  State_120322_Desc = {
    Text = "Уникальный Эффект команды: лимит карт на руке +2, не может складываться с лимитом карт на руке, предоставленным другими колесами судьбы. Наносимый оборудованным персонажем Урон от зарядки серебряного ключа и взрыва ярости увеличивается на <WeaponEffect_Num:[StateArg1]%>. При переключении на позу «Спокойное море» оборудованный персонаж получает <WeaponEffect_Num:[StateArg2]> очков ярости с перезарядкой 3 хода. При переключении на позу «Громовая волна» на всех врагов накладывается <WeaponEffect_Num:[StateArg3]> слоев<DwmofeiKeywords:Ритуал Рождения>, перезарядка 3 хода."
  },
  State_120322_WeaponDesc = {
    Text = "Максимум карт в руке +2, не накладывается на другие максимумы карт, предоставляемые Колесами судьбы. Урон от заряда Серебряного ключа и Вспышки безумия носителя увеличивается на <WeaponEffect_Num:[StateArg1]>. При переключении на состояние «Тихое море» носитель получает <WeaponEffect_Num:[StateArg2]> единиц безумия, время перезарядки 3 хода. При переключении на состояние «Яростные волны» на всех врагов накладывается <WeaponEffect_Num:[StateArg3]> уровней<DwmofeiKeywords:Ритуал Рождения>, время перезарядки 3 хода."
  },
