  },
  State_123109_WeaponDesc = {
    Text = "При первой покупке «Печать пакиа» в «следе от плавления» или при первой покупке товара со скидкой в «пепельных руинах» шанс потратить требуемые чёрные Печать пакиа <WeaponEffect_Num:[StateArg1]%> становится равным 0, действует не более 1 раза за исследование."
  },
  State_123177_Desc = {
    Text = "В начале хода очищается. После достижения 10 уровней, после розыгрыша карты Мушетт немедленно действует, удаляет «Временное Безумие» и добавляет намерение «Человеческий взрыв»."
