  State_123507_Desc = {
    Text = "Уникальное команды: После начала исследования добавить 1 карту «Обратный отсчёт: 5» в колоду: разыграть и взять 1 карту, а следующую карту «Обратный отсчёт» перемешать в сброс. «<DestructionKeywords:Уничтожить>». «Обратный отсчёт: 0»: взять 3 карты, получить 3 единицы арифметики и с вероятностью <WeaponEffect_Num:[StateArg1]%> перемешать «Обратный отсчёт: 5» в сброс. Удержание. «<DestructionKeywords:Уничтожить>»."
  },
  State_123507_WeaponDesc = {
    Text = "После начала исследования добавьте 1 «Обратный отсчёт: 5» в колоду: разыграв, возьмите 1 карту и перемешайте следующую «Обратный отсчёт» в сброс. «<DestructionKeywords:Уничтожить>». «Обратный отсчёт: 0»: возьмите 3 карты, получите 3 единицы арифметики и с вероятностью <WeaponEffect_Num:[StateArg1]%> перемешайте «Обратный отсчёт: 5» в сброс. Удержание. «<DestructionKeywords:Уничтожить>»."
  },
  State_123520_Desc = {
    Text = "Команда уникальна: после первого использования ключевого приказа в каждом ходу существует вероятность <WeaponEffect_Num:[StateArg1]>% вытащить 1 карту «Удар» носителя."
  },
  State_123520_WeaponDesc = {
    Text = "Каждый ход при первом использовании ключевого приказа вероятность <WeaponEffect_Num:[StateArg1]>% вытащить 1 карту «Удар» носителя."
  },
  State_123521_Desc = {
    Text = "Уникальное команды: Базовый Урон вспышки безумия и преследования снаряженца увеличивается на <WeaponEffect_Num:[StateArg1]%>. В этом ходу, после розыгрыша любого «Удар» пробуждённого, Урон от «Удар» снаряженца временно увеличивается на <WeaponEffect_Num:[StateArg2]%> от атакующей силы снаряженца, максимум 8 раз за ход."
  },
  State_123521_WeaponDesc = {
