  },
  State_129612_Desc = {
    Text = "Намерение будет случайным образом выбрано из четырех видов, но не будет повторяться. После освобождения всплеска безумия немедленно переключите намерение. После розыгрыша карты команды получите 1 Уровень <Chapter5_Monster_Fervor3:Безумие>."
  },
  State_129612_Name = {
    Text = "Симфония отголосков"
  },
  State_129625_Desc = {
    Text = "Намерение выбирается случайно из четырёх вариантов без повторений. После применения взрыва безумия намерение немедленно переключается. После розыгрыша командной карты получает 1 слой <Chapter5_Monster_Fervor3:Исступления>. При каждом переключении намерения получает 1 слой «Искажённого пути»."
  },
  State_129625_Name = {
    Text = "Симфония отголосков"
  },
  State_129643_Desc = {
    Text = "Получает 1 слой при каждом переключении намерения. При накоплении 10 слоёв «Искажённого пути» намерение фиксируется на «Безумном пиршестве прорыва», которое невозможно переключить и которое наносит огромный Урон и ослабления."
