  },
  State_129650_Desc = {
    Text = "Уникальное команды: если Носитель является Пробуждённым «Рамона: Неизбывная», Связь, получаемая другими Пробуждёнными при исследовании уровней, увеличивается на <WeaponEffect_Num:[StateArg1]%>, однако сам Носитель не получает Связь."
  },
  State_129650_WeaponDesc = {
    Text = "Если Носитель — Пробуждённый «Рамона: Неизбывная», то при завершении Уровня Связать, полученная другими Пробуждёнными, увеличивается на <WeaponEffect_Num:[StateArg1]%>, но сам Носитель не получает Связать."
  },
  State_129761_Desc = {
    Text = "Измените интерфейс возвращаемого значения интенсивности роста игрока в игре, увеличивая на 1% за каждый Уровень."
