  },
  State_129846_Name = {
    Text = "Счётчик обрыва нитей"
  },
  State_129848_Desc = {
    Text = "Каждый раз, когда [DescArg1] карты покидают размерную трещину, накладывать на них [DescArg2] уровней <BrokenCard:тайное Разрушение>."
  },
  State_129848_Name = {
    Text = "Спектакль марионеток"
  },
  State_129849_Desc = {
    Text = "Создайте копию первой карты команды, разыгранной противником в каждом ходу, и поместите её в размерную трещину. Когда Карта попадает в размерную трещину, присвойте ей <DepleteIconKeywords:расход>. При первом использовании Воспоминания в каждом ходу самая левая Карта будет извлечена и помещена на верх колоды для розыгрыша."
  },
  State_129849_Name = {
    Text = "Перебирая нити судьбы"
  },
  State_129850_Desc = {
    Text = "В размерной трещине, за каждую карту команды, лимит руки игрока уменьшается на 1. Если лимит уже заполнен, при следующем розыгрыше карты «Вековечная сеть» немедленно активируется, после действия очищая размерную трещину и изменяя намерение на «Скорбь, превозмогающий судьбу»."
  },
  State_129850_Name = {
    Text = "Обрыв нитей"
  },
  State_129854_Desc = {
    Text = "В размерной трещине, за каждую карту команды лимит руки игрока уменьшается на 1. Если лимит уже заполнен, при следующем розыгрыше карты «Вековечная сеть» немедленно совершает акцию, после чего очищает размерную трещину и изменяет намерение на «Судьба, внемли сему»."
  },
  State_129854_Name = {
    Text = "Обрыв нитей"
  },
  State_129864_Desc = {
