  State_130498_Name = {
    Text = "Похороны судьбы"
  },
  State_130500_Desc = {
    Text = "В битве с лидером Сопротивление смерти +100%. После активации «сопротивления смерти» в следующем ходу «марионетка» больше не обязана разыгрывать карту команды, а может выбрать одну карту команды из руки."
