  State_130512_Name = {
    Text = "Кукла на нитках"
  },
  State_130517_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: при экипировке и в начале хода случайно активирует один из следующих эффектов: получить <Energy:[Energy:StateArg1]> безумия и наложить <PVPSlowKeywords:замедление> на себя; получить <Energy:[Energy:StateArg3]> безумия; получить <Energy:[Energy:StateArg4]> и [StateArg5] карт <PVPDerivativeCardKeywords_17:«Вдохновение»>."
