  },
  State_131047_Name = {
    Text = "Двойной Призыв"
  },
  State_131048_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После первого разыгрывания «Навыка» за ход наносит <Damage:[Damage:StateArg1]> Урон врагу с <HPAndShieldMin:наименьшим ОЗ и Щитом>."
  },
  State_131048_Name = {
    Text = "Узилище безумия"
  },
  State_131055_Desc = {
    Text = "Количество карт, которые можно взять за ход, уменьшается на 1. Все пробуждающие тела повышают эффективность щита и восстановления жизни на 20%."
