  State_131055_Name = {
    Text = "Причесать волосы"
  },
  State_131056_Desc = {
    Text = "Преобразовать равное количество запоздалого безумия в щит после потери здоровья."
  },
  State_131056_Name = {
    Text = "Вихревой щит"
  },
  State_131058_Desc = {
    Text = "Все пробуждающие тела получают 10 очков базового алиемуса. После освобождения вознесения получаете 1 единицу арифметики, каждое пробуждающее тело может активироваться только 1 раз за ход."
  },
  State_131058_Name = {
    Text = "Натереть щёчки"
  },
  State_131059_Name = {
    Text = "Моск метка улучшения суперспособности"
  },
  State_131061_Desc = {
    Text = "Максимум серебряной энергии и расход ключевого приказа +350. Каждый ход первый ключевой приказ срабатывает 2 раза."
  },
  State_131061_Name = {
    Text = "Прикормка"
  },
  State_131064_Desc = {
    Text = "После освобождения вспышки безумия получаете 1 единицу вычислительной мощности, каждое пробуждающее тело может активироваться только 1 раз за ход."
  },
  State_131064_Name = {
    Text = "Натереть щёчки"
  },
  State_131069_Desc = {
    Text = "Все пробуждающие тела повышают эффективность щита и восстановления жизни на 20%."
  },
  State_131069_Name = {
    Text = "Причесать волосы"
  },
  State_131073_Desc = {
    Text = "Уникальное команды: в начале боя получить безумие, равное <WeaponEffect_Num:[StateArg1]%> базового безумия. Итоговый Урон вспышки безумия снаряженца увеличивается на <WeaponEffect_Num:[StateArg2]%> от базового безумия. При переключении на «Девятый вал» получить временное мастерство царства, равное текущему мастерству царства <WeaponEffect_Num:[StateArg3]%,> с перезарядкой 3 хода."
  },
  State_131073_WeaponDesc = {
    Text = "В начале боя получите [DescArg1] очков Алиемуса. Увеличение итогового урона от вознесения снаряженца на [DescArg2]%. При переключении наПоза «Девятый вал» получите [DescArg3] очков временного мастерства областей, время перезарядки 3 хода (оставшиеся [DescArg4] хода)."
  },
  State_131078_Desc = {
    Text = "Каждый ход первый ключевой приказ срабатывает дважды."
  },
  State_131078_Name = {
    Text = "Прикормка"
  },
  State_131118_Desc = {
    Text = "Каждый раз при получении урона или потере здоровья не может превышать 3% от максимального здоровья."
  },
  State_131118_Name = {
    Text = "Окукливание тысячи нитей"
  },
  State_131123_Desc = {
    Text = "В начале хода очистите. После достижения 10 слоев, при следующем розыгрыше карты немедленно действуйте и переключитесь на следующий замысел, удалите <Chapter5_Monster_Fervor4:Безумие>."
  },
  State_131123_Name = {
    Text = "Временная лихорадка"
  },
  State_131127_Desc = {
    Text = "Поза, связанная с судьбой. Каждый раз, когда Противник разыгрывает 1 карту «Команды», получает 1 Уровень «Временного безумия»."
  },
  State_131127_Name = {
    Text = "Договор оков"
  },
  State_131134_Desc = {
    Text = "После смерти Нефрея получает [DescArg1] Уровень Временного безумия, но теряет 3% макс. здоровья."
  },
  State_131134_Name = {
    Text = "Ворота бездны"
  },
  State_131186_Desc = {
    Text = "После розыгрыша срабатывает дополнительно 1 раз, но получает [DescArg1] ед. урона."
  },
  State_131186_Name = {
    Text = "<ExclamationPointColour:осколки судьбы>"
  },
  State_131188_Desc = {
    Text = "Разыгранные «умения» входят в «размерную трещину» и добавляют «осколки судьбы» ко всем одноимённым умениям, которые удаляются после выхода из размерной трещины. Когда Разлом измерения заполнена, «Сеть отречения» Нефрея после действия очищает размерную трещину, а следующее намерение превращается в мощный взрыв безумия."
  },
  State_131188_Name = {
    Text = "Разлом измерения"
  },
  State_131191_Name = {
    Text = "Когнитивное искажение"
  },
  State_131242_Desc = {
    Text = "Урон, щит, лечение, Огромная Огромная сила, истощение, Урон шупалец, фиксированный яд и фиксированная Контратака, нанесённые этой картой, увеличиваются независимо на 1+[Layer]%."
  },
  State_131242_Name = {
    Text = "Маяк сингулярности β"
  },
  State_131258_Desc = {
    Text = "Нити прядильного колеса вращаются, нарушая ход неверной судьбы. После применения ключевого приказа или разыгрывания карты «Осколки судьбы» снимается 1 Уровень; когда все Уровни сняты, Арахна наносит преследующий Удар «Нити судьбы на своих местах», причиняя огромный Урон. После 3 применений «Окукливание тысячи нитей» врага будет полностью разрушен!"
  },
  State_131258_Name = {
    Text = "Возмущение сети судьбы"
  },
  State_131261_Name = {
    Text = "Арена разрушения"
  },
  State_131351_Desc = {
    Text = "Другие пробуждённые, освободив Вознесение, теряют 1 Уровень, Моск освобождает «Мальстрём! Поток! Снаряд!» для преследования."
  },
  State_131351_Name = {
    Text = "Мальстрём зарядка"
