  },
  State_131749_Desc = {
    Text = "Уникальное команды: после начала исследования перетасуйте 1 карту «Рассчитанная ставка» в колоду для розыгрыша. «Рассчитанная ставка»: расходует 1 арифметику. Перетасуйте все карты команды в руке случайным образом в колоду для розыгрыша, перетасованные карты команды при следующем разыгрывании имеют <WeaponEffect_Num:[StateArg1]%> вероятность дополнительно действовать 1 раз, и за каждую перетасованную карту команды все пробуждённые получают 2 очка Алиемуса. <RetainIconKeywords:Удержание>. <DepleteIconKeywords:расход>. <GuyouKeywords:Начальный>."
  },
  State_131749_WeaponDesc = {
    Text = "После начала исследования перетасуйте 1 карту «Рассчитанная ставка» в колоду для розыгрыша. «Рассчитанная ставка»: расходует 1 арифметику. Перетасуйте все карты команды из руки в колоду для розыгрыша случайным образом, при следующем розыгрыше перетасованных карт есть вероятность <WeaponEffect_Num:[StateArg1]%> дополнительно действовать 1 раз, и за каждую перетасованную карту все пробуждённые тела получают 2 очка безумия. <RetainIconKeywords:Удержание>. <DepleteIconKeywords:расход>. <GuyouKeywords:Начальный>."
  },
