  State_132669_Desc = {
    Text = "Урон, щит, лечение, Огромная Огромная сила, истощение, Урон щупальцами, фиксированное отравление и фиксированная Контратака карт этого пробуждённого тела увеличены, независимый множитель 1+[Layer]%."
  },
  State_132669_Name = {
    Text = "Предначертанное сверхизмерение α"
  },
  State_132840_Name = {
    Text = "Бонус личности командных карт «24» удваивается. После активации взрыва ярости Эффект удвоения бонуса личности отключается до конца хода"
  },
  State_132891_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: При экипировке получить [StateArg1] <StrongEffectKeywords:Усиления>, после «Возвышения» других союзников они получают <PVPOneMeetingKeywords:Раз в жизни>."
  },
  State_132891_Name = {
    Text = "Раздумья под сакурой"
  },
  State_132892_Desc = {
    Text = "·При получении снимает состояние «Единственная встреча» с других союзников, получает эффект Усиления союзников, экипировавших «Мечтания под сенью сакуры», максимум 3 стака.\n·Персонажи, экипировавшие «Мечтания под сенью сакуры», не могут получить «Единственную встречу»."
  },
  State_132892_Name = {
    Text = "Итиго итиэ"
  },
  State_133294_Name = {
    Text = "Багряное Приглашение"
  },
  State_133353_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: после экипировки описания «Удара», «Навыка» и «Взрыва безумия» носителя становятся неразличимы, но каждый раз Урон, щит и исцеление случайно увеличиваются на [StateArg1]%~[StateArg2]%."
  },
  State_133353_Name = {
    Text = "Сказка из трясины"
  },
  State_133354_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Сохраняется после гибели данного Колеса Судьбы. При гибели Носителя и по истечении [Layer] ходов в состоянии смерти другие союзники получают <Heal:[Heal:StateArg1]> <PVPFeatheredSeedsKeyWords:Гинецей> и ОЗ."
  },
  State_133354_Name = {
    Text = "Пусть мир наполнится благоуханием"
  },
  State_133369_Desc = {
    Text = "Следующие [DescArg1] разыгранные командные карты (не Тави) срабатывают 2 раза."
  },
  State_133369_Name = {
    Text = "Ворота Серебряного ключа"
  },
  State_133372_Desc = {
    Text = "Если текущий ход является сверхмерным, срабатывает Эффект сингулярного скачка. «Аннигиляция сингулярности» также может гарантировать срабатывание следующего сингулярного скачка в этом ходу."
  },
  State_133372_Name = {
    Text = "<SingularityKeywords:Сингулярный скачок>"
  },
  State_133391_Desc = {
    Text = "Если количество слоёв этого Состояния больше или равно здоровью цели, все слои «Приговора судьбы» снимаются и цель мгновенно уничтожается. Фиксированный «Приговор судьбы» усиливается бонусом к урону."
  },
  State_133391_Name = {
    Text = "<CutKeywords:Приговор судьбы>"
  },
  State_133395_Desc = {
    Text = "Следующие [Layer] разыгранных командных карт активируют «Перемещение Между измерениями»."
  },
  State_133395_Name = {
    Text = "Перемещение Между измерениями"
  },
  State_133717_Desc = {
    Text = "Текущий владелец — [Layer], все его текущие и будущие карты получат соответствующее свойство (текущее: запечатывание карт)."
  },
  State_133717_Name = {
    Text = "Распространение свойств карты"
  },
  State_133774_Desc = {
    Text = "Каждый слой увеличивает итоговый эффект урона, наносимого этой картой, повышения Силы и урона щупалец, фиксированного Яда, фиксированной Контратаки на 2%; итоговый эффект фиксированного Щита, фиксированного лечения ОЗ, Силы▼ увеличивается на 1%. Карты с «Маяком сингулярности» не могут активировать «Пространственный скачок»."
  },
  State_133774_Name = {
    Text = "<SingularityKeywords1:Маяк сингулярности>"
  },
  State_133775_Desc = {
    Text = "Каждый слой увеличивает итоговый эффект урона всех карт Пробуждённых, повышения Силы и урона щупалец, фиксированного Яда, фиксированной Контратаки на 2%; итоговый эффект фиксированного Щита, фиксированного лечения ОЗ, Силы▼ увеличивается на 1%."
  },
  State_133775_Name = {
    Text = "<SingularityKeywords2:Трёхгранная призма сингулярности>"
  },
  State_133961_Desc = {
    Text = "Уникальное команды: после начала исследования добавляет в колоду карту «Весточка весны»: Расход арифметики 1, получить <WeaponEffect_Num:[StateArg1]> Ключесвет; после разыгрывания навсегда превращается в «Полное цветение сакуры»: Расход арифметики 1, получить <WeaponEffect_Num:[StateArg2]> Ключесвет; после разыгрывания навсегда превращается в «Метель лепестков»: Расход арифметики 1, получить <WeaponEffect_Num:[StateArg3]> Ключесвет; после разыгрывания навсегда превращается в «Единственная встреча»: Расход арифметики 1, выбрать 1 из 3 случайных разблокированных Зовов, немедленно активировать его 2 раза; после разыгрывания навсегда превращается в «Весточка весны». Все эти карты обладают «Удержанием»."
  },
  State_133961_WeaponDesc = {
    Text = "После начала исследования создаёт карту «Весточка весны» и помещает в колоду: стоимость вычислений 1, получить <WeaponEffect_Num:[StateArg1]> ед. энергии серебряного ключа, после розыгрыша навсегда превращается в «Полное цветение»: стоимость вычислений 1, получить <WeaponEffect_Num:[StateArg2]> ед. энергии серебряного ключа, после розыгрыша навсегда превращается в «Мальстрём лепестков»: стоимость вычислений 1, получить <WeaponEffect_Num:[StateArg3]> ед. энергии серебряного ключа, после розыгрыша навсегда превращается в «Итиго итиэ»: стоимость вычислений 1, из 3 случайных разблокированных приказов ключа выбрать 1 и немедленно активировать с двойным эффектом, после розыгрыша навсегда превращается в «Весточку весны». Все эти карты обладают свойством «Сохранение»."
  },
  State_133994_Desc = {
    Text = "Итоговый эффект урона всех командных карт Пробуждённых, повышения Силы и урона щупалец, фиксированного Яда, фиксированной Контратаки увеличивается на [DescArg1]%, а эффект фиксированного Щита, фиксированного лечения ОЗ, Силы▼ увеличивается на [DescArg2]%."
  },
  State_133994_Name = {
    Text = "Трёхгранная призма сингулярности"
  },
  State_133998_Desc = {
    Text = "Эффект урона, щита и изменения силы этой карты увеличивается на [DescArg2]%, итоговый Эффект урона щупальцами, восстановления здоровья, фиксированного отравления и фиксированной контратаки увеличивается на [DescArg1]%. Удаляется в конце хода или после розыгрыша."
  },
  State_133998_Name = {
