  State_133999_Desc = {
    Text = "Каждый слой увеличивает итоговый эффект урона, наносимого этой картой, повышения Силы и урона щупалец, фиксированного Яда, фиксированной Контратаки на 2%; итоговый эффект фиксированного Щита, фиксированного лечения ОЗ, Силы▼ увеличивается на 1%. Снимается в конце хода или после разыгрывания."
  },
  State_133999_Name = {
    Text = "<TempPowerKeywords:Временное Усиление>"
