  State_134100_Desc = {
    Text = "При получении смертельного урона в этом бою воскресает, восстанавливает [Layer] ед. здоровья и даёт всем пробуждённым [StateArg1] ед. ярости и [DescArg1] ед. временного урона щупальцами. Нельзя рассеять."
