  State_134191_Desc = {
    Text = "Уникально для отряда: после начала исследования замешивает 1 карту «Личное время отдыха» в колоду вытягивания. «Личное время отдыха»: затраты 1 ед. вычислительной мощности. Временный крит. Урон +<WeaponEffect_Num:[StateArg1]%>. <RetainIconKeywords:Сохраняется>. <DepleteIconKeywords:Расходуется>."
  },
  State_134191_WeaponDesc = {
    Text = "После начала исследования замешивает 1 карту «Личное время отдыха» в колоду вытягивания. «Личное время отдыха»: затраты 1 ед. вычислительной мощности. Временный крит. Урон +<WeaponEffect_Num:[StateArg1]%>. <RetainIconKeywords:Сохраняется>. <DepleteIconKeywords:Расходуется>."
  },
  State_134195_Desc = {
    Text = "Количество слоёв фиксированного отравления, фиксированной контратаки и фиксированного Приговора судьбы этой карты увеличено, независимый множитель 1+[Layer]%."
  },
  State_134195_Name = {
    Text = "Огромная Огромная сила трёх фаз α1"
