  State_134227_Desc = {
    Text = "Нити, выведенные Арахной, плетущей судьбу. Максимальный [DescArg1] Уровень, может быть израсходован Взрывом Алиемуса для освобождения преследования «Бесконечные нити». «Плетение сетей сетей судьбы» переносится в следующий бой."
  },
  State_134227_Name = {
    Text = "<SilkKeywords:Плетельщица судеб>"
  },
  State_134231_Desc = {
    Text = "Уникально для отряда: щит, создаваемый носителем, повышается на <WeaponEffect_Num:[StateArg1]%>. При нанесении носителем «Преследование» + <WeaponEffect_Num:[StateArg2]%> временного усиления, срабатывает до 5 раз за ход. При каждом срабатывании «Перемещения Между измерениями» носитель получает <WeaponEffect_Num:[StateArg3]> ед. безумия."
  },
  State_134231_WeaponDesc = {
    Text = "Щит, создаваемый носителем, повышается на <WeaponEffect_Num:[StateArg1]%>. При нанесении носителем «Преследование» + <WeaponEffect_Num:[StateArg2]%> временного усиления, срабатывает до 5 раз за ход. При каждом срабатывании «Перемещения Между измерениями» носитель получает <WeaponEffect_Num:[StateArg3]> ед. безумия."
  },
  State_134237_Desc = {
    Text = "Нити, выведенные Арахной, плетущей судьбу, максимальный [DescArg1] Уровень, могут быть израсходованы взрывом безумия для освобождения «<DerivativeCardKeywords_144:Бесконечные нити>» преследования. «Плетение сетей сетей судьбы» наследуется в следующий бой."
  },
  State_134237_Name = {
    Text = "Плетельщица судеб"
  },
  State_134240_Desc = {
    Text = "В следующие [Layer] раз «Вечное ткачество» создаст дополнительные «Путеводные нити», помещая их в колоду для розыгрыша и сброс."
  },
  State_134240_Name = {
