  State_134262_Name = {
    Text = "Уединённый полуденный Дрёма"
  },
  State_134285_Desc = {
    Text = "Если количество слоёв этого Состояния больше или равно здоровью цели, все слои «Приговора судьбы» снимаются и цель мгновенно уничтожается. Фиксированный «Приговор судьбы» усиливается бонусом к урону."
  },
  State_134285_Name = {
    Text = "Приговор судьбы"
  },
  State_134313_Desc = {
    Text = "Уникально для отряда: щит, создаваемый носителем, повышается на <WeaponEffect_Num:[StateArg1]%>. При нанесении носителем «Преследование» + <WeaponEffect_Num:[StateArg2]%> временного усиления, срабатывает до 5 раз за ход."
  },
  State_134313_WeaponDesc = {
    Text = "Щит, создаваемый носителем, повышается на <WeaponEffect_Num:[StateArg1]%>. При нанесении носителем «Преследование» + <WeaponEffect_Num:[StateArg2]%> временного усиления, срабатывает до 5 раз за ход."
  },
  State_134384_Desc = {
