  State_134384_Name = {
    Text = "Перемещение Между измерениями"
  },
  State_134389_Desc = {
    Text = "Итоговый эффект урона этой карты, повышения Силы и урона щупалец, фиксированного Яда, фиксированной Контратаки увеличивается на [DescArg1]%, а эффект фиксированного Щита, фиксированного лечения ОЗ, Силы▼ увеличивается на [DescArg2]%. Карты с «Маяком сингулярности» не могут быть скопированы в «Ультра пространство»."
  },
  State_134389_Name = {
    Text = "<SingularityKeywords:Маяк сингулярности [DescArg2]>"
  },
  State_134391_Desc = {
    Text = "Срабатывает после первой разыгранной командной карты каждый ход: после розыгрыша командной карты её временная оригинальная Копия помещается в сверхмерное пространство. Во время сверхмерного хода этот Эффект не активируется."
  },
  State_134391_Name = {
