  },
  State_138824_Desc = {
    Text = "Сияющая жизнь воспевает свободу, гремит победным маршем — может быть поглощена Вознесением Саи для усиления его эффекта. Это состояние накапливается не более 4 слоёв и сохраняется после окончания боя."
  },
  State_138824_Name = {
    Text = "<KaiHuajishu1:Гинецей>"
  },
  State_139039_Desc = {
    Text = "Финальный Эффект следующего Вознесения этого Пробуждённого в текущем ходу: Урон, фиксированный Щит, фиксированное Лечение ОЗ, фиксированная Сила, Сила▼, Усиление урона шупалец, фиксированный Яд, фиксированная Контратака — повышается на [Layer]%."
  },
  State_139039_Name = {
    Text = "<BreedingKeywords2:Фиеста размножения>"
  },
  State_139687_Desc = {
    Text = "Сияющая жизнь воспевает свободу, гремит победным маршем — может быть поглощена Вознесением Саи для усиления его эффекта. Это состояние накапливается не более 4 слоёв и сохраняется после окончания боя."
