  State_139687_Name = {
    Text = "<KaiHuajishu:Гинецей>"
  },
  State_139688_Desc = {
    Text = "Уникальное команды: лимит арифметики +1, эффекты одного типа не суммируются. За каждые 10 ед. основного алиемуса носителя фиксированный эффект <Corrosion:Коррозии> повышается на <WeaponEffect_Num:[StateArg1]%>, а наносимое Слияние Зародыша повышается на <WeaponEffect_Num:[Float:StateArg2]%>."
  },
  State_139688_WeaponDesc = {
    Text = "Лимит арифметики +1, эффекты одного типа не суммируются. За каждые 10 ед. основного алиемуса носителя фиксированный эффект <Corrosion:Коррозии> повышается на <WeaponEffect_Num:[StateArg1]%>, а наносимое Слияние Зародыша повышается на <WeaponEffect_Num:[Float:StateArg2]%>."
  },
  State_139689_Desc = {
    Text = "Уникальное команды: После использования «Багрового горнила» носитель получает алиемус, равный <WeaponEffect_Num:[StateArg1]%> Основного алиемуса, перезарядка 3 хода."
  },
  State_139689_WeaponDesc = {
    Text = "После использования «Багрового горнила» Носитель получает Алиемус в размере <WeaponEffect_Num:[StateArg1]%> от Базового Алиемуса. Перезарядка: 3 хода."
  },
  State_139977_Desc = {
    Text = "Если в этом раунде разыгран «Удар», то «Удар» получает + [DescArg1]% пробивания урона; иначе в конце раунда +[Layer] Барьер."
  },
  State_139977_Name = {
    Text = "Звёздный зверь"
  },
  State_140063_Desc = {
    Text = "Это «расписка» за вычислительную мощность, взятую в долг у следующего хода. В начале следующего хода будет вычтено [Layer] выч. мощности, нельзя рассеять."
  },
  State_140063_Name = {
    Text = "Долговая расписка"
  },
  State_140068_Desc = {
