  },
  State_140068_Name = {
    Text = "Прозрение"
  },
  State_140135_Desc = {
    Text = "За каждый имеющийся слой финальный Эффект следующего Вознесения этого Пробуждённого в текущем ходу: Урон, фиксированный Щит, фиксированное Лечение ОЗ, фиксированная Сила, Сила▼, Усиление урона шупалец, фиксированный Яд, фиксированная Контратака — повышается на 1%."
  },
  State_140135_Name = {
    Text = "<BreedingKeywords2:Фиеста размножения>"
  },
  State_140186_WeaponDesc = {
    Text = "Все атаки при китовом прыжке наносят на 1 раз больше урона."
  },
  State_140454_Desc = {
    Text = "Уникально для отряда: за каждый 1% выпадения чёрных печатей с самого носителя, его судьбоносного круга и тайного договора после боя восстанавливается <WeaponEffect_Num:[StateArg1]%> макс. здоровья; в конце каждого хода Эффект восстановления уменьшается на 30%, каждый случай рассчитывается независимо. После применения «Восприятия» в «Руинах пепла» обновление текущих «Руин пепла» не требует затрат чёрных печатей."
  },
  State_140454_WeaponDesc = {
    Text = "Уникально для отряда: после окончания боя восстанавливает <WeaponEffect_Num:[DescArg2]%> макс. здоровья ([DescArg1]), в конце каждого раунда этот Эффект восстановления снижается на 30%. После активации «Восприятия» в «Руинах пепла» обновление в текущих «Руинах пепла» не требует затрат чёрных печатей."
  },
  State_140456_WeaponDesc = {
    Text = "Удалить постоянно после применения."
  },
  State_140458_Desc = {
