  State_140728_Desc = {
    Text = "В начале каждого хода получает 1 слой Голода; при нанесении незаблокированного Урона получает Щит равный 2% ([DescArg1]) от макс. ОЗ, максимальное количество слоёв Адаптации увеличивается до 75."
  },
  State_140728_Name = {
    Text = "Защита пищи"
  },
  State_140730_Desc = {
    Text = "После розыгрыша Командной карты накладывает 10 слоёв <AdaptKeywords:Адаптации> на карты принадлежащего Пробуждённого во всех местах, а карты других Пробуждённых теряют 5 слоёв <AdaptKeywords:Адаптации>. Каждый слой <AdaptKeywords:Адаптации> снижает итоговый эффект Урона, Силы, Урона щупалец, фиксированного Яда, фиксированной Контратаки, Щита, Лечения ОЗ и Силы▼ карты на 1%. Максимум [DescArg1] слоёв."
  },
  State_140730_Name = {
    Text = "Мимикрия"
  },
  State_140838_Desc = {
    Text = "Урон, нанесённый в этом ходу, снижается на [Layer]%."
  },
  State_140838_Name = {
    Text = "Стена мрака, затмевающая солнце"
  },
  State_140839_Desc = {
    Text = "В этом ходу Итоговый урон всех Пробуждённых повышается на [Layer]%."
  },
  State_140839_Name = {
    Text = "Охотничий эскорт"
  },
  State_140856_Desc = {
    Text = "Пробуждённый не может действовать; в конце хода снимается 1 слой Вмешательства в сознание. После снятия всех слоёв следующее Вознесение этого Пробуждённого считается Сверхвознесением; если Сверхвознесение уже было использовано, возвращается 100% Основного алиемуса."
  },
  State_140856_Name = {
    Text = "<Yishiganshe:Вмешательство в сознание>"
  },
  State_140860_Desc = {
    Text = "Пробуждённый не может действовать; в конце хода снимается 1 слой Вмешательства в сознание. После снятия всех слоёв следующее Вознесение этого Пробуждённого считается Сверхвознесением; если Сверхвознесение уже было использовано, возвращается 100% Основного алиемуса."
