  },
  State_140861_Desc = {
    Text = "Следующее Вознесение считается Сверхвознесением; если Сверхвознесение уже было использовано, возвращается 100% Основного алиемуса."
  },
  State_140861_Name = {
    Text = "Грёзы страны чудес"
  },
  State_140873_Desc = {
    Text = "Каждый слой снижает итоговый эффект Урона, Силы, Урона щупалец, фиксированного Яда, фиксированной Контратаки, Щита, Лечения ОЗ и Силы▼ этой карты на 1%. Максимум [DescArg1] слоёв."
