  },
  State_141468_Desc = {
    Text = "При достижении 5 слоёв Голода в конце хода расходуются все слои Голода, намерение переключается на мощную атаку и получается Сила."
  },
  State_141468_Name = {
    Text = "<HungerKeywords:Голод>"
  },
  State_141504_Desc = {
    Text = "Можно накопить не более 3 останков. При достижении предела следующий «Празднество Некромантии» сможет их поглотить и усилить свой эффект. Останки переносятся в следующий бой."
  },
  State_141504_Name = {
    Text = "Обломки"
  },
  State_141950_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке и в конце хода <PVPDiscoveryKeyWords:Обнаруживает> [StateArg1] «навыков» с <PVPVoidKeywords:Ускользанием> и помещает их в руку."
  },
  State_141950_Name = {
