  },
  State_141991_Desc = {
    Text = "Урон, Щит, лечение от Вознесения данного Пробуждённого, а также накладываемые им Сила, Истощение, Урон щупалец, Яд, Контратака, Приговор судьбы, фиксированный Яд, фиксированная Контратака, фиксированный Приговор судьбы — все эффекты повышаются на [Layer]%."
