  },
  State_141992_Desc = {
    Text = "Урон, Щит, лечение от карт данного Пробуждённого, а также накладываемые ими Сила, Истощение, Урон щупалец, Яд, Контратака, Приговор судьбы, фиксированный Яд, фиксированная Контратака, фиксированный Приговор судьбы — все эффекты повышаются на [Layer]%."
