  },
  State_141993_Desc = {
    Text = "Урон, Щит, лечение от Командных карт данного Пробуждённого, а также накладываемые ими Сила, Истощение, Урон щупалец, Яд, Контратака, Приговор судьбы, фиксированный Яд, фиксированная Контратака, фиксированный Приговор судьбы — все эффекты повышаются на [Layer]%."
