  State_141994_Desc = {
    Text = "После разыгрывания карты, после Вознесения: нанесённый Урон, получение Щита, лечение, наложение Силы, Истощения, Урона щупалец, Яда, Контратаки, Приговора судьбы, фиксированного Яда, фиксированной Контратаки, фиксированного Приговора судьбы."
