  State_143573_Desc = {
    Text = "Раб-измождь — это карты усиления Понтоса, включающие «Измождь-налётчика», «Измождь-губителя» и «Измождь-убийцу», всего 3 вида. При создании постоянного «Раба-измождя», если количество постоянных «Рабов-измождей» превышает 6, случайный постоянный «Раб-измождь» улучшается до «Слияния измождей» с расходом арифметики +1, но срабатывает дополнительно 1 раз; «Слияние измождей» считается за 2 «Раба-измождя» в колоде. Если все «Рабы-изможди» уже улучшены, положите в руку 1 «Улучш. озарение» с <DestructionKeywords:Уничтожить>."
  },
  State_143573_Name = {
    Text = "Раб-измождь"
  },
  State_143578_Desc = {
    Text = "В этом ходу каждый раз при получении активного урона поместите [Layer] карт(у) <PVPDerivativeCardKeywords_30:«Кошмарный плен»> в Руку."
