  State_143595_Name = {
    Text = "Танец чёрного лебедя"
  },
  State_143597_Desc = {
    Text = "Уникальное команды: Сила▼ эффект, наносимый Носителем, повышается на <WeaponEffect_Num:[StateArg1]%>. При переключении в стойку «Девятый вал» Временный крит. урон повышается на величину, равную <WeaponEffect_Num:[StateArg1]%> от базового крит. урона, перезарядка 3 хода."
  },
  State_143597_WeaponDesc = {
    Text = "Сила▼ эффект, наносимый Носителем, повышается на <WeaponEffect_Num:[StateArg1]%>. После переключения в стойку «Девятый вал» Временный крит. урон повышается на <WeaponEffect_Num:[DescArg1]%>, перезарядка 3 хода."
  },
  State_143598_Desc = {
    Text = "Уникальное команды: Сила▼ эффект, наносимый Носителем, повышается на <WeaponEffect_Num:[StateArg1]%>, каждое убийство врага увеличивает фиксированное Лечение Алиемуса Носителя в конце хода исследования на 2 единицы, максимум <WeaponEffect_Num:[StateArg2]> раз. После переключения в стойку «Девятый вал» Временный крит. урон повышается на величину, равную <WeaponEffect_Num:[StateArg1]%> от базового крит. урона, перезарядка 3 хода."
  },
  State_143598_WeaponDesc = {
    Text = "Сила▼ эффект, наносимый Носителем, повышается на <WeaponEffect_Num:[StateArg1]%>, каждое убийство врага увеличивает фиксированное Лечение Алиемуса Носителя в конце хода исследования на 2 единицы, максимум <WeaponEffect_Num:[StateArg2]> раз. После переключения в стойку «Девятый вал» Временный крит. урон повышается на <WeaponEffect_Num:[DescArg1]%>, перезарядка 3 хода."
  },
  State_143683_Desc = {
    Text = "Преследование этого Пробуждённого запечатано и не может быть использовано, Запечатывание снимается через [Layer] ход(а)."
  },
  State_143683_Name = {
    Text = "<Seal1:Преследование Запечатывание>"
  },
  State_144381_Desc = {
    Text = "Невозможно совершить Действие, осталось [DescArg1] ходов."
  },
  State_144381_Name = {
    Text = "<Yishiganshe:Вмешательство в сознание>"
  },
  State_144441_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: при гибели союзника сам получает <Energy:[Energy:StateArg1]> Алиемус. При возрождении союзника тот получает <Energy:[Energy:StateArg2]> Алиемус. Эффект получения Алиемус действует только если Алиемус цели не заполнен; осталось [Layer] применений, после исчерпания которых Колесо Судьбы уничтожается."
  },
  State_144441_Name = {
    Text = "Синхронизация душ"
  },
  State_144494_Desc = {
    Text = "Всего 7 видов эффектов, включая: вытянуть 8 карт, получить 6 единиц Арифметики, получить Ключесвет, все Пробуждённые получают фиксированный Алиемус, получить силу, временно снизить силу всех врагов, временно повысить Усиление урона."
  },
  State_144494_Name = {
    Text = "<Blessing:Подарок>"
  },
  State_144508_Desc = {
    Text = "«Плата» бывает 3 видов: «Упущенный шанс», «Медоточивые речи», «Скрытая угроза».\n«Упущенный шанс»: через 2 хода получить эффект «Дара».\n«Медоточивые речи»: эффект «Дара» уменьшается на 50%.\n«Скрытая угроза»: применяет к себе случайный 1 из различных эффектов: Слабость на 2 хода, Хрупкость на 2 хода, Травматизация на 2 хода, Яд равный 1% от собственного макс. ОЗ, 2 уровня Пустоты, 2 случайным картам в руке применяет 1 уровень Замедления, создаёт 2 временные карты симптома (не переносятся между боями) и помещает их на верх Стопки добора."
  },
  State_144508_Name = {
    Text = "<BlessingNegativeEffect:Плата>"
  },
  State_144519_Desc = {
    Text = "Тестовая переменная, обновляется после начала хода или после разыгрывания Карты. В данный момент имеется [Layer] духов."
  },
  State_144519_Name = {
    Text = "Духи Нового Хаоса"
  },
  State_145228_Name = {
    Text = "<WormGrowth:Сытость>"
  },
  State_145229_Desc = {
    Text = "Ты тоже часть Милости~. Может быть потреблено Вознесением Карабу для получения усиления. Данное состояние накапливается не более 5 уровней. Не очищается после окончания боя."
  },
  State_145229_Name = {
    Text = "<SacrificialMark:Подношение>"
  },
  State_145436_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Урон от «удара» увеличивается на [DescArg1]%, после каждого «удара» Урон дополнительно увеличивается на [StateArg2]%, максимум до [StateArg3]%."
  },
  State_145436_Name = {
    Text = "Неутолимый голод"
  },
  State_145437_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: при экипировке получает [StateArg2] стаков <EnergyStorageKeywords:Заряда>, Урон от «ударить» повышается на [StateArg1]% и становится <PVPPunctureDamagewords:Прокалывающим уроном>."
  },
  State_145437_Name = {
    Text = "Падение небес"
  },
  State_145456_Desc = {
    Text = "При выборе цели игнорирует Насмешку, Скрытность и Фиксацию. Если несколько целей соответствуют условиям, приоритет отдаётся Пробуждённому, стоящему первым."
  },
  State_145456_Name = {
    Text = "Наименьшее ОЗ и Щит"
  },
  State_145457_Desc = {
    Text = "При выборе цели игнорирует Насмешку, Скрытность и Фиксацию. Если несколько целей соответствуют условиям, приоритет отдаётся Пробуждённому, стоящему первым."
  },
  State_145457_Name = {
    Text = "Наибольшее ОЗ и Щит"
  },
  State_145495_Desc = {
    Text = "Эта карта разыграна двойным выстрелом."
  },
  State_145495_Name = {
    Text = "<CardKeyWord:Двойной выстрел>"
  },
  State_145554_Desc = {
    Text = "Уникальное команды: после начала исследования добавляет 1 карту <Falltospace1[StateArg3]:«Шаги по земле»> в колоду. «Шаги по земле»: стоимость 0 Арифметики. Наносит всем врагам фиксированную <Corrosion:Коррозию> в размере <WeaponEffect_Num:[StateArg1]%> АТК Носителя и <WeaponEffect_Num:[Float:StateArg4]%> его Макс. ОЗ, добавляет <ErosionColorInkKeywords:Искривление восприятия> к Командным картам других Пробуждённых на всех позициях и замешивает 1 карту <Falltospace2[StateArg3]:«Падение вверх»> в Стопку добора. <RetainIconKeywords:Удержание>. <DepleteIconKeywords:Расход>."
  },
  State_145554_Name = {
    Text = "Падение вверх"
  },
  State_145554_WeaponDesc = {
    Text = "После начала исследования добавляет 1 карту <Falltospace1[StateArg3]:«Шаги по земле»> в колоду. «Шаги по земле»: стоимость 0 Арифметики. Наносит всем врагам фиксированную <Corrosion:Коррозию> в размере <WeaponEffect_Num:[StateArg1]%> АТК Носителя и <WeaponEffect_Num:[Float:StateArg4]%> его Макс. ОЗ, добавляет <ErosionColorInkKeywords:Искривление восприятия> к Командным картам других Пробуждённых на всех позициях и замешивает 1 карту <Falltospace2[StateArg3]:«Падение вверх»> в Стопку добора. <RetainIconKeywords:Удержание>. <DepleteIconKeywords:Расход>"
  },
  State_145572_Desc = {
