  State_145709_Desc = {
    Text = "Каждый уровень увеличивает макс. ОЗ на величину, равную 10% Тела Карабу. «Сытость» накапливается максимум до 50 уровней. Если при получении этого Состояния лимит уже достигнут, каждый лишний уровень вместо этого восстанавливает ОЗ в 3-кратном эквивалентном размере. В каждой битве не с боссом можно получить не более 10 уровней «Пира». Не снимается по окончании боя."
  },
  State_145709_Name = {
    Text = "<WormGrowth:Сытость>"
  },
  State_145710_Desc = {
    Text = "Ты тоже часть Милости~. Может быть потреблено Вознесением Карабу для получения усиления. Данное состояние накапливается не более 5 уровней. Не очищается после окончания боя."
  },
  State_145710_Name = {
