  },
  State_146041_Desc = {
    Text = "Этот Пробуждённый чувствует себя оторванным от мирской суеты.\n·До конца хода не может совершать никаких Действий, получает снижение урона на 99%; если у цели нет Сопротивления, цель получает Сопротивление.\n·По окончании эффекта наносит <Damage:[Layer]> Чистого урона всем союзникам.\n·Если в момент применения у цели есть Сопротивление, эффект «Морочить» немедленно заканчивается, а урон по цели удваивается."
  },
  State_146041_Name = {
