    Text = "Каждый раз, когда вы освобождаете вспышку безумия, получаете одну карту, способную наложить [Arg1] очков яда \"Токсичное Вливание\". В конце хода, если у вас на руках каждые 3 карты \"Токсичное Вливание\", вы можете создать одну карту, вызывающую яд \"Высвобождение Токсинов\"."
