  State_20028_Desc = {
    Text = "<ProficientInRealmsIconKeywords:Мастерство границ> увеличивается на 100. За каждую разыгранную карту эмбриональная фузия +10, если здоровье ниже 25%, увеличение составляет 20, максимальное количество активаций за ход - 10 раз."
