    Text = "<PVPWeaponKeywords:Колесо Судьбы>: По окончании хода другие союзники получают <Block:[Block:StateArg1]> щит."
  },
  State_20613_Name = {
    Text = "Край небытия"
  },
  State_20614_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Ход завершен, получить [StateArg1] временную <PVPRetaliateIconKeywords:Контратака>."
  },
  State_20614_Name = {
    Text = "Перегрев ядра"
  },
  State_20615_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Первая «АТК» каждый ход дополнительно наносит [StateArg1] урона, <PVPMethysisKeywords:Яд>."
  },
  State_20615_Name = {
    Text = "горькое проклятие"
  },
  State_20616_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: В конце хода получает <Energy:[Energy:StateArg1]> безумия."
  },
  State_20616_Name = {
    Text = "Весна в Якутске"
  },
  State_20617_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: По завершении хода получите <Block:[Block:StateArg1]> щит."
  },
  State_20617_Name = {
    Text = "Изгнание"
  },
  State_20618_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: Перед «Вознесением» обе стороны сбрасывают все карты и берут равное количеству сброшенных карт +1 карт."
  },
  State_20618_Name = {
    Text = "Шоу чудо-фокусов"
  },
  State_20619_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке получаете <Energy:[Energy:StateArg1]> Алиемус. Когда союзник Пробуждённый использует «Вознесение», вы получаете <DelayKeywords:Задержка>:  <Energy:[Energy:StateArg2]> Алиемус."
  },
  State_20619_Name = {
    Text = "Ода Царю-Богу"
  },
  State_20620_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>：Максимум карт в руке + [StateArg2]. В конце хода получите копию случайных [StateArg1] карт «Умение» из руки。"
  },
  State_20620_Name = {
    Text = "момент встречи"
  },
  State_20621_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: Перед «Вознесением» даёт себе <StrengthenKeywords:Усиление> и <ReinforceKeywords:укрепление>."
  },
  State_20621_Name = {
    Text = "Преодолеть боль"
  },
  State_20622_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: В конце хода получает <Energy:[Energy:StateArg1]> безумия, потребляет всю оставшуюся арифметику, за каждую потреблённую 1 арифметику получаемое безумие увеличивается на [StateArg3]."
  },
  State_20622_Name = {
    Text = "Рождение втайне"
  },
  State_20623_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: после «Вознесения» вытяните [StateArg1] карту."
  },
  State_20623_Name = {
    Text = "Видение"
  },
  State_20624_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: При \"Вознесении\" вытяните [StateArg1] \"Навык\", положите [StateArg2] их копии в руку."
  },
  State_20624_Name = {
    Text = "Момент фортуны"
  },
  State_20625_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: «Вознесение» <DelayKeywords:Задержка>: восстанавливает всем союзникам <Heal:[Heal:StateArg1]> жизни."
  },
  State_20625_Name = {
    Text = "Притча о чревоугодии"
  },
  State_20626_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: Усиление урона «ударить» на [StateArg1] %, и даёт себе <ReinforceKeywords:укрепление>."
  },
  State_20626_Name = {
    Text = "Несгибаемая воля"
  },
  State_20627_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После завершения хода восстанавливается <Heal:[Heal:StateArg1]> жизни всем союзникам."
  },
  State_20627_Name = {
    Text = "Благословление"
  },
  State_20628_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После «Вознесения» даёт другим союзникам <Energy:[Energy:StateArg1]> Алиемус, избыточный Алиемус возвращается к экипировщику в половинном размере."
  },
  State_20628_Name = {
    Text = "обязанности"
  },
  State_20629_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Урон, лечение и эффекты щита от «Вознесение» увеличиваются на [StateArg1]%."
  },
  State_20629_Name = {
    Text = "Во имя розы"
  },
  State_20630_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: В конце хода вы получаете <Block:[Block:StateArg1]> щит и <Energy:[Energy:StateArg2]> безумие."
  },
  State_20630_Name = {
    Text = "В память о зиме"
  },
  State_20631_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: «Ударить» <PVPVulnerabilityIconKeywords:Уязвимый> цель. При экипировке и в конце хода получите [StateArg1] уровней <EnergyStorageKeywords:Готовьсь!>."
  },
  State_20631_Name = {
    Text = "критическая точка"
  },
  State_20632_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: максимальное количество карт на руке +[StateArg1]."
  },
  State_20632_Name = {
    Text = "Спираль памяти"
  },
  State_20633_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: При первом получении активной атаки врага за ход наносит ему [StateArg1] урона, <PVPEntanglementKeywords:Опутывание>."
  },
  State_20633_Name = {
    Text = "Бледный потомок"
  },
  State_20634_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: Урон, лечение и щиты от «Удар», «Умение», «Возвышение» увеличиваются на [DescArg1]%, <PVPGrowthKeywords:Рост> [StateArg2]%."
  },
  State_20634_Name = {
    Text = "Солнцепадение"
  },
  State_20635_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: \"вспышка безумия\", передает всем союзникам <StrengthenKeywords:Усиление>."
  },
  State_20635_Name = {
    Text = "Могущество благочестия"
  },
  State_20636_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: в конце хода получите одну карту <PVPDerivativeCardKeywords_2:«Иллюзия»>. Когда в руке будет две карты <PVPDerivativeCardKeywords_2:«Иллюзия»>, объедините их в одну карту <PVPDerivativeCardKeywords_12:«Крохотное желание»>."
  },
  State_20636_Name = {
    Text = "Выдержка"
  },
  State_20637_Desc = {
    Text = "<PVPWeaponKeywords:колесо судьбы>: В конце хода добавьте [StateArg1] карт(ы) <PVPDerivativeCardKeywords_11:\"неравный обмен\"> в колоду."
  },
  State_20637_Name = {
    Text = "В знании — жизнь"
  },
  State_20639_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: в конце хода Носитель наносит [StateArg1] Урон врагу с <HPAndShieldMax:наибольшими ОЗ и Щитом>, накладывая <PVPMethysisKeywords:Яд>."
  },
  State_20639_Name = {
    Text = "Дар увядания"
  },
  State_20640_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке и в начале раунда наносит всем врагам <Damage:[Damage:StateArg1]> <PVPBleedingKeywords:кровотечение> Урон, за каждую карту в руке у цели <PVPBleedingKeywords:кровотечение> Урон +[StateArg2]."
  },
  State_20640_Name = {
    Text = "Кровавое пиршество"
  },
  State_20641_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: после смерти предоставляет [StateArg1] уровней <PVPProtectiveKeywords:Барьер> другим союзникам."
  },
  State_20641_Name = {
    Text = "Анализ смерти"
  },
  State_20642_Desc = {
    Text = "<PVPHoldingKeywords:В руке>: Каждый раз, когда вы разыгрываете карту, эта Карта становится другой случайной «судьбой» и её расход арифметики уменьшается на 1."
  },
  State_20642_Name = {
    Text = "душа рождается"
  },
  State_20643_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После «Вознесения» получает [StateArg1] Арифметика, <DelayKeywords:Задержка>: вычитает [StateArg2] Арифметика."
  },
  State_20643_Name = {
    Text = "синдром амнезии"
  },
  State_20644_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке нанесите себе [StateArg2] урона, <PVPEntanglementKeywords:Опутывание>. За каждого погибшего союзника <StrongEffectKeywords:Усиление> + [StateArg1]."
  },
  State_20644_Name = {
    Text = "Ценнейший экспонат"
  },
  State_20645_Name = {
    Text = "Рюкзак авантюриста"
  },
  State_20646_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: «ударить» Урон увеличивается на [StateArg1] %, «Вознесение» восстанавливает себе <Heal:[Heal:StateArg2]> жизни."
  },
  State_20646_Name = {
    Text = "Колыбельная пожирания"
  },
  State_20647_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: \"Вознесение\" добавляет [StateArg1] карту <PVPDerivativeCardKeywords_11:\"неравный обмен\"> в руку."
  },
  State_20647_Name = {
    Text = "Под проливным дождём"
  },
  State_20648_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: В начале хода получите положительный <PVPWonderfulEffectKeywords:Чудесный Эффект>, при первом использовании \"Призыв\" врагом каждый ход добавьте [StateArg1] карт \"Чудесное зрелище\" в руку."
  },
  State_20648_Name = {
    Text = "Безмолвный банкет"
  },
  State_20649_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: «Вознесение» помещает в вашу руку последний разыгранный «Навык» из предыдущего хода и уменьшает его расход арифметики на 1, если Эффект срабатывает несколько раз, то он применяется к предыдущим."
  },
  State_20649_Name = {
    Text = "Время вспять"
  },
  State_20650_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: при экипировке <ComaKeywords:оглушает> себя. Перед «Вознесением» развеивает все положительные состояния врагов."
  },
  State_20650_Name = {Text = "Бред"},
  State_20651_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Ход завершен, вытяните [StateArg1] карты."
  },
  State_20651_Name = {
    Text = "Алчность"
  },
  State_20652_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: после «Вознесения» наносит всем врагам [StateArg1] урона, <DisarmKeywords:парализует>."
  },
  State_20652_Name = {Text = "Кара"},
  State_20653_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: \"ударить\"позволяет выбрать цель и уменьшить её Уровень <Energy:[Energy:StateArg1]> безумия."
  },
  State_20653_Name = {
    Text = "Дрейфуя в море желаний"
  },
  State_20654_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: В начале хода <PVPSeriousInjuryKeywords:Травматизация> себя и получите <Damage:[Damage:StateArg1]> стак(ов) <PVPCorrosionKeywords:Клеймо греха>. В конце хода <ReinforceKeywords:Укрепление> себя."
  },
  State_20654_Name = {
    Text = "Заповеди королевы"
  },
  State_20655_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: Урон «удара» увеличен на [StateArg1]%, «Удар» может выбирать цель."
  },
  State_20655_Name = {
    Text = "Милость"
  },
  State_20656_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Увеличивает Урон, лечение и эффекты щита от \"Навык\" на [StateArg1]%. После использования \"Навык\", если нет <PVPProtectiveKeywords:Барьер>, получаете 1 слой."
  },
  State_20656_Name = {
    Text = "Последняя строфа"
  },
  State_20657_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Каждый ход, когда Противник разыгрывает [StateArg1]-ю карту \"Навык\", поместите в вашу руку копию этой карты с расходом арифметики - [StateArg2]."
  },
  State_20657_Name = {
    Text = "Озарение"
  },
  State_20658_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: \"ударить\" за каждую атаку цели получает [StateArg1] вычислительную мощность."
  },
  State_20658_Name = {
    Text = "Баллада в оковах"
  },
  State_20659_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После смерти, в начале следующего хода <PVPResurrectionKeywords:Возрождение> себя и получите <Heal:[Heal:StateArg1]> ОЗ и <Block:[Block:StateArg2]> Щит, а затем уничтожьте этот \"Колесо Судьбы\"."
  },
  State_20659_Name = {
    Text = "Жизнелюбие"
  },
  State_20660_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: «Возвышение» передает всем союзникам <Block:[Block:StateArg1]> щит."
  },
  State_20660_Name = {
    Text = "Стена сердца"
  },
  State_20661_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: После «Вознесения» наносит всем врагам <Damage:[Damage:StateArg1]> Урон <PVPBleedingKeywords:кровотечение>."
  },
  State_20661_Name = {
    Text = "Отринутый путь"
  },
  State_20662_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: в конце хода за каждую единицу <PVPCapKeywords:максимальной вычислительной мощности> наносит [StateArg1] <PVPBleedingKeywords:кровотечения> врагу с <HPAndShieldMin:наименьшим показателем здоровья и щита>, нанося в общей сложности <Damage:[Damage:DescArg1]> урона <PVPBleedingKeywords:кровотечением>."
  },
  State_20662_Name = {
    Text = "скрываясь в ночи"
  },
  State_20663_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Перед «Вознесением» рассеять свои негативные состояния и получить [StateArg1] уровней <EnergyStorageKeywords:Готовьсь!>."
  },
  State_20663_Name = {
    Text = "Цепи долой"
  },
  State_20664_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: «Навык» даёт себе <ReinforceKeywords:укрепление>."
  },
  State_20664_Name = {
    Text = "Присяга рыцаря"
  },
  State_20665_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: если при расipation отрицательного состояния нет отрицательных состояний для снятия, то Лечение <Heal:[Heal:StateArg1]> жизни. Ход завершен, <DelayKeywords:задержка>: снимает с себя отрицательные состояния."
  },
  State_20665_Name = {
    Text = "Рулевой парус"
  },
  State_20666_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: после «Вознесения» союзник с <HPAndShieldMin:наименьшими ОЗ и Щитом> получает [StateArg1] стаков <PVPProtectiveKeywords:Барьера>."
  },
  State_20666_Name = {
    Text = "Дорогому другу"
  },
  State_20667_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: Урон первого разыгранного «Навыка» владельца за ход повышен на [StateArg1] %."
  },
  State_20667_Name = {
    Text = "Клинок титана"
  },
  State_20668_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Когда наш пробуждённый умирает, наносит всем врагам <Damage:[Damage:StateArg1]> <PVPBleedingKeywords:кровотечение> Урон. При смерти снаряженца дополнительно наносит <Damage:[Damage:StateArg2]> <PVPBleedingKeywords:кровотечение> Урон."
  },
  State_20668_Name = {
    Text = "Смерть госпожи Коралл"
  },
  State_20669_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке и в начале хода, если у вас нет <PVPProtectiveKeywords:Барьер>, получите [StateArg1] слоев <PVPProtectiveKeywords:Барьер>, иначе уменьшите стоимость арифметики 1 самого дорогого «Навыка» в руке на –1."
  },
  State_20669_Name = {
    Text = "Скрижаль писаний"
  },
  State_20670_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: \"ударить\"наносит <PVPSeriousInjuryKeywords:тяжёлое ранение>, Урон увеличивается на [StateArg1]%, но наносит себе половину урона в виде потери жизни."
  },
  State_20670_Name = {
    Text = "Плавник страдания"
  },
  State_20671_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: «Вознесение» восстанавливает себе <Heal:[Heal:StateArg1]> жизни."
  },
  State_20671_Name = {
    Text = "Поправ смерть"
  },
  State_20672_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>：В конце хода потратьте арифметику самой высокой карты в руке -[StateArg1]。<PrepareKeywords:Подготовка>。"
  },
  State_20672_Name = {
    Text = "концентрация духа"
  },
  State_20673_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>: «Вознесение» даёт себе <Block:[Block:StateArg1]> щит, другим союзникам <Energy:[Energy:StateArg2]> безумия."
  },
  State_20673_Name = {
    Text = "Неисчислимый фактор"
  },
  State_20696_Name = {
    Text = "Состояние@Страх гигантов"
  },
  State_20723_Desc = {
    Text = "Усиление урона от ударной карты на [Layer]._«Только для разработки»"
  },
  State_20723_Name = {
    Text = "Увеличение фиксированного урона от ударной карты__«仅开发用»"
  },
  State_20724_Desc = {
    Text = "Уменьшение урона от ударной карты на [Layer]._«Только для разработки»"
  },
  State_20724_Name = {
    Text = "Уменьшение фиксированного урона от ударной карты_«Только для разработки»"
  },
  State_20749_Desc = {
    Text = "Общий счет отката."
  },
  State_20758_Desc = {
    Text = "В начале следующего хода, в фазе начала возьмите [Layer] карты."
  },
  State_20758_Name = {
    Text = "Отложенное вытягивание карты"
  },
  State_20766_Desc = {
    Text = "Конкретный Эффект см. в общей логике удара."
  },
  State_20802_Desc = {
    Text = "Эта Карта не может быть разыграна.__«Только для разработки»"
  },
  State_20802_Name = {
    Text = "Невозможно разыграть__«Только для разработки»"
  },
  State_20803_Desc = {
    Text = "Эта Карта -1 расход вычислительной мощности. После использования других карт, эта Карта изменится на случайную колесо судьбы Карта."
  },
  State_20803_Name = {
    Text = "<CardKeyWord:душа рождается>"
