  },
  State_2431_Desc = {
    Text = "Команда уникальна: щит и восстановление здоровья, наносимые снаряженцем, увеличиваются на <WeaponEffect_Num:[StateArg1]%> от его Тело, а Урон от контратак увеличивается на <WeaponEffect_Num:[StateArg3]%>. При разыгрывании «защита» также получает <WeaponEffect_Num:[StateArg4]%> от ЗЩТ снаряженца <RetaliateIconKeywords:Контратака>. После начала боя получайте <WeaponEffect_Num:[StateArg2]%> единиц <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> от Тело снаряженца. Если текущая граница — «глубокое море», дополнительно получайте эквивалентный Урон шупалец."
  },
  State_2431_WeaponDesc = {
    Text = "Щит и восстановление ОЗ, наносимые снаряженцем, увеличиваются на <WeaponEffect_Num:[DescArg1]> пунктов, Контратака, наносимая снаряженцем, увеличивается на <WeaponEffect_Num:[StateArg3]%>. При розыгрыше «защита» дополнительно получите <WeaponEffect_Num:[Counterattack:DescArg3]> слоев <RetaliateIconKeywords:Контратака>. После начала боя получите <WeaponEffect_Num:[Power:DescArg2]> единиц <PowerIconKeywords:силы>. Если текущее царство — «Эквор», дополнительно получите эквивалентный Урон шупалец."
