  State_2501_Desc = {
    Text = "Команда уникальна: максимальное здоровье команды увеличивается на 10%. Лечение и щит, наносимые снаряженцем, увеличиваются на <WeaponEffect_Num:[StateArg3]%>. После разыгрывания «ударить» снаряженца восстанавливается <WeaponEffect_Num:[StateArg1]%> потерянного здоровья. После разыгрывания «защита» снаряженца получаете щит, равный <WeaponEffect_Num:[StateArg2]%> текущего здоровья. Этот Эффект может активироваться не более 1 раза за ход."
