  State_2501_WeaponDesc = {
    Text = "Максимальное здоровье команды увеличено на 10%. Лечение и щит, наносимые снаряженцем, увеличены на <WeaponEffect_Num:[StateArg3]%. После разыгрывания «ударить» снаряженца восстановите [StateArg1]% (<WeaponEffect_Num:[Heal:DescArg1]>) потерянного здоровья. После разыгрывания «защита» снаряженца получите [StateArg1]% (<WeaponEffect_Num:[Block:DescArg2]>) щита от текущего здоровья. Этот Эффект может срабатывать не более 1 раза за ход."
