  State_3070_Desc = {
    Text = "Команда уникальна: \"Удар\" снаряженца заставляет целевого врага потерять временные <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, равные атакующей силе снаряженца <WeaponEffect_Num:[StateArg1]%>. Этот Эффект может срабатывать до 3 раз за ход."
  },
  State_3070_WeaponDesc = {
    Text = "Снаряжение позволяет нанести \"Удар\", временно снижая у цели врага <WeaponEffect_Num:[Power:DescArg1]> очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Этот Эффект может срабатывать до 3 раз за ход."
  },
  State_3071_Desc = {
    Text = "Уникально для команды: после использования защиты снаряжения, временно получает силу, равную атакующей силе экипировки <WeaponEffect_Num:[StateArg1]%> <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_3071_WeaponDesc = {
    Text = "После использования снаряжения «защита», получите <WeaponEffect_Num:[Power:DescArg1]> временных единиц <PowerIconKeywords:силы>."
  },
  State_3072_Desc = {
    Text = "Команда уникальна: при убийстве врага носитель получает <WeaponEffect_Num:[StateArg1]> заряда безумия и 1% критического урона; Эффект действует до конца исследования."
  },
  State_3072_WeaponDesc = {
    Text = "При убийстве врага получает <WeaponEffect_Num:[StateArg1]> безумие, критический Урон увеличивается на 1%, действует на всё исследование."
  },
  State_3073_Desc = {
    Text = "Команда уникальна: после освобождения \"вспышка безумия\" снаряженным, критический шанс всех союзников в этом ходу повышается на <WeaponEffect_Num:[StateArg1]%>."
  },
  State_3073_WeaponDesc = {
    Text = "После освобождения \"вспышка безумия\" у всех союзников в этом ходу критический шанс увеличивается на <WeaponEffect_Num:[StateArg1]%>."
  },
  State_3074_Desc = {
    Text = "Уникальное команды: после разыгрывания симптом карты, носитель получает <WeaponEffect_Num:[StateArg1]> очков Алиемуса. Этот Эффект может срабатывать не более 2 раз за ход. После разыгрывания 1 карты команды, носитель получает 1 очко Алиемуса."
  },
  State_3074_WeaponDesc = {
    Text = "После разыгрывания симптом карты, носитель получает <WeaponEffect_Num:[StateArg1]> очков Алиемуса. Этот Эффект может срабатывать не более 2 раз за ход. После разыгрывания 1 карты команды, носитель получает 1 очко Алиемуса."
  },
  State_3075_Desc = {
