  State_3200_Desc = {
    Text = "Уникальное команды: Базовый Урон и щит, наносимые снаряженцем, увеличены на <WeaponEffect_Num:[StateArg1]%>. В начале исследования добавьте в колоду одну карту «Удар» и одну карту «защита» носителя. После розыгрыша «защита» носителя увеличивает крит. шанс и крит. Урон следующего «удара» носителя на 15%, а после розыгрыша «Удар» носителя увеличивает щит следующей «защиты» носителя на 15%, может складываться до 3 раз."
  },
  State_3200_WeaponDesc = {
    Text = "Базовый Урон и щит, наносимый снаряженцем, увеличиваются на <WeaponEffect_Num:[StateArg1]%>. В начале исследования добавьте в колоду одну карту «Удар» и одну карту «защита» носителя. После розыгрыша «защиты» снаряженец увеличивает крит. шанс и крит. Урон следующего «удара» на 15%, после розыгрыша «удара» снаряженец увеличивает щит следующей «защиты» на 15%, может накапливаться до 3 раз."
  },
  State_3201_Name = {
