  },
  State_3203_WeaponDesc = {
    Text = "Щит Носителя повышается на <WeaponEffect_Num:[StateArg3]%>. «Защита» Носителя накладывает <WeaponEffect_Num:[Poison:DescArg1]> стаков <IntoxicationIconKeywords:Яда> на врага с наибольшим количеством ОЗ. Если текущее Царство — «Каро», при наложении <IntoxicationIconKeywords:Яда> <EmbryoFusionIconKeywords:Слияние Зародыша> +<WeaponEffect_Num:[Blood:StateArg2]>; этот эффект срабатывает не более 3 раз за ход."
