  },
  State_3393_Desc = {
    Text = "В начале хода эмбриональная фузия увеличивается на 30%. Все ваши поглощающие эффекты становятся бесконечным поглощением."
  },
  State_3394_Name = {
    Text = "Поместите 1 карту <DerivativeCardKeywords_4:\"вдохновение\"> в колоду для розыгрыша"
  },
  State_3395_Desc = {
    Text = "Уникальное команды: Базовый Урон «Удар» носителя увеличивается на 25%, базовый щит «защита» увеличивается на 25%. При розыгрыше «удара» носителя получаете временную <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, равную атакующей силе носителя <WeaponEffect_Num:[StateArg1]%>, при розыгрыше «защиты» носителя получаете временную <AlertIconKeywords:Тревога>, равную силе защиты носителя <WeaponEffect_Num:[StateArg2]%>. Если текущее Царство — «Ультра», при входе в ультра-ход получаете одну временную <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> и временную <AlertIconKeywords:Тревога>."
  },
  State_3395_WeaponDesc = {
    Text = "Базовый Урон «удара» снаряженца увеличивается на 25%, базовый щит «защиты» увеличивается на 25%. При разыгрывании «удара» снаряженца получаете <WeaponEffect_Num:[Power:DescArg1]> временных <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, при разыгрывании «защиты» снаряженца получаете <WeaponEffect_Num:[DescArg2]> временных <AlertIconKeywords:настороженности>. Если текущее царство «Ультра», при входе в ультра-ход получаете один временный <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> и временный <AlertIconKeywords:настороженности>."
  },
  State_3397_Desc = {
