  State_3411_Name = {
    Text = "Иммунитет к <FragileIconKeywords:хрупкий>, <WeaknessIconKeywords:слабость>, <VulnerabilityIconKeywords:уязвимость> на 1 ход. Получить <Block:[Block:StateArg1]> очков щита"
