  },
  State_3416_Desc = {
    Text = "Уникальное команды: после начала боя получить Контратаку в размере <WeaponEffect_Num:[StateArg1]%> ЗЩТ Носителя. После срабатывания<DeathResistanceIconKeywords: Сопротивления смерти> получить не более 2 стаков «Колыбели» суммарно: Щит и Лечение ОЗ всех союзников повышаются на <WeaponEffect_Num:[StateArg2]%>, в конце хода снимается 1 стак; если текущее Царство — «Каро», после срабатывания<DeathResistanceIconKeywords: Сопротивления смерти> Слияние Зародыша <WeaponEffect_Num:+[Blood:StateArg3]>."
  },
  State_3416_WeaponDesc = {
    Text = "После начала боя получить <WeaponEffect_Num:[Counterattack:DescArg1]> стаков Контратаки. После срабатывания<DeathResistanceIconKeywords: Сопротивления смерти> получить не более 2 стаков «Колыбели» суммарно: Щит и Лечение ОЗ всех союзников повышаются на <WeaponEffect_Num:[StateArg2]%>, в конце хода снимается 1 стак; если текущее Царство — «Каро», после срабатывания<DeathResistanceIconKeywords: Сопротивления смерти> Слияние Зародыша <WeaponEffect_Num:+[Blood:StateArg3]>."
  },
  State_3418_Desc = {
    Text = "Ход завершен, временная Огромная Огромная Огромная Огромная сила теряется"
  },
  State_3418_Name = {
    Text = "Затухание задержки"
  },
  State_3419_Desc = {
    Text = "При подборе показать три карты с гравировкой высшего уровня или проклятия. Выбрать одну и наделить её соответствующей гравировкой."
  },
  State_3420_Desc = {
    Text = "Каждое действие вызывает кровотечение,лечение может снизить количество слоев кровотечения наполовину."
  },
  State_3420_Name = {
    Text = "Кровавые брызги"
