  State_3420_WeaponDesc = {
    Text = "Каждое действие вызывает кровотечение,лечение может снизить количество слоев кровотечения наполовину."
  },
  State_3421_Desc = {
    Text = "В начале хода добавьте в руку одну карту \"Гарпун\", чтобы получить [Arg1] силы в этом ходу. После освобождения вспышки безумия увеличьте силу всех \"Гарпун\" в руке на [Arg2]."
  },
  State_3422_Name = {
    Text = "Состояние - аксессуар Безупречное Откровение"
