  State_3422_WeaponDesc = {
    Text = "Освобождая Призыв, восстановите [DescArg1] ОЗ. Если Уровень заряда Ключесвета снаряженца больше 20, дополнительно восстановите [DescArg1] ОЗ. Одноименные эффекты не могут действовать одновременно."
