  },
  State_3425_Desc = {
    Text = "При жизни ниже 50%([StateArg1]), намерение меняется на \"Инстинкт выживания\": снимает состояние Хрупкость, Слабость и Яд, накладывает 99 слоёв Слабости и Хрупкости на нашу команду"
