  },
  State_47199_Name = {
    Text = "Переключение на депрессивную личность. Мясо и кровь · Мания: Урон получает [DescArg1]-кратный бонус от <PowerIconKeywords:силы> и наносит цели 200% урона с эффектом <BleedingIconKeywords:кровотечения>, получает [StateArg7] единиц <PowerIconKeywords:силы>"
