  },
  State_47206_Name = {
    Text = "Переключение на маниакальную личность. Эквор · Депрессия: наложить <WeaknessIconKeywords:слабость> и <VulnerabilityIconKeywords:уязвимость> на цель на 2 хода, создать 1 щупальце, <TentacleInjurieIconKeywords:Урон шупалец> + [TentaclePower:StateArg3]"
  },
  State_47209_Name = {
    Text = "Переключиться на Депрессивную личность. Ультра·Мания: получить <RetaliateIconKeywords:Контратаку>, равную 15% нанесённого урона, затем нанести остальным врагам равный <FixedDamage:Чистый урон>. За каждую разыгранную в этом ходу карту «Озарение» этот урон увеличивается на [StateArg9] в текущем ходу, максимум на [StateArg10]"
  },
  State_47211_Name = {
