  },
  State_47530_Name = {
    Text = "<CardKeyWord:моделирование>"
  },
  State_47557_Desc = {
    Text = "Уникальное команды: после начала исследования носитель переходит в режим личности Серебряной Трески-Рыбочеловека. После Вознесения носителя происходит переключение между личностью Серебряной Трески-Рыбочеловека и личностью Кошки.\nЛичность Серебряной Трески-Рыбочеловека: после нанесения носителем активного урона получить <WeaponEffect_Num:[StateArg1]> ключесвета. Личность Кошки: после нанесения носителем активного урона временный крит. урон носителя <WeaponEffect_Num:+[StateArg2]%>. Оба эффекта совместно используют лимит в 5 срабатываний за ход."
  },
  State_47557_WeaponDesc = {
    Text = "После начала исследования носитель переходит в режим личности Серебряной Трески-Рыбочеловека. После Вознесения носителя происходит переключение между личностью Серебряной Трески-Рыбочеловека и личностью Кошки.\nЛичность Серебряной Трески-Рыбочеловека: после нанесения носителем активного урона получить <WeaponEffect_Num:[StateArg1]> ключесвета. Личность Кошки: после нанесения носителем активного урона временный крит. урон носителя <WeaponEffect_Num:+[StateArg2]%>. Оба эффекта совместно используют лимит в 5 срабатываний за ход."
  },
  State_47822_Desc = {
    Text = "Если в следующем ходу снова получит «Паралич», все его «ударить» становятся «Иллюзией», нельзя рассеять, действует до конца следующего хода."
  },
  State_47822_Name = {
    Text = "Немного онемело"
  },
  State_47825_Desc = {
    Text = "В начале хода активируется соответствующий Эффект умения."
  },
  State_47825_Name = {
    Text = "<CardKeyWord:задержка>"
  },
  State_47826_Desc = {
    Text = "·Если цель находится под «Параличом», Урон удваивается, иначе в этом ходу её «ударить» нельзя использовать.\n·Если цель находится под «Параличом» 2 хода подряд, все её «ударить» становятся «Иллюзией»."
  },
  State_47826_Name = {
    Text = "<WeaknessColour:Паралич>"
  },
  State_47827_Desc = {
    Text = "Каждый слой уменьшает весь наносимый Урон в этом бою на 1 единицу, не может быть рассеяно."
  },
  State_47827_Name = {
    Text = "<WeaknessColour:Снижение силы>"
  },
  State_47828_Desc = {
    Text = "·При наложении наносит Урон, равный количеству слоёв. Если цель находится в состоянии «Опутывание», Урон удваивается, в противном случае снаряженные цели Судьбы становятся недействительными до конца хода."
  },
  State_47828_Name = {
    Text = "<WeaknessColour:Сплетение>"
  },
  State_47830_Desc = {
