  },
  State_47830_Name = {
    Text = "<PVPVulnerabilityIconColour:ранение>"
  },
  State_47831_Desc = {
    Text = "Не может предпринимать никаких действий до завершения хода. После получения урона от оглушения цель получает сопротивление. Если у цели есть сопротивление, повторное получение урона от оглушения отменяет Эффект оглушения и удваивает Урон. Это состояние не может быть рассеяно."
  },
  State_47831_Name = {
    Text = "<ComaColour:петрификация>"
  },
  State_47832_Desc = {
    Text = "Включая зараженную мышь, электрифицированную мышь, потерявший ориентацию мышь."
  },
  State_47832_Name = {
    Text = "<CardKeyWord:мышиная Карта>"
  },
  State_47833_Desc = {
