  },
  State_47889_Name = {
    Text = "Эквор: Урон, нанесённый «24», получает [StateArg2] % бонус к <TentacleInjurieIconKeywords:ущербу от щупалец> и наносит 10% урона <IntoxicationIconKeywords:Яд>. Взрыв безумия «24» может вызвать [StateArg6] % <IntoxicationIconKeywords:Яд> у врагов."
  },
  State_47892_Name = {
    Text = "Хаос: крит. шанс и крит. урон «24» +[StateArg4]%. После каждого использования Зова итоговый урон Вознесения «24» повышается на [StateArg1]%"
  },
  State_47894_Name = {
