  },
  State_48108_Name = {Text = "Фуэте"},
  State_48110_Desc = {
    Text = "\"Навык\" меняет следующий Удар в этом ходу на случайную цель и дополнительно атакует [StateArg1] случайных целей."
  },
  State_48110_Name = {
    Text = "человек в зеркале"
  },
  State_48140_Desc = {
    Text = "В начале исследования «24» входит в состояние Депрессивной личности.\n<School_1:Хаос·Депрессия>：Получить <Posse:[StateArg1]> ед. Ключесвета, следующий Зов срабатывает 2 раза.\n<School_1:Хаос·Мания>：Нанести урон 3 раза, увеличить весь урон «24» на [StateArg2] ед.\n<School_2:Эквор·Депрессия>：Наложить <WeaknessIconKeywords:Слабость> и <VulnerabilityIconKeywords:Уязвимость> на цель на 2 хода, создать 1 Щупальце, <TentacleInjurieIconKeywords:Урон шупалец>+ [StateArg3].\n<School_2:Эквор·Мания>：Этот урон получает бонус [StateArg4]% <TentacleInjurieIconKeywords:Урона шупалец> и накладывает <IntoxicationIconKeywords:Яд> на всех врагов в размере 30% нанесённого урона.\n<School_3:Каро·Депрессия>：<EmbryoFusionIconKeywords:Слияние Зародыша> +[Blood:StateArg5], накопить [StateArg6] ед. лечения Багрового горнила.\n<School_3:Каро·Мания>：Урон получает 6-кратный бонус <PowerIconKeywords:Силы> и накладывает на цель <BleedingIconKeywords:Кровотечение> в размере 200% нанесённого урона, получить [StateArg7] ед. <PowerIconKeywords:Силы>.\n<School_4:Ультра·Депрессия>：Добавить 2 карты «Озарение» в руку, временно снизить <PowerIconKeywords:Силу> цели на [StateArg8] ед.\n<School_4:Ультра·Мания>：Получить <RetaliateIconKeywords:Контратаку> в размере 15% нанесённого урона, затем нанести остальным врагам равный <FixedDamage:Чистый урон>. За каждую разыгранную в этом ходу карту «Озарение» увеличить этот урон в текущем ходу на [StateArg9] ед., максимум на [StateArg10] ед."
  },
  State_48140_Name = {
    Text = "Эффекты царства и личности"
  },
  State_48141_Desc = {
    Text = "<School_1:Хаос>: «24» <School_2:крит. шанс> и <TentacleInjurieIconKeywords:крит. урон> +[StateArg4]%. После каждого использования Зова итоговый урон Вознесения «24» увеличивается на [StateArg1]%.\n<IntoxicationIconKeywords:Эквор>: наносимый «24» Урон получает [StateArg2]% бонус к <IntoxicationIconKeywords:Урону щупалец> и наносит 10% урона <School_3:Яд>. Вознесение «24» может вызвать 50% <EmbryoFusionIconKeywords:Яда> у врагов.\n<PowerIconKeywords:Каро>: «24» за каждую потраченную 1 ед. Арифметики <School_4:Слияние Зародыша> +[Blood:DescArg1], получает [StateArg3] ед. <RetaliateIconKeywords:Силы>. Вознесение «24» дополнительно получает 300% бонус к Силе\n⟦T11⟧Ультра⟦/T11⟧: наносимый «24» Урон получает [StateArg5]% бонус к урону ⟦T12⟧Контратаки⟦/T12⟧, в конце хода замешать 1 карту «Озарение» в стопку сброса, лимит руки +2."
  },
  State_48141_Name = {
    Text = "Эффект области"
  },
  State_48149_Name = {
    Text = "Не можно использовать Эффект карты__«Только для разработки»"
  },
  State_48176_Desc = {
    Text = "В этом игровом тесте каждый ход вы получаете 1 очко арифметики, а за каждую единицу расхода в \"24\" вы получаете 30 очков ключесвета."
  },
  State_48176_Name = {
    Text = "\"24\" Демо"
  },
  State_48198_Desc = {
    Text = "В этом пробном запуске, каждый ход получите 1 карту \"вдохновение\"."
  },
  State_48198_Name = {
    Text = "\"24\" Демо"
  },
  State_48199_Desc = {
    Text = "В этом игровом тесте каждый ход вы получаете 1 очко вычислительной мощности."
  },
  State_48199_Name = {
    Text = "\"24\" Демо"
  },
  State_48589_Desc = {
    Text = "Это пробуждающее тело еще не пробуждено... Приближаясь к падению, оно пробудится, ответит жизнью и станет в 2 раза сильнее, начав бой в истинной форме."
  },
  State_48589_Name = {
    Text = "Невознесённый"
  },
  State_48607_Name = {
    Text = "Уменьшение исходной вычислительной мощности универсальной карты__«仅开发用»"
  },
  State_48822_Desc = {
    Text = "Механизм границы мяса и крови: в начале хода получаемая эмбриональная фузия увеличивается на 50%."
  },
  State_48822_Name = {
    Text = "Бесконечный цикл жизни"
  },
  State_48923_Desc = {
    Text = "Тень \"24\" уже пробудилась, воспользуйся последней возможностью \"Спасите меня\", чтобы найти шанс!"
  },
  State_48923_Name = {
    Text = "Тень \"24\"пробуждение!"
  },
  State_48923_WeaponDesc = {
    Text = "Получить щит в начале следующего хода в размере потерянного здоровья на предыдущем ходу."
  },
  State_49063_Desc = {
    Text = "Усиление урона удара Ротань на 30%."
  },
  State_49063_Name = {
    Text = "Растущая жажда битвы"
  },
  State_49109_Desc = {
    Text = "Карта остается у вас. Если она все еще в руке, когда ход завершен, вы получаете 1 исходную копию этой карты команды с расходом."
  },
  State_49109_Name = {
    Text = "<Rune_20_High:зачатие>"
  },
  State_49109_WeaponDesc = {
    Text = "Срабатывает дополнительно [StateArg1] раз, расход."
  },
  State_49148_Desc = {
    Text = "После смерти добавьте \"Искажение 1\" к одной карте с ненулевым расходом вычислительной мощности. Искажение: состояние карты, сохраняется после окончания боя. Каждый Уровень уменьшает расход на 1, но после розыгрыша каждый Уровень добавляет одну случайную искаженную карту в руку (игнорируя лимит руки) и удаляет все искажения."
  },
  State_49148_Name = {
    Text = "Плод искажения"
  },
  State_49149_Desc = {
    Text = "Каждый Уровень уменьшает расход вычислительной мощности карты на 1. После разыгрывания, за каждый Уровень мутации добавьте одну случайную мутировавшую карту в руку и удалите это состояние. Это состояние будет сохранено после окончания боя."
  },
  State_49149_Name = {
    Text = "<ExclamationPointColour:искажение [Layer]>"
  },
  State_49149_WeaponDesc = {
    Text = "Удалить постоянно после применения."
  },
  State_49207_Name = {
    Text = "Получить 100 Ключесвета"
  },
  State_49225_Desc = {
    Text = "Ход завершен, заставляет 1 щупальце атаковать [Layer] раз."
  },
  State_49225_Name = {
    Text = "<CardKeyWord:сбор щупалец>"
  },
  State_49226_Desc = {
    Text = "В конце хода за каждую карту в руке все враги получают 3% отравления и вы получаете 3 единицы алиэмиуса."
  },
  State_49226_Name = {
    Text = "Слабый Искра свечи"
  },
  State_49260_Desc = {
    Text = "Ход завершен, Лечение равен 7.5% от Тело жизни."
  },
  State_49260_Name = {
    Text = "Боль непринятия"
  },
  State_49270_Desc = {
    Text = "Усиление урона карты удара на [Layer] %."
