  State_49270_Name = {
    Text = "Усиление урона карт ударов"
  },
  State_49270_WeaponDesc = {
    Text = "Усиление урона карты удара на [Layer] %."
  },
  State_49278_Desc = {
    Text = "Когда ход завершен, Лечение равен 5% от потерянной жизни. Если жизнь ниже 50%([StateArg1]), также получите [StateArg2] силы."
  },
  State_49278_Name = {
    Text = "Багровый алтарь"
  },
  State_49430_Desc = {
    Text = "Получаемый Урон снижен, каждый Уровень снижает Урон на 1 %. Состояние снимается после смерти других союзников."
  },
  State_49430_Name = {
    Text = "<AberrationColour:скрытность>"
  },
  State_49500_Desc = {
    Text = "Каждый Уровень увеличивает количество атак на 1. При получении урона теряется один Уровень. Ход завершен: всё теряется."
  },
  State_49500_Name = {
    Text = "Текст молитвы"
  },
  State_49524_Desc = {
    Text = "В конце хода восстанавливается 5% потерянной жизни. Каждый раз, когда игрок берет 1 карту состояния или симптома, все \"Нубия\" получают [StateArg1] временной силы."
  },
  State_49524_Name = {
    Text = "Кровавое Евангелие"
  },
  State_49526_Desc = {
    Text = "После смерти сразу восстановить [StateArg2] единиц жизни и получить Иммунитет к урону на 1 ход, изменить намерение на \"Распространение нечистот\"."
  },
  State_49526_Name = {
    Text = "Развеивание"
  },
  State_49542_Desc = {
    Text = "Команда уникальна: после начала боя получите силу, равную <WeaponEffect_Num:[StateArg1]%> от атакующей силы снаряженца. Если текущее Царство — \"Эквор\", также увеличится Урон шупалец, равный <WeaponEffect_Num:[StateArg2]%> от атакующей силы снаряженца."
  },
  State_49542_WeaponDesc = {
    Text = "После начала боя получите <WeaponEffect_Num:[Power:DescArg1]> единиц силы. Если текущая граница — \"глубокое море\", также получите <WeaponEffect_Num:[DescArg2]> урона от щупалец."
  },
  State_49546_Desc = {
    Text = "Всегда появляется вместе с 2 охранниками Элита. После его смерти они тоже погибают."
