  },
  State_49558_Name = {
    Text = "Благословление песков"
  },
  State_49582_Desc = {
    Text = "В этом бою оставшийся щит каждый ход не будет удаляться и будет сохраняться."
  },
  State_49582_Name = {
    Text = "Постоянное сохранение щита"
