  State_49844_Desc = {
    Text = "Команда уникальна: после завершения хода получить <WeaponEffect_Num:[StateArg1]> очков ключесвета. После срабатывания сопротивления смерти получить <WeaponEffect_Num:[StateArg2]> очков ключесвета. После использования тела Гнозис экстренного реагирования лимит арифметики увеличивается на 3, количество вытягиваемых карт за ход увеличивается на 3."
  },
  State_49844_WeaponDesc = {
    Text = "По окончании хода получите <WeaponEffect_Num:[StateArg1]> очков Ключесвета. После срабатывания сопротивления смерти получите <WeaponEffect_Num:[StateArg2]> очков Ключесвета. После использования Тела Гнозис экстренного реагирования лимит арифметики увеличивается на 3, а количество вытягиваемых карт за ход увеличивается на 3."
  },
  State_49877_Desc = {
    Text = "Уменьшите расход вычислительной мощности карты. После разыгрывания, за каждый Уровень искажения добавьте одну случайную искажённую карту в руку и удалите это состояние. Это состояние будет сохранено после окончания боя."
