  },
  State_55487_Desc = {
    Text = "Эрика наносит дополнительно 2 урона с атакой «ударить», а также получает дополнительно 2 щита от защиты «защита» на протяжении [Layer] ходов."
  },
  State_55487_Name = {
    Text = "Многократные вычисления"
  },
  State_55489_Name = {
    Text = "Пространственно-временной скачок"
  },
  State_55806_Name = {
    Text = "<PoetryKeywords:Посвящение стихов>: нанести отрицательный <PVPWonderfulEffectKeywords:чудесный Эффект> всем врагам или дать положительный <PVPWonderfulEffectKeywords:чудесный Эффект> всем союзникам или вытянуть 1 карту, получить 1 вычислительную мощность. Последнее посвящение стихов срабатывает 2 раза"
  },
  State_55807_Name = {
    Text = "Возьмите 1 карту, получите 1 вычислительную мощность"
  },
  State_55808_Name = {
    Text = "<PoetryKeywords:Посвящение стихов>: дать всем союзникам положительный <PVPWonderfulEffectKeywords:чудесный Эффект>, или вытянуть 1 карту, получить 1 вычислительную мощность. Последнее посвящение стихов срабатывает 2 раза"
  },
  State_55809_Name = {
    Text = "Предоставить всем врагам отрицательный <PVPWonderfulEffectKeywords:чудесный Эффект>"
  },
  State_55811_Desc = {
    Text = "Выберите одну из перечисленных опций для применения."
  },
  State_55811_Name = {
    Text = "<ComaColour:решение>"
  },
  State_55813_Name = {
    Text = "<PoetryKeywords:Посвящение стихов>: нанести отрицательный <PVPWonderfulEffectKeywords:чудесный Эффект> всем врагам или вытянуть 1 карту, получить 1 вычислительную мощность. Последнее посвящение стихов срабатывает 2 раза"
  },
  State_55814_Name = {
    Text = "<PoetryKeywords:Посвящение стихов>: нанести отрицательный <PVPWonderfulEffectKeywords:чудесный Эффект> всем врагам или дать положительный <PVPWonderfulEffectKeywords:чудесный Эффект> всем союзникам. Последнее посвящение стихов срабатывает 2 раза"
  },
  State_55816_Name = {
    Text = "Дать всем союзникам благоприятный <PVPWonderfulEffectKeywords:чудесный Эффект>"
  },
  State_55824_Desc = {
    Text = "Выберите одну из перечисленных опций для применения, после выбора удалите выбранную опцию, если остались другие опции, положите эту карту в руку противника."
  },
  State_55824_Name = {
    Text = "<ComaColour:посвящение стихов>"
  },
  State_55836_Desc = {
    Text = "Ход завершен, расход вычислительной мощности для карты команды Орла в руке уменьшается на 1."
  },
  State_55836_Name = {
    Text = "Сонет в чернилах"
  },
  State_55839_Desc = {
    Text = "При подборе теряются все другие создания, случайным образом получаете 2 золотых творения."
  },
  State_55866_Desc = {
    Text = "Команда уникальна: в начале битвы вытяните 1 карту команды снаряженца, и есть вероятность <WeaponEffect_Num:[StateArg1]%> уменьшить её расход вычислительной мощности на 1. Каждый раз, когда срабатывает Сопротивление смерти, этот Эффект повторно срабатывает 1 раз."
  },
  State_55866_WeaponDesc = {
    Text = "В начале боя возьмите 1 карту команды снаряженца, и с вероятностью <WeaponEffect_Num:[StateArg1]%> уменьшите её расход вычислительной мощности на 1. Каждый раз, когда срабатывает Сопротивление смерти, этот Эффект повторно срабатывает 1 раз."
  },
  State_55992_Desc = {
    Text = "Вычислительная мощность недостаточна, что приводит к накладыванию расхода и меток на карты."
  },
  State_55992_Name = {Text = "Пепел"},
  State_55993_Name = {
    Text = "Метка тлеющих углей"
  },
  State_56018_Desc = {
    Text = "В этом бою максимальное здоровье повышено на [Layer]%."
  },
  State_56018_Name = {
    Text = "Благосклонность музы: Колесо Судьбы"
  },
  State_56020_Desc = {
    Text = "В этом бою Усиление урона на [Layer]%."
  },
  State_56020_Name = {
    Text = "Благосклонность музы: Огромная Огромная Огромная Огромная сила"
  },
  State_56030_Desc = {
    Text = "В этом ходу щиты и лечение от пробуждающего тела повышены на [Layer]%."
  },
  State_56030_Name = {Text = "Снег"},
  State_56031_Desc = {
    Text = "В этом раунде каждое нанесение 1 урона повышает временный критический шанс на [Layer]%."
  },
  State_56031_Name = {
    Text = "Бабочка"
  },
  State_56034_Desc = {
    Text = "Каждая \"метафора\" может иметь максимум 3 слоя. Разные \"метафоры\" усиливают различные эффекты стихов: \n<D06CardKeyWordnu:Стих-нападка>: расход всех метафор \"Гнев\", каждая метафора дополнительно наносит 2 единицы урона. \n<D06CardKeyWordai:Стих-элегия>: расход всех метафор \"Ай\", каждая метафора дополнительно восстанавливает здоровье. \n<D06CardKeyWordxi:Стих-панегирик>: расход всех метафор \"Радость\", каждая метафора дополнительно дает 10 очков Алиемуса. \n<D06CardKeyWordju:Стих-панихида>: расход всех метафор \"Страх\", каждая метафора дополнительно получает <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_56034_Name = {
    Text = "Метафора"
  },
  State_56208_Desc = {
    Text = "Элегия дождя: восстанавливает <Heal:[DescArg1]> ОЗ.\nЭлегия ветра: получает [DescArg2] очков <PowerIconKeywords:Силы>.\nЭлегия цветов: все Пробуждённые получают [DescArg3] Алиемуса.\nЭлегия луны: Временный крит. шанс увеличивается на [DescArg4]%."
  },
  State_56208_Name = {
    Text = "Поэзия"
  },
  State_56330_Desc = {
    Text = "Получить [DescArg1] очков щита. Если за этот ход вы использовали \"вспышку безумия\" трижды, эта Карта будет активирована ещё раз."
  },
  State_56330_Name = {
    Text = "Высший образ"
  },
  State_56331_Desc = {
    Text = "Выберите 1 карту команды из колоды для розыгрыша, сброса карт, поместите её в руку и снизьте затраты на 2 единицы."
  },
  State_56331_Name = {
    Text = "Высший образ"
  },
  State_56332_Desc = {
    Text = "Получите [DescArg1] очков временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. После использования в этом ходу каждое нанесение урона увеличивает временный критический шанс на 3%."
  },
  State_56332_Name = {
    Text = "Высший образ"
  },
  State_56333_Desc = {
    Text = "Восстановление 10% утраченной жизни. Если текущая жизнь ниже 25%, эта Карта срабатывает дополнительно 1 раз."
  },
  State_56333_Name = {
    Text = "Высший образ"
  },
  State_56334_Desc = {
    Text = "Следующий ключевой приказ работает дважды."
  },
  State_56334_Name = {
    Text = "Высший образ"
  },
  State_56335_Desc = {
    Text = "Наносит <FixedDamage:Чистый урон>, равный 150% собственного макс. ОЗ. Этот урон получает 10-кратный бонус от <PowerIconKeywords:Силы>."
  },
  State_56335_Name = {
    Text = "Высший образ"
  },
  State_56336_Desc = {
    Text = "Вытащить 5 карт."
  },
  State_56336_Name = {
    Text = "Высший образ"
  },
  State_56337_Desc = {
    Text = "Получить [DescArg1] очков временной <AlertIconKeywords:настороженности>. После использования в этом ходу щиты и восстановление усиливаются на [DescArg2]%."
  },
  State_56337_Name = {
    Text = "Высший образ"
  },
  State_56338_Desc = {
    Text = "Получить 3 единицы вычислительной мощности."
  },
  State_56338_Name = {
    Text = "Высший образ"
  },
  State_56339_Desc = {
    Text = "Рассеивает случайное 1 отрицательное состояние. Эта Карта действует дополнительно 3 раза, расходуется."
  },
  State_56339_Name = {
    Text = "Высший образ"
  },
  State_56340_Desc = {
    Text = "Применить ко всем врагам Эффект <VulnerabilityIconKeywords:уязвимость> на 3 хода. Каждый раз, когда враг погибает, эта Карта будет перемещена из колоды в руку."
  },
  State_56340_Name = {
    Text = "Высший образ"
  },
  State_56341_Desc = {
    Text = "Мастерство границ +25 очков, временное мастерство границ +125 очков."
  },
  State_56341_Name = {
    Text = "Высший образ"
  },
  State_56342_Desc = {
    Text = "Все пробуждающие тела получают пятнадцать единиц безумия."
  },
  State_56342_Name = {
    Text = "Высший образ"
  },
  State_56343_Desc = {
    Text = "Наложить на всех врагов <WeaknessIconKeywords:слабость> на 3 хода, поместить 1 копировать этой карты в сброса карт, добавить <DepleteIconKeywords:расход>, <NothingnessIconKeywords:ничто>."
  },
  State_56343_Name = {
    Text = "Высший образ"
  },
  State_56372_Desc = {
    Text = "При смерти Очистить 1 негативное состояние, полученное игроком."
  },
  State_56372_Name = {
    Text = "Цветы и стихи"
  },
  State_56400_Desc = {
    Text = "После «удара» навыки в руке будут по порядку превращаться в другие «навыки» [ShowIfState:, <CardKeyWord:<SkillName3:>>→<CardKeyWord:<SkillName2:>>→<CardKeyWord:<SkillName1:>>→<CardKeyWord:<SkillName3:>>]."
  },
  State_56400_Name = {
    Text = "Поэтичные минувшие дни"
  },
  State_56402_Desc = {
    Text = "Иметь метафору <D06CardKeyWordnu:\"Гнев\"> [DescArg2] слоев: при активации \"Стих-нападка\" дополнительно наносится Урон. \n Иметь метафору <D06CardKeyWordai:\"Ай\"> [DescArg3] слоев: при активации \"Стих-элегия\" дополнительно восстанавливается здоровье. \n Иметь метафору <D06CardKeyWordxi:\"Радость\"> [DescArg1] слоев: при активации \"Стих-панегирик\" дополнительно пробуждённое тело получает алиемус. \n Иметь метафору <D06CardKeyWordju:\"Страх\"> [DescArg4] слоев: при активации \"Хитрость\" дополнительно получают силу."
  },
  State_56402_Name = {
    Text = "Метафора"
  },
  State_57166_Desc = {
    Text = "Пробуждающее тело наносит на 25% больше урона."
  },
  State_57170_Desc = {
    Text = "Максимальное количество карт на руке +2, Ход завершен: выберите 1 карту в руке для сохранения и уменьшите её расход вычислительной мощности на 1, Эффект длится 3 хода."
  },
  State_57170_Name = {
    Text = "Свет заблудшего пути"
  },
  State_57316_Desc = {
    Text = "В начале каждого хода преобразуйте 1 карту «Зародыш» в «Непорочное дитя», если нет «Зародыша», <EmbryoFusionIconKeywords:Слияние Зародыша> +[Blood:DescArg1], не подвержено эффектам усиления Слияния Зародыша. Длится [Layer] ход(ов)."
  },
  State_57316_Name = {
    Text = "Вечная жизнь священной реликвии"
  },
  State_57317_Desc = {
    Text = "Когда это колесо судьбы в колоде, вы сможете увидеть изменения, которые произойдут с навыками в вашей руке."
  },
  State_57317_Name = {
    Text = "<PVPFlowerKeywords:Поэтичные минувшие дни>"
  },
  State_57324_Desc = {
    Text = "Если это пробуждающее тело активирует \"Цветы и поэзия былых времён\", эта Карта изменится на <CardKeyWord:<SkillName1:>>."
  },
  State_57324_Name = {
    Text = "Поэтичные минувшие дни"
  },
  State_57325_Desc = {
    Text = "Если это пробуждающее тело активирует \"Поэтичные минувшие дни\", эта Карта изменится на <CardKeyWord:<SkillName2:>>."
  },
  State_57325_Name = {
    Text = "Поэтичные минувшие дни"
  },
  State_57326_Desc = {
    Text = "Если это пробуждающее тело активирует \"Цветы и поэзия прошлого\", эта Карта изменится на <CardKeyWord:<SkillName3:>>."
  },
  State_57326_Name = {
    Text = "Поэтичные минувшие дни"
  },
  State_57335_Name = {
    Text = "Эта Карта наносит Урон, усиленный в [DescArg1] раз силой"
  },
  State_57356_Name = {
    Text = "Состояние@вычисление контратаки Погружённого"
  },
  State_57368_Name = {
    Text = "Состояние@Платформа контратаки Погружённого"
  },
  State_57413_Name = {
    Text = "Каждая единица щита увеличивает Урон этой карты на [DescArg1] единиц"
  },
  State_57417_Desc = {
    Text = "При каждом срабатывании Сопротивления смерти наносится <FixedDamage:Чистый урон>, равный 100% от Контратаки. Каждый раз, когда срабатывает Сопротивление смерти в этом бою, <FixedDamage:Чистый урон> увеличивается на 25%."
  },
  State_57417_Name = {
    Text = "Колыбель любви"
  },
  State_57566_Name = {
    Text = "Инстинкт выживания"
  },
  State_57587_Desc = {
    Text = "Вытяните 1 карту при использовании \"разделение железы\", осталось [Layer] раз."
  },
  State_57587_Name = {
    Text = "Медузы, собирайтесь!"
  },
  State_57665_Name = {
    Text = "Покровительство Богоматери"
  },
  State_57728_Desc = {
    Text = "Число раз урона Юу Хаши увеличивается на 1."
  },
  State_57728_Name = {
    Text = "Дар прилива крови"
  },
  State_57751_Desc = {
    Text = "Команда уникальна: щит, наносимый снаряженцем, увеличивается на <WeaponEffect_Num:[StateArg1]%>. После освобождения ключевого приказа все пробуждённые получают <WeaponEffect_Num:[StateArg2]%> временный критический шанс и критический Урон, но добавляется жертва в размере 3% от максимального здоровья. Если текущее Царство — \"Эквор\", то после освобождения ключевого приказа также увеличивается Урон шупалец на <WeaponEffect_Num:[StateArg3]%> от атакующей силы снаряженца."
  },
  State_57751_WeaponDesc = {
    Text = "Щит от снаряжения увеличен на <WeaponEffect_Num:[StateArg1]%>. После освобождения ключевого приказа все пробуждённые получают <WeaponEffect_Num:[StateArg2]%> временный критический шанс и крит. Урон, но добавляется [DescArg1] пунктов ритуала жертвоприношения. Если текущее царство — \"Эквор\", после освобождения ключевого приказа также увеличивается Урон шупалец на [DescArg2] пунктов."
  },
  State_57753_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке получите [StateArg1] уровней <PVPSleepKeywords:Качественный сон>."
  },
  State_57753_Name = {
    Text = "Сон под ледником"
  },
  State_57766_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После первого «Вознесения» за ход временно <StrongEffectKeywords:Усиление> +[StateArg1]."
  },
  State_57766_Name = {
    Text = "Пастушья трость"
  },
  State_57767_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: В конце хода уменьшите <Energy:[Energy:StateArg1]> безумия, чтобы преобразовать в <PVPDerivativeCardKeywords_12:\"Крохотное желание\">, если преобразование не удалось, получите <Energy:[Energy:StateArg2]> безумия."
  },
  State_57767_Name = {
    Text = "Вечное выступление"
  },
  State_57768_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Урон «Навыка» повышен на [StateArg1] %. После «Вознесения» восстанавливает [StateArg2] % потерянного здоровья."
  },
  State_57768_Name = {
    Text = "Когда растает снег"
  },
  State_57769_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: после использования карты навыка владельца, возьмите 1 карту навыка владельца, максимум 1 раз за ход."
  },
  State_57769_Name = {
    Text = "Ворота Истины"
  },
  State_57770_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Урон, исцеление и эффект Щита от «Навыка» увеличены на [StateArg1]~[StateArg2]% (сейчас [Layer] %), <PhantomKeywords:Фантом>."
  },
  State_57770_Name = {
    Text = "Рулетка Судьбы"
  },
  State_57814_Name = {
    Text = "Когда этот маркер присутствует, это означает, что происходит замена колеса судьбы. Некоторые логические процессы будут нуждаться в этом маркере для идентификации.__«仅开发用»"
  },
  State_57817_Desc = {
    Text = "Невозможно действовать, в конце хода Уровни – 1, при исчерпании уровней <StrongEffectKeywords:Огромная Огромная сила> +5, невозможно развеять, замена колеса судьбы приведёт к потере состояния изысканного сна."
  },
  State_57817_Name = {
    Text = "Качественный сон"
  },
  State_57854_Desc = {
    Text = "В начале хода получает [StateArg1] щита и [StateArg2] ущерба от щупалец, генерирует 2 временных щупальца, которые длятся [Layer] ходов."
  },
  State_57854_Name = {
    Text = "Клятва свободы"
  },
  State_57854_WeaponDesc = {
    Text = "Состояние@Леди глубин, чай с тортом"
  },
  State_57864_Name = {
    Text = "Бонус обновленной силы__«Только для разработки»"
  },
  State_57942_Desc = {
    Text = "Текущая Степень слияния [Layer]%. Когда Степень слияния достигает 100%, враг принудительно переходит на следующую стадию и использует более мощные навыки перехода."
  },
  State_57942_Name = {
    Text = "Степень слияния"
  },
  State_57952_Desc = {
    Text = "Когда Огромная Огромная Огромная Огромная сила уменьшается, снижается ровно половина текущих слоёв силы."
  },
  State_57952_Name = {
    Text = "Глубокое Вдаль от берегов"
  },
  State_57953_Desc = {
    Text = "Ход завершен, появляется 1 щупальце. После пробуждения это состояние удаляется."
  },
  State_57953_Name = {
    Text = "Глубокий сон"
  },
  State_57955_Desc = {
    Text = "Шило наносит больше урона на [StateArg1]% в течение [Layer] ходов."
  },
  State_57955_Name = {
    Text = "Спасение из тупика: Урон"
  },
  State_57968_Desc = {
