  },
  State_58144_WeaponDesc = {
    Text = "Шанс критического удара увеличивается на [Layer] % в этом уровне."
  },
  State_58259_Desc = {
    Text = "Команда уникальна: критический шанс снаряженца увеличивается на <WeaponEffect_Num:[StateArg1]%. После убийства врага снаряженец получает <WeaponEffect_Num:[StateArg2]> чёрных печатей, которые могут активироваться максимум 3 раза за исследование. После активации 3 раз, критический шанс снаряженца увеличивается на <WeaponEffect_Num:[StateArg3]%> на протяжении текущего исследования."
  },
  State_58259_WeaponDesc = {
    Text = "Критический шанс снаряженца увеличивается на <WeaponEffect_Num:[StateArg1]%>. После убийства врага снаряженец получает <WeaponEffect_Num:[DescArg2]> чёрных печатей, которые могут срабатывать до 3 раз в ходе исследования ([DescArg1]/3). После 3 срабатываний критический шанс снаряженца увеличивается на <WeaponEffect_Num:[StateArg3]%> навсегда в этом исследовании."
  },
  State_58297_Desc = {
    Text = "Райкер получает [DescArg3] чёрных печатей при убийстве врагов, максимум 5 раз за каждое исследование.([DescArg1] /5)\n После получения 50/125/250 чёрных печатей в бою лимит создания увеличивается на 1, в конце боя выберите одно «наследие Хаоса» для добавления в список реликвий.(Получено [DescArg2] очков чёрной Печать пакиа)"
  },
  State_58297_Name = {
    Text = "Победитель получает всё"
  },
  State_58447_Desc = {
    Text = "Включает в себя следующие три реликвии: \n\"Легкий ветровик удачи\": критический шанс всех пробуждённых увеличивается на 10%. Все случайные результаты Райкера и кубиков не будут иметь минимального значения. \n<TentacleInjurieIconKeywords:Улучшение>: критический шанс увеличивается до 15%, максимальное значение случайного результата увеличивается на 1. \n\"Кости-восьмигранники\": каждый раз при освобождении ключевого приказа добавьте в руку 1 карту \"Кости-восьмигранники\". \n<TentacleInjurieIconKeywords:Улучшение>: изменено на добавление 1 карты \"Сияющий восьмигранник\" в руку. \n\"Большая кнопка рта\": в начале хода и при активации случайного эффекта Райкера или игральной кости получите 50 очков Ключесвета и 2% критического урона, максимум 30% критического урона. \n<TentacleInjurieIconKeywords:Улучшение>: изменено на получение 100 очков Ключесвета и 4% критического урона, максимум 50% критического урона."
  },
  State_58447_Name = {
    Text = "<CardKeyWord:наследие хаоса>"
  },
  State_58490_Desc = {
    Text = "Когда Сонливость будет полностью снята, запечатайте всех пробуждённых и карты, а намерение \"Дремлющий повелитель\" измените на \"Власть монарха\"."
  },
