  },
  State_60298_Desc = {
    Text = "Неизвестная Огромная Огромная Огромная Огромная сила всё ещё затаилась под Чёрным бассейном. Перед тем как быть побеждённой, она полностью восстановит здоровье и начнёт бой в форме освобождения."
