  },
  State_60592_WeaponDesc = {
    Text = "В начале исследования замешать 1 карту «Серебрянный Ключ Закат» в стопку добора с эффектом <DestructionKeywords:Уничтожить>. После использования Зова крит. урон носителя повышается на <WeaponEffect_Num:[StateArg1]%>. При нанесении носителем активного урона получить <WeaponEffect_Num:[DescArg1]> ед. ключесвета и <WeaponEffect_Num:[StateArg3]%> временного крит. шанса, не более 5 раз за ход."
  },
  State_60594_Desc = {
    Text = "Уникальное команды: по окончании хода носитель получает 5 очков Алиемуса. После использования Вознесение следующая Командная Карта, разыгранная носителем, увеличивает крит. шанс, крит. Урон, Щит и восстановление ОЗ на <WeaponEffect_Num:[StateArg1] %>."
  },
  State_60594_WeaponDesc = {
    Text = "По окончании хода носитель получает 5 очков Алиемуса. После освобождения вспышки безумия, следующий критический шанс, крит. Урон, щит и восстановление ОЗ карты команды, разыгранной в этом ходу, увеличиваются на <WeaponEffect_Num:[StateArg1]%."
  },
  State_60898_Desc = {
    Text = "При получении активного урона и урона щупалец Запечатывает Вознесение и все Карты атакующего Пробуждённого на 1 ход, снимает 1 уровень <ResentChainsKeywords:Цепи ненависти>."
