  State_65358_Desc = {
    Text = "Уникальное команды: Базовый Урон, наносимый снаряженцем, увеличивается на <WeaponEffect_Num:[StateArg1]%. Перед использованием Вознесения временный лимит руки увеличивается на 1, и вытягивается 1 Командная Карта снаряженца. Если текущее Царство — \"Кровь и Инкарнация\", при активации Поглощения временный критический Урон увеличивается на <WeaponEffect_Num:[StateArg1]%, Эффект срабатывает не более 1 раза за ход. ."
  },
  State_65358_WeaponDesc = {
    Text = "Базовый Урон, наносимый снаряженцем, увеличивается на <WeaponEffect_Num:[StateArg1]%.> Перед тем, как снаряженец освободит вознесение, лимит руки временно увеличивается на +1, и он берет 1 карту команды. Если текущее царство — \"Каро\", временный критический Урон снаряженца при активации поглощения увеличивается на <WeaponEffect_Num:[StateArg1]%>, действует не более одного раза за ход."
  },
  State_65360_Desc = {
    Text = "Уникальное команды: Базовый Урон, наносимый снаряженцем, увеличивается на <WeaponEffect_Num:[StateArg1]%. В начале боя носитель получает 25 слоев \"Снег\", после разыгрывания карты носитель получает 2 очка Алиемуса и удаляет 1 слой. После полного удаления \"Снег\" носитель получает <WeaponEffect_Num:[StateArg2]%> критического шанса."
  },
  State_65360_WeaponDesc = {
    Text = "Базовый Урон, наносимый снаряженцем, увеличивается на <WeaponEffect_Num:[StateArg1]%>. В начале боя снаряженец получает 25 слоев \"Снег\", после розыгрыша карты снаряженец получает 2 единицы Алиемуса и теряет 1 слой. После полного удаления \"Снег\" снаряженец получает <WeaponEffect_Num:[StateArg2]%> Крит. шанс (в данный момент осталось [DescArg1] слоев снега)."
  },
  State_65362_Desc = {
    Text = "После накопления [StateArg1] активных урона (осталось [Layer] раз), случайным образом применяется заморозка к 1 карте команды в руке."
  },
  State_65362_Name = {
    Text = "Вернуться инея"
  },
  State_65463_Name = {
    Text = "Получить 5 чёрной Печать пакиа"
