  },
  State_65497_Name = {
    Text = "Илот: Верига: Зонд забег"
  },
  State_65553_Desc = {
    Text = "В конце хода получает силу в зависимости от количества оставшихся карт на руке, каждая Карта дает [Layer] очков."
  },
  State_65553_Name = {
    Text = "Ледяной клинок"
  },
  State_65557_Desc = {
    Text = "После получения фатального урона восстановите все жизненные силы, намерение преобразуется в \"Истинный: взгляд космоса\", получите 80 слоёв временного укрепления и снимите с себя негативные состояния и положительные состояния с игрока. В конце хода удалите 20 слоёв укрепления."
  },
  State_65557_Name = {
    Text = "Древний хаос"
  },
  State_65558_Desc = {
    Text = "После получения фатального урона намерение преобразуется в \"Взгляд из Глубокого Космоса\" и вы получите 80 слоёв временного укрепления, восстановите все жизни, может сработать [DescArg1] раз. После исчерпания количества срабатываний, при получении фатального урона останется 1 жизнь, и намерение изменится на \"Глаза мириадов миров\". В конце хода удалите 20 слоёв укрепления."
  },
  State_65558_Name = {
    Text = "Звёздная осколок"
  },
  State_65559_Desc = {
    Text = "После гибели всего Тоху ва-боху возродится."
  },
  State_65559_Name = {
    Text = "Обломки древности"
  },
  State_65564_Name = {
    Text = "\n<D05EX_Relic:Участники экспедиции всё больше сомневаются в Шило, тебе нужно сделать выбор до того, как враг подойдёт, чтобы утихомирить команду>"
  },
  State_65565_Name = {
    Text = "\n<D05EX_Relic:игнорируя подозрения членов группы, продолжить двигаться вперёд>"
