  State_65566_Name = {
    Text = "\n<D05EX_Relic:объяснение ситуации членам экспедиции>"
  },
  State_65567_Name = {
    Text = "\n<D05EX_Relic:сдерживание Шило для дальнейшей защиты членов группы>"
  },
  State_65568_Name = {
