  },
  State_66308_Name = {
    Text = "Древний хаос"
  },
  State_66311_Desc = {
    Text = "Воспоминания о пробуждённых хлынут из края твоего сознания, укоренятся и вырастут в твоем мозгу. Сколько бы раз ты их ни разрывал, сколько бы раз Раствориться ни опрокидывало их, они никогда не покидали тебя."
