  State_66311_Name = {
    Text = "Разбитые воспоминания"
  },
  State_66313_Desc = {
    Text = "Каждый раз, когда вы играете 1 карту команды, отбрасывайте 1 карту с наименьшим расходом вычислительной мощности этого пробуждающего тела."
