  State_66314_Desc = {
    Text = "Неуязвим к любому урону."
  },
  State_66314_Name = {
    Text = "Полный Иммунитет к урону"
  },
  State_66317_Desc = {
    Text = "Воспоминания о Пробуждённых вырываются из краёв вашего разума, укореняются и растут в вашем сознании. Сколько бы раз вы их ни отрубали, сколько бы раз Раствориться ни опрокидывало их, они никогда не покидали вас. В начале каждого хода восстанавливается 1 единица лимита арифметики и 2 единицы лимита руки."
  },
  State_66317_Name = {
    Text = "Осколки памяти"
  },
  State_66325_Desc = {
    Text = "Воспоминания о Пробуждённых вырываются из краёв вашего разума, укореняются и растут в вашей голове. Сколько бы раз вы их ни прерывали, сколько бы раз Раствориться ни свергало их, они никогда не покидали вас. В начале каждого хода восстанавливается 1 единица лимита арифметики и 2 единицы лимита руки."
