  State_66555_Name = {
    Text = "Шприц активности"
  },
  State_66556_Desc = {
    Text = "Каждый раз, когда вы разыгрываете карты одного и того же пробуждающего тела подряд, это пробуждающее тело получает 8 безумия."
  },
  State_66556_Name = {
    Text = "Хронометр"
  },
  State_66557_Desc = {
    Text = "Каждый раз, когда вы теряете жизнь, получите [DescArg1] очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Максимум 10 стаков за бой. Когда стаки заполняются, Лечение 25% утраченной жизни."
  },
  State_66557_Name = {
    Text = "Высочайшая почесть"
  },
  State_66558_Desc = {
    Text = "Каждые 3 хода добавляйте 1 Уровень <WeaknessIconKeywords:слабость> ко всем врагам. Наносите Урон врагам с <WeaknessIconKeywords:слабость>, получая [DescArg1] временного <PowerIconKeywords:силы>, до 3 раз за ход."
  },
  State_66558_Name = {
    Text = "Злой ребёнок"
  },
  State_66559_Desc = {
    Text = "При разыгрывании карты с расходом вычислительной мощности 3 или выше, возьмите 1 карту и получите 1 единицу вычислительной мощности."
  },
  State_66559_Name = {
    Text = "Утраченная красота"
  },
  State_66560_Desc = {
    Text = "«ударить» получить 2 единицы арифметики, случайным образом сбросить 1 карту; «защита» взять 2 карты, потерять 1 единицу арифметики. Максимум 3 срабатывания за ход."
  },
  State_66560_Name = {
    Text = "Счастливая пластинка"
  },
  State_66561_Desc = {
    Text = "Каждые 3 хода добавляйте 1 Уровень <VulnerabilityIconKeywords:уязвимость> ко всем врагам. Наносите Урон врагам с <VulnerabilityIconKeywords:уязвимость>, заставляя их потерять [DescArg1] единиц временного <PowerIconKeywords:силы>, до 3 раз за ход."
  },
  State_66561_Name = {
    Text = "Ритуал весны"
  },
  State_66562_Desc = {
    Text = "Каждые 4 хода удваивается Урон всем врагам в текущем ходу. Однако, если в этом ходу используется вспышка безумия, все пробуждающие тела будут запечатаны на 1 ход."
  },
  State_66562_Name = {
    Text = "Останки следопыта"
  },
  State_66563_Desc = {
    Text = "В начале хода, если в прошлом ходу было сыграно более 3 карт, вытяните 2 карты."
  },
  State_66563_Name = {
    Text = "Новенький бумажник"
  },
  State_66564_Desc = {
    Text = "При подборе вы получаете 3 единицы вычислительной мощности."
  },
  State_66564_Name = {
    Text = "Зеркальце карманных часов"
  },
  State_66565_Desc = {
    Text = "При подборе накладывает на всех врагов 1 ход <WeaknessIconKeywords:слабость> и <VulnerabilityIconKeywords:уязвимость>."
  },
  State_66565_Name = {
    Text = "Сменная смирительная рубашка"
  },
  State_66566_Desc = {
    Text = "Каждый ход в начале <DeathResistanceIconKeywords:Сопротивление смерти> увеличивается на 10% (каждый раз, когда срабатывает Сопротивление смерти в этом уровне, полученное Сопротивление смерти уменьшается вдвое). Когда <DeathResistanceIconKeywords:Сопротивление смерти> выше 100%, <ProficientInRealmsIconKeywords:Мастерство царства> увеличивается на 100."
  },
  State_66566_Name = {
    Text = "Слеза сирены"
  },
  State_66703_Desc = {
    Text = "Команда уникальна: лимит накопления серебряного ключа увеличен на 100%. Лимит руки +2, не складывается с лимитом рук, предоставляемым другими колесами судьбы. Готовьсь! серебряного ключа снаряженца увеличивается на <WeaponEffect_Num:[StateArg1]%>. После разыгрывания карты снаряженца, в этом ходу критический шанс и критический Урон карты команды, а также щиты, алиемус и Огромная Огромная сила снаряженца увеличиваются на <WeaponEffect_Num:[StateArg2]%>, максимум 5 стаков."
  },
  State_66703_WeaponDesc = {
    Text = "Максимум накопления серебряного ключа увеличивается на 100%. Лимит руки +2, не накладывается с другими лимитами рук, предоставляемыми судьбой. Восст. ключесвета носителя увеличивается на <WeaponEffect_Num:[DescArg2]>. После разыгрывания карты носителем, в этом ходу крит. шанс и крит. Урон карт команды носителя, а также щит, Алиемус и Огромная Огромная Огромная Огромная сила увеличиваются на <WeaponEffect_Num:[StateArg2]%>, максимум 5 слоев (текущие [DescArg1] слоев)."
  },
  State_66722_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: При экипировке и в начале хода, если у вас нет <PVPProtectiveKeywords:Барьер>, получите [StateArg1] слоев <PVPProtectiveKeywords:Барьер>, иначе получите <StrengthenKeywords:Усиление>."
  },
  State_66722_Name = {
    Text = "Колесо уединённого мира"
  },
  State_66872_Desc = {
