  State_66884_Desc = {
    Text = "Ход завершен, расход вычислительной мощности уменьшается, Эффект также срабатывает при выбрасывании."
  },
  State_66884_Name = {
    Text = "<PrepareKeypvewords:Готовность1>"
  },
  State_66888_Desc = {
    Text = "Уникальное команды: после освобождения ключевого приказа получить силу, равную атакующей силе снаряженца <WeaponEffect_Num:[StateArg1]%> <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> и щит, равный силе защиты <WeaponEffect_Num:[StateArg2]>. После использования Тела Гнозис экстренного реагирования, в конце хода все пробуждённые получают <WeaponEffect_Num:[StateArg3]> очков безумия."
  },
  State_66888_Name = {
    Text = "Серебряное сердце"
  },
  State_66888_WeaponDesc = {
    Text = "После освобождения ключевого приказа получите <WeaponEffect_Num:[Power:DescArg1]> очков <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> и <WeaponEffect_Num:[Block:DescArg2]> очков щита. После использования Тела Гнозис экстренного реагирования, в конце хода все пробуждённые получают <WeaponEffect_Num:[StateArg3]> очков Алиемус."
  },
  State_66893_Desc = {
    Text = "Уникальное команды: после начала битвы получаете <WeaponEffect_Num:[StateArg1]%> серебряной энергии, равной заряду серебряного ключа снаряженца. При первом использовании ключевого приказа в каждой битве Эффект повторяется."
  },
  State_66893_WeaponDesc = {
