  },
  State_67235_Desc = {
    Text = "При смерти восстанавливает всё здоровье, максимальное здоровье увеличивается на 100%, применяется \"душевная Чума\"."
  },
  State_67235_Name = {
    Text = "Невознесённый"
  },
  State_67237_Desc = {
    Text = "Достигнув 10 уровня, намерение изменится на \"Безысходный Конец\": уменьшит максимальное здоровье противника до 1."
  },
  State_67237_Name = {Text = "Конец"},
  State_67238_Desc = {
    Text = "В конце хода получите 1 слой \"конца\". После получения фатального урона, удалите это состояние и получите Иммунитет к урону на 1 ход, восстановите 15% здоровья и получите 10 слоёв \"конца\"."
  },
  State_67238_Name = {
    Text = "Порча души"
  },
  State_67240_Desc = {
    Text = "\"Знающий\" получает 25 уровней временного <ReinforcePVEKeywords:укрепление> и [Power:StateArg1] единиц временной <PowerIconKeywords:силы>. Удалить это состояние."
  },
  State_67240_Name = {
    Text = "<TuiyanColour:дедукция>"
  },
  State_67241_Desc = {
    Text = "Ответ восстанавливает всю жизнь при смерти, максимальная жизнь увеличивается на 100%, освобождает \"рыцарский пыл\"."
  },
  State_67241_Name = {
    Text = "Невознесённый"
  },
  State_67242_Desc = {
    Text = "При смерти восстанавливает всё Жизнь, максимальное здоровье +100%, выпускает «Дух и плоть@1мин»。"
  },
  State_67242_Name = {
    Text = "Невознесённый"
  },
  State_67243_Desc = {
    Text = "Ход завершен. Призыв «Фрагмент мозга в банке». Когда Фрагмент мозга в банке активирует «Разделение интеллекта», дополнительно крадет 5% силы игрока."
  },
  State_67243_Name = {
    Text = "От@1нная Плоть"
  },
  State_67245_Desc = {
    Text = "Ход завершен, получите [StateArg1] единиц <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_67245_Name = {
    Text = "Рвение рыцаря"
  },
  State_67246_Desc = {
    Text = "При первом разрушении щита за ход потеряйте 25% от максимального здоровья, получите [Power:DescArg1] очков <PowerIconKeywords:Врем. Огромная Огромная Огромная сила▼> и [Layer] слоев временного укрепления. В начале следующего хода восстановите <Block:[Block:DescArg2]> слоев щита, за каждое срабатывание \"Веры рыцаря\" дополнительно получите 1 щит."
  },
  State_67246_Name = {
    Text = "Вера рыцаря"
  },
  State_67247_Desc = {
    Text = "В конце каждого хода восстанавливаются враги, одновременно может существовать не более 2 врагов. После смерти врага \"Гниющий мозг\" теряет 5% максимального здоровья."
  },
  State_67247_Name = {
    Text = "Ворота бездны"
  },
  State_67252_Desc = {
    Text = "При получении смертельного урона переместитесь на заднюю линию и сохраните 1 единицу жизни, после чего не сможете получить никакого урона. <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> увеличивает [DescArg1]. Саморазрушение не активирует этот Эффект."
  },
  State_67252_Name = {
    Text = "Разделение духа"
  },
  State_67253_Desc = {
    Text = "После того, как будет сыграно [Layer] карт, впереди появится 1 \"мозг в банке\", максимальное количество одновременно существующих — 3."
  },
  State_67253_Name = {
    Text = "Мозг в колбе"
  },
  State_67255_Desc = {
    Text = "При смерти восстановить все жизни, максимальное значение жизни +100%, применить \"первая философия\"."
  },
  State_67255_Name = {
    Text = "Невознесённый"
  },
  State_67256_Desc = {
    Text = "После фазы вытягивания карт из руки случайно показываются три карты команды. Выберите одну и наделите её гравировкой \"Эхо\", остальные карты сбросьте."
  },
  State_67256_Name = {
    Text = "Первая доктрина"
  },
  State_67257_Desc = {
    Text = "Каждый ход после первого освобождения ключевого приказа все пробуждающие тела получают +10 к безумию, но стоимость его применения навсегда возрастает на 10%."
  },
  State_67257_Name = {
    Text = "Постепенно рвущаяся связь"
  },
  State_67258_Desc = {
    Text = "Бой начинается, получить <Block:[Block:DescArg1]> слоёв щита. Ход завершен, щит не исчезает."
  },
  State_67258_Name = {
    Text = "Решимость рыцаря"
  },
  State_67347_Desc = {
    Text = "В руке: если верхняя Карта колоды для розыгрыша является картой команды, она копируется с уменьшением расхода вычислительной мощности на 1."
  },
  State_67347_Name = {
    Text = "Всеведение тысячи истин"
  },
  State_67353_Desc = {
    Text = "После смерти \"Гниющий мозг\" теряет 5% максимального здоровья."
  },
  State_67353_Name = {
    Text = "Расплавление"
  },
  State_67358_Desc = {
    Text = "Каждый раз, когда игрок расходует 1 единицу вычислительной мощности, он немедленно получает <Block:[Block:StateArg1]> щита и 3 слоя временного укрепления."
  },
  State_67358_Name = {
    Text = "Нестабильный барер"
  },
  State_67414_Desc = {
    Text = "Не подлежит прямому взгляду глаз. Неопровержимый дух. Фрагменты, способные на всё, остаются лишь фрагментами. Теперь, встречай предопределённый Конец разрушения..."
  },
  State_67414_Name = {
    Text = "Противостоять мириадам источников"
  },
  State_67418_Desc = {
    Text = "После розыгрыша сбросьте все карты, не связанные с этим пробуждением, получите 5 случайных карт, не связанных с пробуждением. Эффект срабатывает только 1 раз за бой."
  },
  State_67418_Name = {
    Text = "<WhiteQuality:высший логика удовольствия>"
  },
  State_67419_Desc = {
    Text = "После использования получите 3 исходные копии с <RetainIconKeywords:сохранением> и <DepleteIconKeywords:расходом>, их арифметическая цена –1, Эффект срабатывает только 1 раз за бой."
  },
  State_67419_Name = {
    Text = "<WhiteQuality:высшая Принцип размножения>"
  },
  State_67420_Desc = {
    Text = "После разыгрывания вытяните 4 карты, уменьшите их расход арифметики на фактический расход арифметики гравировочной карты, Эффект срабатывает только 1 раз за бой."
  },
  State_67420_Name = {
    Text = "<WhiteQuality:Высшая Причина Мудрости>"
  },
  State_67598_Desc = {
    Text = "После освобождения вспышки безумия поместите в руку случайную карту, соответствующую пробуждённому. Эта Карта получает <DepleteIconKeywords:расход> и <NothingnessIconKeywords:Ускользание>. После завершения боя восстановите [DescArg1] единиц жизни."
  },
  State_67598_Name = {
    Text = "Докторский саквояж"
  },
  State_67599_Desc = {
    Text = "Не «ударить» и «защита» карты команды, после разыгрывания, соответствующий пробуждённый получает 15 очков алиемуса, максимум 5 раз за ход. При первом срабатывании за ход, разыгранная Карта также возвращается в руку."
  },
  State_67599_Name = {
    Text = "Маятник времени: проекция"
  },
  State_67600_Desc = {
    Text = "Максимальная вычислительная мощность повышена на 4. При каждом сбросе колоды добавьте 4 карты <DerivativeCardKeywords_4:\"вдохновение\"> в колоду для розыгрыша."
  },
  State_67600_Name = {
    Text = "Благословление: чёрная свеча"
  },
  State_67602_Name = {
    Text = "Утилизировано"
  },
  State_67603_Desc = {
    Text = "Усиление урона, наносимого врагам в негативном состоянии, на 20%. При убийстве врага, Ассасин получает 20 безумия."
  },
  State_67603_Name = {
    Text = "Жреческий жезл"
  },
  State_67604_Desc = {
    Text = "Каждый раз, когда вы разыгрываете карту команды, принадлежащую другому пробуждённому, он получает 3 очка Алиемуса и накапливает 1 Уровень \"Жизнелюбия\". При накоплении 10 уровней все \"Жизнелюбие\" сбрасываются, и в руку помещается по одной случайной карте команды с расходом арифметики, которая уменьшает стоимость на 1 и имеет свойства \"расход\" для каждого пробуждённого. Максимум 1 раз за ход."
  },
  State_67604_Name = {
    Text = "Маятник времени: эволюция"
  },
  State_67605_Desc = {
    Text = "Когда у вас есть щит, это создание предоставляет [DescArg1] единиц <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Когда ваш щит выше текущей жизни, дополнительно даётся [DescArg2] единиц <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_67605_Name = {
    Text = "Веер из голубиных перьев"
  },
  State_67606_Desc = {
    Text = "В начале хода за каждого врага получаете 1 единицу арифметики. При убийстве врага активным уроном наносите остальным врагам кровотечение <BleedingIconKeywords:кровотечение>, равное избыточному урону."
  },
  State_67606_Name = {
    Text = "Песнь толпы"
  },
  State_67607_Desc = {
    Text = "После каждых 5 применений вспышки безумия пробуждающее тело, использовавшее вспышку безумия, получает 100 безумия."
  },
  State_67607_Name = {
    Text = "Крошечная пелёнка"
  },
  State_67608_Name = {
    Text = "Утилизировано"
  },
  State_67609_Desc = {
    Text = "После освобождения вспышки безумия, потеряйте 8% текущей жизни, украдите у всех врагов [DescArg1] единиц временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Если только 1 враг, дополнительно украдите [DescArg2] единиц временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_67609_Name = {
    Text = "Птица ритуала несчастья"
  },
  State_67611_Desc = {
    Text = "Каждые 2 хода Урон всем врагам удваивается, и в этом ходу за каждое освобождение вспышки безумия случайно нейтрализуется 1 негативное состояние."
  },
  State_67611_Name = {
    Text = "Благословление: останки следопыта"
  },
  State_67612_Desc = {
    Text = "Все критические удары навыка \"ударить\" наносят на 20% больше урона. При подборе добавьте в руку 1 карту <DerivativeCardKeywords_40:\"Прекрасное мгновение\">."
  },
  State_67612_Name = {
    Text = "Прекрасное мгновение β"
  },
  State_67614_Desc = {
    Text = "В начале каждого хода все пробуждающие тела получают 25 безумия. При подборе максимальное здоровье становится в 1.5 раза больше."
  },
  State_67614_Name = {
    Text = "Благословление: кошмарный манифест β"
  },
  State_67615_Desc = {
    Text = "Каждая шестая Командная Карта возвращается из сброса в руку."
  },
  State_67615_Name = {
    Text = "В сумерках"
  },
  State_67616_Name = {
    Text = "Утилизировано"
  },
  State_67618_Desc = {
    Text = "В начале каждого хода все пробуждающие тела получают 25 безумия. При подборе предмета максимальное здоровье становится в 1.5 раза больше."
  },
  State_67619_Desc = {
    Text = "Максимальное количество карт на руке увеличивается на 5. При получении восполните карты до максимума. В начале хода дополнительно тяните 1 карту, в конце хода сбросьте все симптом карты и карточки состояния на руках, сохраните другие карты."
  },
  State_67619_Name = {
    Text = "Благословление: мысленная гравюра β"
  },
  State_67620_Desc = {
    Text = "После разыгрывания третьей карты в каждом раунде поместите 1 карту <DerivativeCardKeywords_4:\"Озарение\"> в сброс. После разыгрывания Часит 6 карты в каждом раунде возьмите 1 карту <DerivativeCardKeywords_4:\"Озарение\"> из сброса в руку."
  },
  State_67620_Name = {
    Text = "Светоч цивилизации"
  },
  State_67621_Desc = {
    Text = "После освобождения вспышки безумия, получите [DescArg1] очков временной силы и украдите у всех врагов [DescArg1] единиц временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Если только 1 враг, дополнительно украдите [DescArg2] единиц временной <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_67621_Name = {
    Text = "Благословление: знамение ритуальной птицы"
  },
  State_67622_Desc = {
    Text = "При исчерпании последней единицы вычислительной мощности, получите 2 вычислительные мощности. Максимум 2 раза за ход."
  },
  State_67622_Name = {
    Text = "Дифференциальный двигатель"
  },
  State_67623_Desc = {
    Text = "После подбора навсегда получите [DescArg1] <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>. Каждый раз, нанося Урон, восстанавливаете [DescArg2] единиц жизни, максимум 6 раз за ход."
  },
  State_67623_Name = {
    Text = "Благословление: поцелуй миноги"
  },
  State_67624_Name = {
    Text = "Утилизировано"
  },
  State_67625_Desc = {
    Text = "При первом использовании карты команды за ход она помещается в сброс, а временная Копия этой карты с уменьшением расхода вычислительной мощности на 1 перетасовывается в колоду для розыгрыша."
  },
  State_67625_Name = {
    Text = "Безмолвный граммофон"
  },
  State_67626_Desc = {
    Text = "Макс. арифметика увеличивается на 1. Если подряд разыграть 2 карты с бо́льшим расходом вычислительной мощности, чем у предыдущей, получите 1 единицу арифметики."
  },
  State_67626_Name = {
    Text = "Мистический архив"
  },
  State_67628_Name = {
    Text = "Утилизировано"
  },
  State_67630_Name = {
    Text = "Утилизировано"
  },
  State_67631_Desc = {
    Text = "Максимальная вычислительная мощность повышена на 2. При каждом сбросе колоды добавляется 1 Карта <DerivativeCardKeywords_9:\"шатаясь\"> в колоду для розыгрыша."
  },
  State_67631_Name = {
    Text = "Чёрная свеча"
  },
  State_67632_Name = {
    Text = "Утилизировано"
  },
  State_67634_Desc = {
    Text = "Ход завершен: за каждую неиспользованную карту в руке все пробуждающие тела получают 2 безумия."
  },
  State_67634_Name = {
    Text = "Наклонённые весы"
  },
  State_67635_Desc = {
    Text = "При подборе все пробуждающие тела получают 50 очков безумия, а 2 карты <DerivativeCardKeywords_1:\"Эхо призрачного образа\"> перемешиваются в колоду для розыгрыша."
  },
  State_67635_Name = {
    Text = "Средство связи +β"
  },
  State_67636_Desc = {
    Text = "Критический Урон увеличивается на 15%. Урон, наносимый врагам с щитом, всегда будет критическим ударом."
  },
  State_67636_Name = {
    Text = "Принципы эстетики"
  },
  State_67637_Desc = {
    Text = "В начале хода возьмите 2 карты, получите 2 единицы арифметики. Каждый раз, когда вы берете 1 карту команды или Возвышение, её стоимость в арифметике меняется случайным образом (0-4)."
  },
  State_67637_Name = {
    Text = "Шляпа кудодесника"
  },
  State_67638_Desc = {
    Text = "Усиление урона на 50% против врагов в негативном состоянии, после убийства врага Ассасин получает 100 единиц безумия."
  },
  State_67638_Name = {
    Text = "Жезл жреца+"
  },
  State_67639_Desc = {
    Text = "Шанс критического удара увеличивается на 50%, а Урон от критического удара — на 100%."
  },
  State_67639_Name = {
    Text = "Благословление: жуткий крючок"
  },
  State_67640_Desc = {
    Text = "Крит. шанс и крит. Урон увеличены на 100%. За каждое нанесение урона/ущерба от щупалец в этом ходу: у всех пробуждённых крит. Урон и крит. Урон снижается на 10%, максимум на 50%. Нанесённый яд и Контратака увеличиваются на 10%, максимум на 50%."
  },
  State_67640_Name = {
    Text = "Маятник времени: всплеск"
  },
  State_67641_Desc = {
    Text = "После освобождения \"вспышка безумия\" получите [DescArg1] временных <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_67641_Name = {
    Text = "Стальной замок"
  },
  State_67643_Desc = {
    Text = "При нанесении активного урона получаете [DescArg1] очков щита. При ответе жизни получаете [DescArg2] временной бонус <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>."
  },
  State_67643_Name = {
    Text = "Наш дом"
  },
  State_67645_Desc = {
    Text = "Шанс критического удара увеличивается на 10%. После первого критического удара в каждом ходу шанс критического удара дополнительно увеличивается на 20%, после третьего критического удара в каждом ходу критический Урон дополнительно увеличивается на 50%."
  },
  State_67645_Name = {
    Text = "Праздничное благословение"
  },
  State_67646_Desc = {
    Text = "В конце нечетного хода, если осталась арифметика, в следующем ходу дополнительно возьмите 2 карты; в конце четного хода, если остались карты в руке, в следующем ходу получите 2 единицы арифметики."
  },
  State_67646_Name = {
    Text = "Солнечный диск"
  },
  State_67647_Desc = {
    Text = "Каждая пятая Командная Карта, которую вы разыгрываете, сработает дважды и вернётся в руку."
  },
  State_67647_Name = {
    Text = "виноградное Прекрасное Прекрасное Прекрасное Прекрасное вино звёзд+"
  },
  State_67649_Desc = {
    Text = "Скрыть намерения монстра. Каждый ход получать 1 очко вычислительной мощности, вытягивать 1 карту."
  },
  State_67649_Name = {
    Text = "Чарующий колокольчик"
  },
  State_67650_Desc = {
    Text = "«ударить»и «защита» дополнительно получают 50 очков Ключесвета. Каждый раз, когда вы разыгрываете карту с ценой в арифметике 2 или больше, возьмите 1 карту с ценой в арифметике 1 и установите её цену в арифметике равным 0, максимум 3 раза за ход."
  },
  State_67650_Name = {
    Text = "Маятник времени: близнецы"
  },
  State_67651_Desc = {
    Text = "При подборе мастерство царства команды становится 150% от исходного значения. После разыгрывания 5-й карты команды за ход все пробуждённые получают 20 алиемуса."
  },
  State_67651_Name = {
    Text = "Маятник времени: нечистота"
  },
  State_67653_Desc = {
    Text = "Каждый ход после двух вспышек безумия все пробуждающие тела получают по 8 очков безумия, а после трех вспышек — еще по 8 очков безумия."
  },
  State_67653_Name = {
    Text = "Отринутая кровь"
  },
  State_67654_Name = {
    Text = "Срабатывает дополнительно [DescArg1] раз(а)"
  },
  State_67656_Desc = {
    Text = "Критический шанс увеличивается на 50%, <FragileIconKeywords:хрупкий> на себя на 3 хода."
  },
  State_67656_Name = {
    Text = "Жуткий крючок"
  },
  State_67657_Desc = {
    Text = "В начале хода возьмите 1 карту. При двукратном разыгрывании карт с той же вычислительной мощностью, что и предыдущая, дополнительно берите 1 карту, максимум 3 раза за ход."
  },
  State_67657_Name = {
    Text = "Агрегат гнозиса"
  },
  State_67658_Desc = {
    Text = "При разыгрывании карты с фактическим расходом арифметики 3, возьмите 1 карту и получите 2 арифметики; при разыгрывании карты с фактическим расходом арифметики 4 или выше, расход других карт в руке уменьшается на 1."
  },
  State_67658_Name = {
    Text = "Маятник времени: Глаза"
  },
  State_67659_Desc = {
    Text = "В начале хода за каждого врага получаете 2 единицы арифметики. При убийстве врага активным уроном наносите остальным врагам кровотечение <BleedingIconKeywords:кровотечение>, равное двойному избыточному урону."
  },
  State_67659_Name = {
    Text = "Песнь толпы+"
  },
  State_67660_Desc = {
    Text = "Каждый третий раз, когда вы применяете \"ударить\", наносится [DescArg1] урона всем врагам, и соответствующее пробуждающее тело получает 15 безумия."
  },
  State_67660_Name = {
    Text = "Ржавый ланцет"
  },
  State_67661_Desc = {
    Text = "При каждом расходе вычислительной мощности, извлеките 1 карту, максимум 5 раз за ход. При каждом Сбросе колоды, получите 2 единицы вычислительной мощности."
  },
  State_67661_Name = {
    Text = "Маятник времени: бессонница"
  },
  State_67662_Desc = {
    Text = "Каждый раз, когда вы играете карту, не являющуюся пробуждающим телом, пробуждающее тело с минимальным безумием получает 10 безумия."
  },
  State_67662_Name = {
    Text = "Альбом с иностранными марками"
  },
  State_67665_Desc = {
    Text = "Макс. арифметика увеличивается на 2. После розыгрыша «ударить» или «защита» соответствующее пробуждённое получает 5 алиемуса. После высвобождения Вознесения получите 1 карту «ударить» с расходом Ускользание, после высвобождения Воспоминания случайным образом получите 1 карту «защита» с расходом Ускользание."
  },
  State_67665_Name = {
    Text = "Маятник времени: крылья"
  },
  State_67666_Desc = {
    Text = "При каждом нанесении урона получите [DescArg1] временные <PowerIconKeywords:Огромная Огромная Огромная Огромная сила>, максимум до 3 раз. Когда стаки заполнены, Эффект удваивается."
  },
  State_67666_Name = {
    Text = "Филигранный агат"
  },
  State_67667_Desc = {
    Text = "В конце хода все пробуждающие тела получают 5 алиемуса. За каждую оставшуюся 1 единицу арифметики все пробуждающие тела дополнительно получают 3 алиемуса."
  },
  State_67667_Name = {
    Text = "Прото-батарея"
  },
  State_67668_Desc = {
    Text = "Критический Урон увеличивается на 15%. Критический шанс удара повышается на 40%."
  },
  State_67668_Name = {
    Text = "Клюв белого ворона"
  },
  State_67669_Name = {
    Text = "Утилизировано"
  },
  State_67670_Desc = {
    Text = "После освобождения вспышки безумия берите 1 карту. Если жизнь ниже 25%, берите дополнительно 1 карту."
  },
  State_67670_Name = {
    Text = "Колесо знания"
  },
  State_67671_Desc = {
    Text = "При каждом нанесении 1 активного урона Лечение [DescArg1] жизни, применяется [DescArg2] уровней <BleedingIconKeywords:кровотечение>."
  },
  State_67671_Name = {
    Text = "Благословление: разум роя"
  },
  State_67672_Desc = {
    Text = "Повышает Эффект <WeaknessIconKeywords:Слабость> на 8%, Эффект <VulnerabilityIconKeywords:Брешь> на 25%. При наложении <WeaknessIconKeywords:Слабость> или <VulnerabilityIconKeywords:Брешь> временно крадет у цели [DescArg1] пунктов <PowerIconKeywords:силы>."
  },
  State_67672_Name = {
    Text = "Пожелтевшая фотография+"
  },
  State_67673_Desc = {
    Text = "В начале хода берите 1 карту."
  },
  State_67673_Name = {
    Text = "Компас истинного севера"
  },
  State_67674_Desc = {
    Text = "Каждый раз, когда вы разыгрываете 1 карту команды, получаете [DescArg2]% <DeathResistanceIconKeywords:Сопротивление смерти> (в этом уровне за каждое срабатывание сопротивления смерти полученное сопротивление уменьшается вдвое). Если ваше <DeathResistanceIconKeywords:Сопротивление смерти> равно или превышает 100%, вместо этого получите [DescArg1] очков временной <PowerIconKeywords:силы>."
  },
  State_67674_Name = {
    Text = "Змеиная кожа"
  },
  State_67675_Desc = {
    Text = "В конце хода, если осталась арифметика, в следующем ходу дополнительно берите 2 карты; если остались карты в руке, в следующем ходу получите 2 единицы арифметики."
  },
  State_67675_Name = {
    Text = "колесо солнца и луны+"
  },
  State_67677_Desc = {
    Text = "Когда вы наносите <WeaknessIconKeywords:слабость>, получаете [DescArg1] очков щита; при нанесении <VulnerabilityIconKeywords:уязвимость>, получаете [DescArg2] временных <PowerIconKeywords:силы>. Если оба эффекта были активированы в течение 1 хода, дополнительно получаете [DescArg1] очков щита и [DescArg2] временных <PowerIconKeywords:силы>."
  },
  State_67677_Name = {
    Text = "Позолоченная рамка"
  },
  State_67703_Desc = {
    Text = "В начале хода, если на предыдущем ходу осталось более 3 карт в руке, получите 2 вычислительной мощности."
  },
  State_67703_Name = {
    Text = "Эмблема Мисаг"
  },
  State_67704_Desc = {
    Text = "После освобождения \"вспышка безумия\", соответствующее пробуждающее тело получает 10 безумия и [DescArg1] единиц щита."
  },
  State_67704_Name = {
    Text = "Вуаль безымянного божества"
  },
  State_67796_Name = {
    Text = "<TongxiaoKeywords:понимание всех вещей>: после использования восстанавливается, вы получаете <Energy:[StateArg1]> единиц безумия"
  },
  State_67841_WeaponDesc = {
    Text = "Изменить мощность карты перед использованием"
  },
  State_67844_Desc = {
    Text = "Восстанавливает все здоровье после получения критического урона, может быть активирован @1 раз, текущий активирован [DescArg1] раз."
  },
  State_67844_Name = {
    Text = "Древний хаос"
  },
  State_67866_Name = {
    Text = "<BleedingColour: кровотечение>"
  },
  State_68298_Desc = {
    Text = "После получения фатального урона намерение превращается в \"Взгляд из Глубокого Космоса\" и получает 80 слоёв временного укрепления, восстанавливает все жизненные силы, может быть активирован [DescArg1] раз. В конце хода удаляет 20 слоёв укрепления."
  },
  State_68298_Name = {
    Text = "Звёздная осколок"
  },
  State_68554_Desc = {
    Text = "Восстанавливает все здоровье после получения критического урона, состояние удаляется после смерти всех остальных врагов. Может быть активирован @1 раз, текущий активирован [DescArg1] раз."
  },
  State_68554_Name = {
    Text = "Обломки изначального хаоса"
  },
  State_68621_Desc = {
    Text = "В начале боя и в конце каждого хода получает 2 слоя временной <ResentChainsKeywords:Цепи ненависти>."
  },
  State_68621_Name = {
    Text = "Зловещий поток"
  },
  State_68622_Desc = {
    Text = "Огромная Огромная Огромная Огромная сила, накладываемая пробуждающим телом, уменьшена на 75%. При каждой потере жизни получите [DescArg1] очков щита и 1 слой временное Усиление."
  },
  State_68622_Name = {
    Text = "Поток злой веры"
  },
  State_68623_Desc = {
    Text = "Каждый раз, когда вы играете 1 карту команды, отбрасывайте 1 карту с наименьшим расходом вычислительной мощности этого пробуждающего тела."
  },
  State_68623_Name = {
    Text = "Поток безумия"
  },
  State_68624_Desc = {
    Text = "Ход завершен. Восстанавливается 10% потерянной жизни, снимаются негативные состояния с себя и положительные состояния с игрока."
  },
  State_68624_Name = {
    Text = "Поток рождения"
  },
  State_68626_Desc = {
    Text = "Базовый алиемус всех Пробуждённых увеличивается на 50%. В конце каждого хода у всех Пробуждённых отнимается 10 единиц Алиемуса, восстанавливая 3% Макс. ОЗ."
  },
  State_68626_Name = {
    Text = "Поток ужаса"
  },
  State_68627_Desc = {
    Text = "В начале боя получите 15 слоёв \"Временный Барьер\". В конце хода получите 15 слоёв \"Временный Барьер\" и добавьте \"Временное Раствориться\" к 10 случайным картам."
  },
  State_68627_Name = {
    Text = "Ледянящий поток"
  },
  State_68632_Desc = {
    Text = "Все карты команды увеличивают расход вычислительной мощности на 1. Каждые 3 хода в конце хода вы получите 1 карту \"Окаменевание\"."
  },
  State_68632_Name = {
    Text = "Поток плача"
  },
  State_68635_Name = {
    Text = "«Чистосеребряное ядро · Страх»"
  },
  State_68637_Desc = {
    Text = "При потере жизни уменьшите соответствующее количество уровней. Когда Уровни достигают 0, игрок получает 2 уровня временного барьера, получает [DescArg1] Уровень щита и [DescArg2] Уровень временной крепости, а также восстанавливает [DescArg3] Уровень измерения барьера."
  },
  State_68637_Name = {
    Text = "Бастион измерения"
  },
  State_68638_Name = {
    Text = "«Чистосеребряное ядро · Ересь»"
  },
  State_68646_Desc = {
    Text = "Базовый Урон и значение щита увеличены на 200%, но будут расход после использования."
  },
  State_68646_Name = {
    Text = "<RedQuality1:временное Раствориться>"
  },
  State_68647_Name = {
    Text = "«Ядро чистого звука · Безумие»"
  },
  State_68680_Desc = {
    Text = "Удалить обломки изначального"
  },
  State_68680_Name = {
    Text = "Удалить обломки изначального"
  },
  State_68704_Desc = {
    Text = "До истинного прибытия товарищества осталось [DescArg1] ходов.."
  },
  State_68704_Name = {
    Text = "Нисхождение"
  },
  State_68829_Desc = {
    Text = "При получении активного урона или урона щупалец, получает иммунитет к урону и уменьшает 1 слой, снимается в начале хода."
  },
  State_68829_Name = {
    Text = "<ParcloseColour: Барьер>"
  },
  State_68829_WeaponDesc = {
    Text = "Получаемый урон снижен на 99%, при каждом получении урона уменьшается на 1 уровень."
  },
  State_70026_Desc = {
    Text = "Эта Карта имеет \"Удержание\", после розыгрыша временный критический шанс всех пробуждённых увеличивается на [StateArg1]％ и удаляет \"Бессмертное владычество\". Если текущее Царство - Эквор, после удаления \"Бессмертного владычества\" получите 1 очко Арифметики."
  },
  State_70026_Name = {
    Text = "<OrangeQuality:бессмертное владычество>"
  },
  State_70031_Desc = {
    Text = "Уникальное команды: При начале боя наделите все карты команды с расходом вычислительной мощности 3 или более в колоде для розыгрыша эффектом \"Бессмертное владычество\": эта Карта получает \"Удержание\", после разыгрывания временный критический шанс всех пробуждённых увеличивается на <WeaponEffect_Num:[StateArg1]%> и Эффект \"Бессмертное владычество\" удаляется. Если текущее царство — Эквор, то после удаления \"Бессмертного владычества\" получите 1 единицу арифметики."
  },
  State_70031_WeaponDesc = {
    Text = "В начале боя наделите все карты команды с расходом вычислительной мощности 3 или выше в колоде для розыгрыша эффектом \"Бессмертное владычество\": эта Карта получает \"Удержание\", после разыгрывания все пробуждённые получают временный крит. шанс, увеличенный на <WeaponEffect_Num:[StateArg1]%>, и Эффект \"Бессмертное владычество\" снимается. Если текущее царство — Эквор, то после снятия \"Бессмертного владычества\" получите 1 единицу арифметики."
  },
  State_70182_Desc = {
    Text = "Полученные все щиты уменьшены на [DescArg1]%."
  },
  State_70182_Name = {
    Text = "<FragileColour:хрупкий>"
  },
  State_70182_WeaponDesc = {
    Text = "Все полученные щиты уменьшаются на 33 %."
  },
  State_70277_Desc = {
    Text = "После получения активного урона или урона щупалец [StateArg1]% урона преобразуется в восполнение Багрового горнила, длится [Layer] хода."
  },
  State_70277_Name = {
    Text = "Ритуал Творения"
  },
  State_70287_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: В конце хода увеличьте Урон, лечение и щиты всех «Навыков» владельца в руке на [StateArg1] %."
  },
  State_70287_Name = {
    Text = "Каменный трон"
  },
  State_70288_Desc = {
    Text = "Урон, лечение и щит, нанесённые этой картой, увеличиваются на [DescArg1]%."
  },
  State_70288_Name = {
    Text = "Каменный трон"
  },
  State_70313_Desc = {
    Text = "В бою с боссом в начале каждого хода и после выпуска способности \"Расплавленный Дор\" Сумасшедшее всплеск, получает 1 Уровень эффекта \"<Zhongmowuqiling:Конец света>\". Эффект \"Конец света\" может накопиться до 10 уровней. При достижении 10 уровней, 1 Карта \"Пустотное завершение\" добавляется в руку."
  },
  State_70313_Name = {
    Text = "Путь уничтожения"
  },
  State_70318_Desc = {
    Text = "Накладывает [StateArg1] ходов <VulnerabilityIconKeywords:Уязвимости> на всех врагов, получает состояние «Неистовство» на 1 ход: Усиление урона +[StateArg2]%."
  },
  State_70318_Name = {
    Text = "Безумие"
  },
  State_70322_Desc = {
    Text = "При наличии 10 слоёв конца, поместите 1 карту \"Безысходный Конец\" в руку."
  },
  State_70322_Name = {Text = "Конец"},
  State_70330_Desc = {
    Text = "Получить состояние «Неистовство» на 1 ход: Усиление урона +[Arg2]%."
  },
  State_70330_Name = {
    Text = "Безумие"
  },
  State_70346_Desc = {
    Text = "Наложить на всех врагов состояние <WeaknessIconKeywords:слабость> на [StateArg1] ход и уменьшить их <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> на [Exhaustion:StateArg3] очков в этом ходу."
  },
  State_70346_Name = {
    Text = "Проклятие"
  },
  State_70347_Desc = {
    Text = "Всем врагам снижается Огромная Огромная Огромная Огромная сила на [Exhaustion:StateArg3] единиц <PowerIconKeywords:Огромная Огромная Огромная Огромная сила> в этом ходу."
  },
  State_70347_Name = {
    Text = "Проклятие"
  },
  State_70374_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Первые [StateArg1] раз(а) за ход, когда носитель получает атаку, наносит <PVPEmptinessKeywords:Пустоту> атакующему."
  },
  State_70374_Name = {
    Text = "Марионетка забвения"
  },
  State_70379_Desc = {
    Text = "Накладывает на атакующего <PVPEmptinessKeywords:Пустоту>. Снимает это состояние после получения атаки."
  },
  State_70379_Name = {
    Text = "Контратака пустоты"
  },
  State_70443_Desc = {
    Text = "При наличии 10 слоёв конца, поместите 1 карту \"Безысходный Конец\" в руку."
  },
  State_70443_Name = {Text = "Конец"},
  State_70539_Name = {
    Text = "Порча души"
  },
  State_70589_Desc = {
    Text = "При разыгрывании 2 карт подряд с меньшим расходом вычислительной мощности, чем предыдущая, накладывается Урон отравлением на всех врагов (40/80), максимум 5 раз за ход."
  },
  State_70590_Desc = {
    Text = "Каждый ход после первого использования эмбриона в этом ходу активный Урон будет вызывать кровотечение на 15/30% от нанесенного урона."
  },
  State_70593_Desc = {
    Text = "После разыгрывания непроизводной карты команды, создайте 1/2 временные копии этой карты с уменьшенной на 2 стоимостью и перетасуйте их в колоду для розыгрыша, время перезарядки 3 хода."
  },
  State_70594_Desc = {
    Text = "Если вы находитесь в состоянии прилива, то в конце хода получите Урон шупалец в размере 32/64 единиц с временем восстановления 3 хода."
  },
  State_70595_Desc = {
    Text = "Бой начинается, накладывает 1280 отравление на всех врагов, Эффект удваивается в бою с лидером."
  },
  State_70598_Desc = {
    Text = "Каждый раз, когда Карта попадает в Ультра пространство, если эта Карта принадлежит другому владельцу, чем другие карты сверхпространства, добавьте 1/2 карты Озарения в руку."
  },
  State_70600_Desc = {
    Text = "Ответ: 32 очка жизни в конце хода."
  },
  State_70600_Name = {
    Text = "Кровь благодати"
  },
  State_70602_Desc = {
    Text = "Использование Пробуждения серебряного ключа позволяет вытащить 4 карты."
  },
  State_70603_Desc = {
    Text = "Использование пробуждения серебряного ключа дает всем пробуждающим телам по 10 единиц безумия."
  },
  State_70605_Desc = {
    Text = "После использования Пробуждения серебряного ключа вы получаете 32 силы."
  },
  State_70607_Desc = {
    Text = "При разыгрывании дважды подряд карт с большим расходом вычислительной мощности, чем предыдущая Карта, получите 24/48 контратаки, максимум 5 раз за ход."
  },
  State_70609_Desc = {
