  State_70609_Name = {
    Text = "Экземпляр бабочки"
  },
  State_70611_Desc = {
    Text = "После пробуждения серебряным ключом увеличивается Базовый Урон всех пробуждающих тел на 25%/50%."
  },
  State_70614_Name = {
    Text = "Лазерная челюсть+"
  },
  State_70617_Desc = {
    Text = "Усиление урона от первых пяти атак каждый ход на 15%/30%."
  },
  State_70618_Desc = {
    Text = "В начале хода берите 1 карту."
  },
  State_70619_Desc = {
    Text = "\"Ударить\" наносит Урон в размере 10%/20% отравления, максимум 320/640 ед. за ход."
  },
  State_70620_Desc = {
    Text = "При получении атаки от врага наносит ему 1 раз <FixedDamage:чистый урон> в размере 25%/50% от нашего макс. ОЗ, этот урон получает усиление контрудара на 100%/200%, максимум 1 раз за ход для каждого врага."
  },
  State_70620_Name = {
    Text = "Утерянный жертвенный нож"
