  },
  State_70623_Desc = {
    Text = "В начале каждого хода все пробуждающие тела получают 10 безумие."
  },
  State_70624_Desc = {
    Text = "После пробуждения серебряным ключом все пробуждающие тела получают 20 единиц безумия."
  },
  State_70628_Desc = {
    Text = "В начале хода берите 2 карты."
