  State_70635_Desc = {
    Text = "Использование Пробуждения серебряного ключа дает 416 очков контратаки."
  },
  State_70636_Desc = {
    Text = "При потере жизни получите 10%/20% потери жизни в виде Багровой плавильни."
  },
  State_70637_Desc = {
    Text = "В начале боя верхний Лимит щупалец увеличивается на +1/2, получите 1/2 щупальца."
  },
  State_70641_Desc = {
