  State_70646_Name = {
    Text = "Утерянный жертвенный нож+"
  },
  State_70647_Desc = {
    Text = "Увеличение базового урона всех пробуждающих тел на 30%."
  },
  State_70648_Desc = {
    Text = "Бой начинается с наложения отравления на всех врагов на 640, Эффект удваивается в бою с лидером."
  },
  State_70656_Desc = {
    Text = "\"Ударить\" наносит дополнительно 60% урона от атакующей силы пробуждающего тела 1/2 раза, максимум 3 раза за ход."
  },
  State_70657_Desc = {
    Text = "Бой начинается, получает 32 силы."
  },
  State_70660_Desc = {
    Text = "Бой начинается, получает 64 силы."
  },
  State_70661_Desc = {
    Text = "Ответ: 64 жизни в конце хода."
  },
  State_70661_Name = {
    Text = "Кровь благодати+"
  },
  State_70662_Desc = {
    Text = "После Пробуждения серебряного ключа получите 2 единицы вычислительной мощности."
  },
  State_70664_Desc = {
    Text = "Использование серебряного ключа для пробуждения добавляет 16 силы."
  },
  State_70666_Desc = {
    Text = "Бой начинается, получите 100/200 Мастерство областей. Повышено на 10%/20% базовое отравление, наносимое всеми пробуждающими телами, и отравление, наносимое созданиями."
  },
  State_70667_Desc = {
    Text = "Очнувшись серебряного ключа дает 4 единицы вычислительной мощности."
  },
  State_70670_Desc = {
    Text = "Бой начинается с 320 контратаки, Эффект удваивается в бою с лидером."
  },
  State_70671_Desc = {
    Text = "После входа в сверхизмерение, первая сыгранная непроизводная Командная Карта дополнительно активируется 1/2 раза."
  },
  State_70678_Desc = {
    Text = "Бой начинается, получает 640 контратаки, Эффект удваивается в бою с лидером."
  },
  State_70681_Desc = {
    Text = "Все пробуждающие тела получают увеличение базового урона на 60%."
  },
  State_70682_Desc = {
    Text = "Когда количество карт в руке меньше или равно 2, тяните 1/2 карты, максимум 2 раза за ход."
  },
  State_70683_Desc = {
    Text = "Аннигиляция дает пробуждающему телу с наименьшим безумием 50/100 безумия, перезарядка 3 хода."
  },
  State_70684_Desc = {
    Text = "В начале хода, если здоровье ниже 25%, получить 72/144 временной силы."
  },
  State_70685_Desc = {
    Text = "После пробуждения серебряного ключа накладывает отравление 416 на всех врагов."
  },
  State_70686_Desc = {
    Text = "После Вознесения все враги получают <FixedDamage:Чистый урон> в размере 15%/30% от макс. ОЗ нашей стороны 1 раз, а также накладывается 10%/20% Яда."
  },
  State_70687_Name = {
    Text = "Запредельные часы+"
  },
  State_70689_Desc = {
    Text = "Использование Пробуждения серебряного ключа накладывает на всех врагов отравление 832."
  },
  State_70690_Desc = {
    Text = "После начала боя получите 100/200 Мастерство областей. Базовая Контратака всех пробуждающих тел и Контратака созданий повышены на 10%/20%."
  },
  State_70691_Desc = {
    Text = "При каждом нанесении урона получите 4/8 временная Огромная Огромная Огромная Огромная сила, максимум 15 раз за ход."
  },
  State_70693_Desc = {
    Text = "Увеличение автоматического получения при эмбриональной фузии на 100%/200%."
  },
  State_70694_Desc = {
    Text = "После пробуждения серебряного ключа взять 2 карты."
  },
  State_70695_Desc = {
    Text = "В начале каждого хода все пробуждающие тела получают 5 безумие."
  },
  State_70696_Desc = {
    Text = "После пробуждения серебряного ключа вы получаете 208 контратак."
  },
  State_70698_Desc = {
    Text = "защита получает 200/400 временной контратаки, максимум 3 раза в ход."
  },
  State_70804_Name = {
    Text = "Срок жизни"
  },
  State_70805_Desc = {
    Text = "После начала боя на всех врагов накладывается 1/2 слоя слабости, Эффект удваивается для лидера. Базовый Урон всех пробуждённых увеличивается на 15%/30%."
  },
  State_70806_Name = {
    Text = "Длань защиты+"
  },
  State_70808_Desc = {
    Text = "Использование позы Тихого моря накладывает 64/128 истощения на всех врагов, 3 хода перезарядки."
  },
  State_70809_Desc = {
    Text = "В начале хода, если жизнь ниже 25%, получает 100/200 щита."
  },
  State_70809_Name = {
    Text = "Длань защиты"
  },
  State_70810_Desc = {
    Text = "Использование стойки гневной волны сразу активирует все щупальцы для атаки врагов 1 или 2 раза, перезарядка 3 хода."
  },
  State_70812_Desc = {
    Text = "Бой начинается. Всем врагам накладывается 1/2 уровня уязвимости, для лидера Эффект удваивается. Пробуждающие тела наносят на 15%/30% больше базового урона."
  },
  State_70832_Desc = {
    Text = "Уникальное команды: в начале боя снаряженец получает безумие, равное <WeaponEffect_Num:[StateArg1]%> восстановлению ярости снаряженца. После первого использования вспышки ярости в каждом бою Эффект повторяется."
  },
  State_70832_WeaponDesc = {
    Text = "В начале боя снаряженец получает безумие, равное <WeaponEffect_Num:[StateArg1]%> восстановлению ярости снаряженца (<WeaponEffect_Num:[DescArg1]>). После первого использования вспышки безумия в каждом бою Эффект повторяется."
  },
  State_70835_Desc = {
    Text = "Уникальное команды: безумие, яд и восстановление жизни, причиненные снаряженцем, увеличиваются на <WeaponEffect_Num:[StateArg1]%>. После освобождения вспышки безумия, снаряженец получает безумие, равное расходу безумия в <WeaponEffect_Num:[StateArg2]%>."
  },
  State_70835_WeaponDesc = {
    Text = "Увеличение безумия, яда и восстановления жизни, причиняемых снаряженцем, на <WeaponEffect_Num:[StateArg1]%>. После высвобождения вспышки безумия, получает безумие, равное расходу безумия <WeaponEffect_Num:[StateArg2]%>."
  },
  State_70989_Desc = {
    Text = "После использования вспышки безумия 4 раза за ход, получите 3/6 вычислительной мощности, перезарядка 3 хода."
  },
  State_71001_Desc = {
    Text = "После разыгрывания 4 карт команды, принадлежащих разным пробуждённым в течение одного хода, все пробуждённые получают 20/40 алиемуса, перезарядка 3 хода."
  },
  State_71153_Desc = {
    Text = "В начале хода Кекес получает 15 безумия. Когда Кекес получает щит, он восстанавливает 50% от щита в виде жизни."
  },
  State_71154_Desc = {
    Text = "В начале хода Ай Джис получает 15 безумия. При этом, нанося Урон врагам с уязвимостью, она крадет у них 10 временной силы, максимум 5 раз за ход."
  },
  State_71155_Desc = {
    Text = "В начале хода Ли получает 15 Алиемус. Каждый раз, когда теряет ОЗ, получает 8 очков силы, максимум 10 раз за бой. После накопления 10 раз, цена в арифметике \"Боль и услада\" становится 1, количество урона увеличивается на 1."
  },
  State_71156_Desc = {
    Text = "В начале хода Агриппа получает 15 безумия. \"Нестерпимая щедрость\" также снижает расход вычислительной мощности Агриппы на 1 в этом ходу, максимум 1 раз за ход."
  },
  State_71157_Desc = {
    Text = "В начале хода Шань получает 15 очков безумия. Бой начинается, всем картам команды Шань присваивается \"Сохранено\", \"Подготовка 1\", и получено 24 очка щита."
  },
  State_71157_Name = {
    Text = "Измерение изображение·Шань"
  },
  State_71158_Desc = {
    Text = "В начале хода Долл получает 15 алиемуса. После начала боя цена в арифметике \"Равноценный обмен\" Долла становится равной 0, разыграв, в следующем ходу дополнительно возьмите 2 карты."
  },
  State_71159_Desc = {
    Text = "В начале хода Фалост получает 15 безумия. При каждом уроне щупальцами отравление, наносимое Фалостом в этом бою, увеличивается на 1%, максимум до 100%."
  },
  State_71160_Desc = {
    Text = "В начале хода \"24\" получает 15 единиц безумия. Если \"24\" находится в состоянии \"Депрессивная личность\", он дополнительно получает 25 единиц безумия. Если он находится в состоянии \"Маниакальная личность\", временный критический шанс и временный критический Урон \"24\" увеличиваются на 35%."
  },
  State_71161_Desc = {
    Text = "В начале хода Фэйнт получает 15 алиемуса. Каждый раз, когда активируется Сопротивление смерти, щит, Контратака и восстановление жизней, причиненные Фэйнтом в этом исследовании, увеличиваются на 20%, максимум 5 раз."
  },
  State_71162_Desc = {
    Text = "В начале хода Голиаф получает 15 Алиемуса. Если Голиаф нанесет 3 раза Урон за 1 ход, Урон Голиафа в бою получает бонус +1 к силе. Перезарядка: 3 хода."
  },
  State_71163_Desc = {
    Text = "В начале хода Кровавая цепь · Илот получает 15 Алиемус. Активный Урон Кровавой цепи · Илот добавляет 20% Кровотечения, и после убийства врага наносит Кровотечение, равное избыточному урону, остальным врагам."
  },
  State_71164_Desc = {
    Text = "В начале хода Аурита получает 15 Алиемуса. Количество урона от «Деления стрекательных клеток» увеличивается на 1, после разыгрывания «защиты» Аурита добавляет 1 карту «Деления стрекательных клеток» в свою руку."
  },
  State_71166_Desc = {
    Text = "В начале хода Лили получает 15 Алиемуса. Максимальный Уровень терпения Лили увеличивается на 100%. При использовании \"Неувядающий цветок на иле\" или \"Удар во имя защиты\" восстанавливается 8% от уровня терпения в виде ОЗ."
  },
  State_71167_Desc = {
    Text = "В начале хода Лотан получает 15 Алиемуса. После первого разыгрывания «защиты» Лотан положит в руку 2 карты с дополнительным расходом и Непокорный клинок."
  },
  State_71168_Desc = {
    Text = "В начале хода Пандия получает 15 Алиемус. В начале хода получает 64 очка контратаки. За каждые 4 очка не временной контратаки Урон от карты команды \"Пандия\" увеличивается на 1."
  },
  State_71169_Desc = {
    Text = "В начале хода Шило получает 15 безумия. Каждый раз, когда сбрасывается 1 Карта, \"Шило\" получает 5 очков безумия."
  },
  State_71170_Desc = {
    Text = "В начале хода Тави получает 15 безумия. Если за ход было сыграно 6 карт команды Тави, в руку добавляется 1 Карта \"Серебряный Погоня за светом ключа\", время перезарядки 3 хода."
  },
  State_71171_Desc = {
    Text = "В начале хода Мириам получает 15 безумия и кладет 1 карту \"таинство\" в руку."
  },
  State_71172_Desc = {
    Text = "В начале хода Долл: Преисподняя получает 15 Алиемус. После освобождения Вознесения расплавления, за каждые 20 потраченных очков Алиемус другие Пробуждённые получают 1 очко Алиемус."
  },
  State_71173_Desc = {
    Text = "В начале раунда Сальвадор получает 15 Алиемус. Каждый раз, когда вы накапливаете Багровое горнило, он также получает 5% от накопленного количества силы. \"Ударить\" и \"Конец страдания\" Сальвадора получают дополнительный бонус +1 к силе."
  },
  State_71175_Desc = {
    Text = "В начале раунда Нодира получает 15 Алиемуса. После освобождения \"вспышки безумия\" Нодира получает контратаку, равную 50% от текущего щита, максимум 1 раз за ход."
  },
  State_71177_Desc = {
    Text = "В начале хода Лиз получает 15 безумия. Эффект карт, сброшенных с помощью \"Танец смерти\", активируется дополнительно 1 раз, перезарядка 3 хода."
  },
  State_71178_Desc = {
    Text = "В начале хода Рамона получает 15 безумия. Каждый третий раз, когда вы разыгрываете карту команды Рамоны, эта Командная Карта активируется дополнительно 1 раз."
  },
  State_71179_Desc = {
    Text = "В начале хода Увхаш получает 15 Алиемус. Расход Алиемуса Увхаша снижен на 10 единиц, при каждом использовании Вознесения расход Алиемуса дополнительно снижается на 5 единиц, за ход можно использовать Вознесение 2 раза."
  },
  State_71180_Desc = {
    Text = "В начале хода Альва получает 15 Алиемуса. Если в предыдущем ходу Альва разыграла 2 карты «защита»,то добавьте в руку 1 карту с расходом «Точный взмах»; если разыграла 2 карты «ударить»,то добавьте 1 карту с расходом «Боевая стойка»."
  },
  State_71181_Desc = {
    Text = "В начале хода Сорель получает 15 Алиемуса. Каждый раз, когда Сорель наносит Урон, Слияние Зародыша +10, максимум 10 раз за ход. После 10 активаций увеличивает крит. Урон Сорель на 20% в этом бою."
  },
  State_71182_Desc = {
    Text = "В начале хода Хамлин получает 15 безумия. Расход вычислительной мощности \"Соната души\" снижается на 1, Базовый Урон увеличивается на 1 раз."
  },
  State_71183_Desc = {
    Text = "В начале хода Таис получает 15 Алиемуса. После розыгрыша 2 карт команды за 1 ход, она получает 1 карту \"Непорочное дитя\" и 72 единицы Врем. Огромная Огромная Огромная сила▼, перезарядка 3 хода."
  },
  State_71187_Desc = {
    Text = "В начале хода Хилестер получает 15 безумия. Перед концом хода за каждую карту команды Хилестера в руке одно щупальце атакует врага и восстанавливает 8 жизни."
  },
  State_71188_Desc = {
    Text = "В начале хода Морфи получает 15 безумия. «Ударить» и «защита» Морфи могут преобразовать 25% «Жертвы» в временный Урон от щупалец, но не более 1 раза за ход."
  },
  State_71189_Desc = {
    Text = "В начале хода Нимфея получает 15 Алиемуса. После розыгрыша «ударить» увеличивает отравление, наносимое Нимфеей в этом бою, на 20%, после розыгрыша «защита» активирует яд на 50% у всех врагов. Максимум 1 раз за ход для каждого эффекта."
  },
  State_71190_Desc = {
    Text = "В начале раунда Огр получает 15 единиц Алиэмиуса. После первого использования Огра \"Пробивающая пушка\" или \"Удар\" в этом раунде, щит и Огромная Огромная Огромная Огромная сила Огра увеличиваются на 50%."
  },
  State_71191_Desc = {
    Text = "В начале хода Лекк получает 15 безумия. Каждый ход результат первого броска игральной кости всегда равен 6."
  },
  State_71192_Desc = {
    Text = "В начале хода Рамона: Неизбывная получает 15 Алиемус. При первой активации \"Петля\" за ход получает 500 очков Ключесвета и 1 Уровень \"Негэнтропия\"."
  },
  State_71193_Desc = {
    Text = "В начале хода Тулу получает 15 безумия. Расход алиемуса Тулу уменьшен на 10 единиц, после освобождения вспышки безумия мгновенно генерируются 2 временных щупальца."
  },
  State_71194_Desc = {
    Text = "В начале хода Гарен получает 15 безумия. Использование \"Тихое Наблюдение\"возвращает двойной расход вычислительной мощности. Перезарядка: 3 хода."
  },
  State_71271_Desc = {
    Text = "В начале раунда Орла получает 15 Алиэмиус. В начале битвы получают по 1 слою всех эмоций. Эффект «Метафора» увеличивается на 50％."
  },
  State_71272_Desc = {
    Text = "В начале хода Дженкинс получает 15 безумия, окончательный Урон +5%. Базовый Урон и рост наносимого урона \"Коричневый в действии\" повышаются на 200%."
  },
  State_71273_Desc = {
    Text = "В начале раунда Даффодил получает 15 Алиемуса и 1 карту \"Озарение\". Каждый раз, когда вы разыгрываете \"Разнородные приливы\", Огромная Огромная Огромная Огромная сила, которую он получает, навсегда увеличивается на 25% в этом исследовании, максимум до 300%."
  },
  State_71274_Desc = {
    Text = "В начале хода Тинкт получает 15 Алиемус. После активации карты команды Тинкта Скачок она возвращается в руку, активируется не более 3 раз за ход."
  },
  State_71275_Desc = {
    Text = "В начале хода Ванда получает 15 очков Алиемуса и получает 1 Уровень \"Манок снов\". Если текущий ход является Ультра-ходом, дополнительно положите в руку 1 временную карту \"Цепи хребтовых игл\" и \"Хранительница заблудших\"."
  },
  State_71276_Desc = {
    Text = "В начале хода Эрика получает 15 алиемуса. После того, как Эрика разыграет 3 карты команды за 1 ход, она получает 1 карту \"Озарение\" и бонус к силе и Бдительности, получаемый от \"Электромагнитного разряда\", увеличивается в 2 раза."
  },
  State_71277_Desc = {
    Text = "В начале хода Касия получает 15 Алиемус. Каждый раз, когда она берет 1 карту, Касия получает 1 очко Алиемус. Когда Касия освобождает Вознесение, все враги теряют 32 очка силы."
  },
  State_71278_Desc = {
    Text = "В начале хода Уинкл получает 15 Алиемус. Каждый раз, когда другие пробуждённые используют Вознесение, Уинкл получает 5 очков Алиемус, и цена в арифметике \"Перековка психики\" снижается на 1."
  },
