  State_74771_Desc = {
    Text = "Очаг ярости, необходимый для одного освобождения вспышки безумия."
  },
  State_74771_Name = {
    Text = "Лимит алиемуса"
  },
  State_74788_Desc = {
    Text = "\n·Парадокс существования: в начале исследования 75% сопротивляемости смерти преобразуется в бонус к максимальному здоровью, до 300% сопротивляемости смерти может быть преобразовано, увеличивая максимум здоровья до 10%. Каждый раз, когда срабатывает сопротивляемость смерти, вы получите 1 карту «Сияние Серебряного Ключа».\n·Бездна шрамов: во время битвы с боссом, каждый раз, когда восстановление здоровья вашей команды достигает 100% от их максимального здоровья, последующие эффекты восстановления снижаются на 25%, но текущее общее количество сопротивляемости смерти увеличивается на 25%, максимум можно активировать 3 раза.\n·Призматическая линза: в начале хода, если Контратака превышает 750% максимального здоровья, избыточные слои уменьшаются наполовину, и постоянная Контратака может накапливаться до 2250% максимального здоровья; если яд врага превышает 1000% максимального здоровья, избыточные слои также уменьшаются наполовину, а яд может накапливаться до 3000% максимального здоровья. Пробужденное тело получает на 70% меньший бонус урона от контратаки, но весь нанесённый яд и Контратака увеличиваются на 10%. В начале хода врага, за каждое активированное восприятие духа, вы получаете временную контратаку в размере 25% текущей постоянной контратаки и активируете у всех врагов 25% яда.\n·Луч судьбы: для обычных монстров количество ходов до применения «Взгляда» увеличивается до 6. Все битвы ограничиваются 15 ходами, но в начале 15-го хода добавляется 1 Карта «Предела Луча»: энергия Серебряного Ключа и безумие всех пробужденных тел заполняются до максимума."
  },
  State_74788_Name = {
    Text = "(Временно не используется)"
  },
  State_74791_Desc = {
    Text = "\n·Гармония арифметики: когда за один ход сыграно 10 командных карт, за каждую дополнительно разыгранную командную карту получается 1 уровень «Гармонии арифметики». «Гармония арифметики» увеличивает расход арифметики на +1 за каждую разыгранную командную карту в этом ходу; каждая дополнительно потраченная единица арифметики конвертируется в ключесвет, равный 100% Восст. ключесвета пробуждённого, эффект суммируется. После активации Ультра пространства эффект Гармонии арифметики сбрасывается.\n·Переполнение арифметики: после разыгрывания карты снимает с неё эффект снижения расхода арифметики в этом ходу. Когда текущая арифметика в бою превышает 12, каждая лишняя единица автоматически конвертируется в ключесвет, равный 300% среднего Восст. ключесвета команды.\n·Гармония алиемуса: эффект повышения процента алиемуса уменьшается вдвое. После каждого Вознесения пробуждённого его Основной алиемус +10. В конце хода за каждого пробуждённого, не совершившего Вознесение, команда получает ключесвет, равный 200% среднего Восст. ключесвета команды."
  },
  State_74791_Name = {
    Text = "Ключевая гармонизация"
  },
  State_74809_Name = {
