  },
  State_74947_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: в начале хода накладывает [StateArg1] уровней Помехи на врага с <HPAndShieldMin:наименьшим количеством ОЗ и Щита>. После того как Носитель совершает убийство, эффект немедленно срабатывает ещё раз."
  },
  State_74947_Name = {
    Text = "Шляпа ведьмы с широкими полями"
  },
  State_74948_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: «Вознесение» лишает врага с наибольшим Алиемус [StateArg1] Алиемус и накладывает <PVPEmptinessKeywords:Ускользание>."
  },
  State_74948_Name = {
    Text = "Маятник гипнотизёра"
  },
  State_76236_Desc = {
    Text = "\n·Возвышение Ключесвета: когда Ключесвет заполнен, можно дополнительно выбрать «Возвышение Ключесвета», чтобы поместить карту Возвышения указанного Пробуждённого в руку и наделить её «Удержанием» — действует в течение текущего боя. «Возвышение Ключесвета» можно активировать только 1 раз за ход, откат независим от «Зова».\n·Перегрузка Ключесвета: при использовании «Возвышения Ключесвета» за каждого Пробуждённого с разблокированным Возвышением дополнительно расходуется 1000 единиц Ключесвета — этот эффект может сделать Ключесвет отрицательным.\n·Метка архива: за каждый Зов, которым владеет Хранитель, «Исследования объектов» и «Исследование духовного сознания» повышаются на 1%, максимум на 50%. Эффект всех Колёс Судьбы R изменяется: вероятность появления Реликвии Изображения измерения Носителя повышается на 100%."
  },
  State_76236_Name = {
    Text = "Сияющий серебряный блеск"
  },
  State_76277_Desc = {
    Text = "Уникальное команды: После начала битвы с лидером расходуется до 50 чёрных печатей, за каждую потраченную 1 чёрную печать получаете <WeaponEffect_Num:[StateArg1]%> <DeathResistanceIconKeywords:Сопротивление смерти>. В звёздной главе Эффект изменяется на \"Увеличивает вероятность появления реликвии изображений размерности у снаряженца на 100%\"."
  },
  State_76277_WeaponDesc = {
    Text = "После начала битвы с лидером, расходуется максимум 50 чёрных печатей, за каждую потраченную 1 чёрную печать получаете <WeaponEffect_Num:[StateArg1]%> <DeathResistanceIconKeywords:Сопротивление смерти>. В Звёздной главе Эффект изменяется на \"увеличивает вероятность появления Изображения размерности Реликвии у владельца на 100%\"."
  },
  State_76278_Desc = {
    Text = "Команда уникальна: за каждую новую клетку, по которой проходит, восстанавливается <WeaponEffect_Num:[StateArg1]%> потерянного здоровья. После использования Тела Гнозис экстренного реагирования, критический шанс и критический Урон всех пробуждённых повышаются на 100%. В Звёздной главе Эффект изменяется на \"повышение вероятности появления Изображения размерности у снаряженца на 100%\"."
  },
  State_76278_WeaponDesc = {
    Text = "При прохождении каждой новой клетки восстанавливается [StateArg1]% потерянного здоровья ([DescArg1]). После использования экстренного Гнозис критический шанс и критический Урон всех пробуждающих тел увеличиваются на 100%. В Звёздной главе Эффект изменяется на \"увеличение вероятности появления изображений размерности реликвии Снаряженца на 100%\"."
  },
  State_76279_Desc = {
    Text = "Уникальное команды: цена пробуждения Пробуждённого в следе от плавления снижена на <WeaponEffect_Num:[StateArg1]> чёрных печатей. Возжигание Гноса снаряженца получает Начальный. В Звёздной главе Эффект изменяется на \"увеличивает вероятность появления Изображения размерности Реликвии снаряженца на 100%\"."
  },
  State_76279_WeaponDesc = {
    Text = "Цена пробуждения Пробуждённого в следе от плавления снижена на <WeaponEffect_Num:[StateArg1]> чёрных печатей. Возжигание Гнозиса снаряженца получает Начальный. В Звёздной главе Эффект изменяется на \"вероятность появления Реликвии размерности снаряженца увеличивается на 100%\"."
  },
  State_76280_Desc = {
    Text = "Команда уникальна: восстановление в площадке для отдыха увеличивается на <WeaponEffect_Num:[StateArg1]%, после выбора восстановления ОЗ добавьте 2 карты \"Озарение\" в колоду. В Звёздной главе Эффект меняется на \"повышение вероятности появления реликвий размерности обладателя на 100%\"."
  },
  State_76280_WeaponDesc = {
    Text = "Увеличение восстановления в Площадке для отдыха на <WeaponEffect_Num:[StateArg1]%>. После восстановления жизни добавьте 2 карты \"Озарение\" в колоду. В Звёздной главе Эффект изменяется на \"Увеличивает вероятность появления Реликвии размерности снаряженца на 100%\"."
  },
  State_76281_Desc = {
    Text = "Уникальное команды: после завершения боя Пробуждённый с наименьшим уровнем Алиемуса получает <WeaponEffect_Num:[StateArg1]> очков Алиемуса. В Звёздной главе Эффект изменяется на \"увеличивает вероятность появления Реликвии размерности снаряженца на 100%\"."
