  State_76281_WeaponDesc = {
    Text = "После окончания боя пробуждённый с наименьшим Алиемусом получает <WeaponEffect_Num:[Energy:StateArg1]> очков безумия. В звёздной главе Эффект изменяется на \"увеличивает вероятность появления реликвии изображения размерности для снаряженца на 100%\"."
