  },
  State_76282_WeaponDesc = {
    Text = "Магазин Р-Меток: попытки обновления +1, цена обновления уменьшается на <WeaponEffect_Num:[StateArg1]> единиц чёрной Печать пакиа. В звёздной главе Эффект изменяется на \"увеличивает вероятность появления изображения размерности у снаряженца на 100%\"."
  },
  State_76283_Desc = {
    Text = "Уникальное команды: Слот реликвий изменяется на 3, одно из которых - Проклятая реликвия. После покупки проклятого существа получите <WeaponEffect_Num:[StateArg1]> чёрных печатей. В Звёздной главе Эффект изменяется на \"увеличивает вероятность появления созданий изображений размерности у снаряженца на 100%\"."
  },
  State_76283_WeaponDesc = {
    Text = "Слот реликвий становится 3, одно из которых — Проклятая реликвия. После покупки проклятого существа получите <WeaponEffect_Num:[StateArg1]> чёрных печатей. В Звёздной главе Эффект изменяется на \"увеличивает вероятность появления изображения размерности снаряженца на 100%\"."
