  State_76284_Desc = {
    Text = "Команда уникальна: после начала уровня все пробуждённые получают <WeaponEffect_Num:[StateArg1]> очков Алиемуса. После начала Босс Битвы вытяните 2 карты. В Звёздной главе Эффект изменяется на \"увеличение вероятности появления реликвии изображения размерности снаряженца на 100%\"."
