  State_76284_WeaponDesc = {
    Text = "После начала уровня все пробуждённые получают <WeaponEffect_Num:[Energy:StateArg1]> очков безумия. После начала битвы с боссом возьмите 2 карты. В звёздной главе Эффект изменяется на \"повышение вероятности появления реликвии изображения размерности снаряженца на 100%\"."
