  State_76285_WeaponDesc = {
    Text = "После начала уровня получите <WeaponEffect_Num:[StateArg1]> очков ключесвета. После начала битвы с лидером получите 2 очка арифметики. В звёздной главе Эффект изменяется на \"Увеличивает вероятность появления изображения размерности снаряженца на 100%\"."
  },
  State_76286_Desc = {
    Text = "Уникальное команды: Место отдыха дополнительно предоставляет один вариант: устранить до 3 симптомов, получить <WeaponEffect_Num:[StateArg1]> Чёрная печать. В Звёздной главе Эффект изменён на \"увеличивает вероятность появления реликвии изображений размерности обладателя на 100%\"."
  },
  State_76286_WeaponDesc = {
    Text = "Место отдыха дополнительно предоставляет вариант: удалить до 3 симптомов и получить <WeaponEffect_Num:[StateArg1]> чёрных печатей. В Звёздной главе Эффект изменён на \"увеличивает вероятность появления реликвии изображений размерности владельца на 100%\"."
  },
  State_76287_Desc = {
    Text = "Уникальное команды: количество гравировок, доступных для выбора после обычной битвы, увеличивается до 4, вероятность улучшения гравировок карты владельца составляет <WeaponEffect_Num:[StateArg1]%>. В звёздной главе Эффект изменяется на \"увеличивает вероятность появления реликвий изображения размерности владельца на 100%\"."
  },
  State_76287_WeaponDesc = {
    Text = "Количество гравировок, доступных для выбора после обычной битвы, увеличивается до 4. Вероятность улучшения гравировок карты снаряженца до высокой гравировки составляет <WeaponEffect_Num:[StateArg1]%>. В звёздной главе Эффект изменяется на \"увеличивает вероятность появления реликвии изображения размерности снаряженца на 100%\"."
  },
  State_76288_Desc = {
    Text = "Уникальное команды: после окончания битвы получите <WeaponEffect_Num:[StateArg1]> очков Ключесвет. В Звёздной главе Эффект изменяется на \"увеличивает вероятность появления реликвии измерения снаряженца на 100%\"."
  },
  State_76288_WeaponDesc = {
    Text = "После окончания боя вы получаете <WeaponEffect_Num:[StateArg1]> очков Ключесвета. В звёздной главе Эффект изменяется на \"Увеличивает вероятность появления реликвии размерности снаряженца на 100%\"."
  },
  State_76289_Desc = {
    Text = "Уникальное команды: Кругозор +1 во время исследования, после открытия поля зрения на карте получает <WeaponEffect_Num:[StateArg1]> чёрных печатей. В начале битвы с лидером накладывает <WeaknessIconKeywords:слабость> и <VulnerabilityIconKeywords:уязвимость> на всех врагов на 1 ход. В звёздной главе Эффект изменяется на \"Увеличивает вероятность появления реликвий размерности снаряженца на 100%\"."
  },
  State_76289_WeaponDesc = {
    Text = "При исследовании Кругозор +1, после открытия всего поля зрения карты получите <WeaponEffect_Num:[StateArg1]> чёрных печатей. В начале битвы с боссом накладывается <WeaknessIconKeywords:слабость> и <VulnerabilityIconKeywords:уязвимость> на всех врагов на 1 ход. В звёздной главе Эффект изменяется на \"увеличивает вероятность появления реликвии изображений размерности у снаряженца на 100%\"."
  },
  State_76290_Desc = {
    Text = "Уникальное команды: После окончания обычного боя можно выбрать отказаться от гравировки, максимальная жизнь увеличивается на <WeaponEffect_Num:[StateArg1]%>. Этот Эффект может действовать максимум 2 раза. В звёздной главе Эффект изменяется на \"Увеличивает вероятность появления реликвии изображения размерности снаряженца на 100%\"."
  },
  State_76290_WeaponDesc = {
    Text = "После окончания обычного боя можно выбрать освободить гравировку, максимальная жизнь увеличивается на <WeaponEffect_Num:[DescArg1]>. Этот Эффект может срабатывать максимум 2 раза. В звёздной главе Эффект изменяется на \"увеличивает вероятность появления реликвий изображений размерности снаряженца на 100%\"."
  },
  State_76291_Desc = {
    Text = "Команда уникальна: после начала уровня получите <WeaponEffect_Num:[StateArg1]> очков чёрной Печать пакиа. Лимит реликвий +2. В звёздной главе Эффект изменяется на \"Увеличивает вероятность появления реликвий размерности снаряженца на 100%\"."
  },
  State_76291_WeaponDesc = {
    Text = "После начала уровня получите <WeaponEffect_Num:[StateArg1]> очков чёрной Печать пакиа. Лимит реликвий +2. В звёздной главе Эффект изменён на \"увеличивает вероятность появления реликвии с изображением размерности снаряженца на 100%\"."
