  },
  State_76430_Name = {
    Text = "Размерность изображение·Лили"
  },
  State_76433_Name = {
    Text = "Гармония арифметики"
  },
  State_76434_Desc = {
    Text = "Каждый раз, когда вы разыгрываете Карту команды, если из-за арифметической гармонии был дополнительно потрачен расход, вы получаете дополнительно 100% Ключесвета подзарядки пробуждённого, что может накапливаться."
  },
  State_76434_Name = {
    Text = "Гармония арифметики"
  },
  State_76435_Name = {
    Text = "Призматическая линза"
  },
  State_76528_Name = {
    Text = "Эта Карта считается \"ударить\"."
  },
  State_76529_Desc = {
    Text = "При подборе выберите карту пробуждённого, чтобы уменьшить ее расход вычислительной мощности на 1, после разыгрывания вытяните 1 карту и считайте ее \"ударить\"."
  },
  State_76533_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>：При экипировке и в конце хода дайте противнику случайные [StateArg1] карты с [StateArg2] слоями <PVPAcheKeywords:Скрытая боль>。"
  },
  State_76533_Name = {
    Text = "Сокрытое страдание"
  },
  State_76553_Desc = {
    Text = "Эта Карта требует расход вычислительной мощности -[StateArg1]."
  },
  State_76553_Name = {
    Text = "Миллион воздыхающих взглядов"
  },
  State_77686_Name = {
    Text = "Полумеханическая форма"
  },
  State_77688_Desc = {
    Text = "В начале пятого хода или при предстоящей смерти, Иммунитет к смерти, изменив намерение на \"Механическое вознесение\"."
  },
  State_77688_Name = {
    Text = "Слабость плоти"
  },
  State_77690_Desc = {
    Text = "После переключения на \"Полумеханическая форма\", за каждый Уровень \"Конец\" дополнительно получаете 10% от максимального здоровья. В состоянии \"Полумеханическая форма\" \"Расплавление · дора\" будет выпускать более угрожающие навыки с увеличением уровней \"Конец\"."
  },
  State_77690_Name = {Text = "Конец"},
  State_77692_Desc = {
    Text = "В конце хода призвать 2 растворяющихся монстра, максимум 2 одновременно. После смерти призванных растворяющихся монстров \"Расплавление · дора\" теряет 5% максимального здоровья."
  },
  State_77692_Name = {
    Text = "Ворота бездны"
  },
  State_77693_Desc = {
    Text = "После смерти \"Расплавление·Дора\" теряет 5% максимального здоровья."
  },
  State_77693_Name = {
    Text = "Расплавление"
  },
  State_78102_Desc = {
    Text = "Наносимый Урон снижен на 15%, Увеличение получаемого урона на 30%, длится до конца боя."
  },
  State_78102_Name = {
    Text = "Паралич разгона"
  },
  State_78694_Desc = {
    Text = "Получите [Arg1] очков силы в начале битвы. В начале хода за каждые [Arg2] единиц постоянной силы получите [Arg3] единиц временной силы, максимум [Arg4] единиц временной силы, и в конце хода потеряйте половину щита, полученного от этой реликвии временной силы."
  },
  State_78696_Desc = {
    Text = "После пробуждения серебряного ключа выберите соответствующего Пробуждённого [Arg1] \"Навыков\" и потратьте их, а затем перетасуйте [Arg2] копии дополнительных расходов в колоду для розыгрыша."
  },
  State_78697_Desc = {
    Text = "В начале хода на вас накладывается [Arg2] слоев яда, за каждое свободное место в ультрапространстве получаете [Arg1] очков силы."
  },
  State_78698_Desc = {
    Text = "Лимит арифметики -[Arg1]. За каждую разыгранную карту с ценой в арифметике не менее [Arg2] получите 1 единицу арифметики, максимум [Arg3] раз за ход."
  },
  State_78699_Desc = {
    Text = "После вытягивания карт дополнительно вытянуть [Arg1] карту, но выбросить [Arg2] карты из руки."
  },
  State_78700_Desc = {
    Text = "Увеличение базового урона всех пробуждённых на [Arg1]%, при каждом сбросе колоды дополнительно увеличивается на [Arg2]%, но 1 Карта \"Потрясение\" добавляется в руку, максимальное увеличение составляет [Arg3]%."
  },
  State_78701_Desc = {
    Text = "В начале хода: если у вас более [Arg1] постоянных щупалец, теряете [Arg2] щупальца и получаете [Arg3] временных щупалец. В противном случае получаете [Arg4] временных щупалец."
  },
  State_78702_Desc = {
    Text = "После пробуждения ключесвета дополнительно расходуется [Arg1] очков ключесвета, в результате чего стоимость вычислительной мощности карт возжигания становится равной 0, а после розыгрыша соответствующий пробуждённый получает дополнительно [Arg2] очков алиемуса."
  },
  State_78703_Desc = {
    Text = "В начале боя нанести всем врагам [Arg1] единиц отравления. Перед началом хода снять [Arg2]% отравления у врагов и наложить [Arg3]% от снятого количества кровотечения."
  },
  State_78710_Desc = {
    Text = "Каждый раз, когда разыгрывается Командная Карта, соответствующий Пробуждённый в этом ходу получает увеличение итогового урона на [Arg1]%, но теряет [Arg2] очков Алиемуса, максимальное количество срабатываний за ход — [Arg3] раз."
  },
  State_78712_Desc = {
    Text = "В начале хода Степень слияния эмбриона увеличивается на [Arg1], ваш эмбрион будет сброшен в конце хода."
  },
  State_78713_Desc = {
    Text = "В начале хода получить [Arg1] очков контратаки. После применения [Arg2] раз вспышки безумия за ход, удалить [Arg3]% постоянной контратаки, получить временную контратаку в размере [Arg4]% от удаленной суммы, перезарядка [Arg5] ходов."
  },
  State_78781_Desc = {
    Text = "Временно уменьшить силу цели и получить эквивалентную временную силу."
  },
  State_78781_Name = {
    Text = "<TouquKeywords: Кража>"
  },
  State_79405_Desc = {
    Text = "После розыгрыша \"Чистые Воспоминания\" увеличивается на 1, при достижении 10 фиксируется на 1 ход и получает 3 карты \"Озарение\", в начале следующего хода сбрасывается до 5."
  },
  State_79405_Name = {
    Text = "Истинное прошлое"
  },
  State_79406_Desc = {
    Text = "После разыгрывания \"Чистые Воспоминания\" уменьшите на 1, когда достигнет 0, заблокируйте на 1 ход и дайте всем Пробуждённым 30 очков Алиемус. В начале следующего хода сбросьте до 5."
  },
  State_79406_Name = {
    Text = "Помпезный сон-наваждение"
  },
  State_80052_Desc = {
    Text = "Тестирование"
  },
  State_80052_Name = {
    Text = "Тестирование123"
  },
  State_80052_WeaponDesc = {
    Text = "Тестирование"
  },
  State_80161_Desc = {
    Text = "Команда уникальна: Базовый Урон, нанесённый «вспышкой безумия» снаряженца, увеличивается на <WeaponEffect_Num:[StateArg1]%>, а заряд ключа повышается на <WeaponEffect_Num:[StateArg2]%>. После перехода в ультра-ход все пробуждённые получают <WeaponEffect_Num:[StateArg4]> очков Алиемуса. После освобождения\"Аннигиляция\"снаряженец получает <WeaponEffect_Num:[StateArg3]> очков Алиемуса."
  },
  State_80161_WeaponDesc = {
    Text = "Базовый Урон, наносимый вспышкой безумия носителя, увеличивается на <WeaponEffect_Num:[StateArg1]%>, заряд серебряного ключа увеличивается на <WeaponEffect_Num:[DescArg1]>. После входа в ультра-ход все пробуждённые получают <WeaponEffect_Num:[StateArg4]> очков алиемуса. После освобождения \"аннигиляции\" носитель получает <WeaponEffect_Num:[StateArg3]> очков алиемуса."
  },
  State_80174_Desc = {
    Text = "Команда уникальна: заряд серебряного ключа снаряженца увеличивается на <WeaponEffect_Num:[StateArg1]%>. После начала первого боя на всех врагов накладывается 1 слой слабости и уязвимости."
  },
  State_80174_WeaponDesc = {
    Text = "Восст. ключесвета увеличивается на <WeaponEffect_Num:[DescArg1]>. После начала первой битвы на всех врагов накладывается 1 слой слабости и уязвимости."
  },
  State_80207_Desc = {
    Text = "Если после розыгрыша этой карты срабатывает «Мерцание измерений», срабатывает последующий Эффект. При извлечении из сверхпространства расход арифметики уменьшается на 1."
  },
  State_80207_Name = {
    Text = "<WormholeKeywords:Ультрадистанция>"
  },
  State_80328_Desc = {
    Text = "Её эмоции, когнитивные способности и всё остальное навсегда связаны с волей улья. Может складываться до 15 слоёв. \"Согласие\" может быть преобразовано безумным взрывом Клементины \"Восстановление жизни\" в отрицательный Эффект."
  },
  State_80328_Name = {
    Text = "Эмпатия"
  },
  State_80331_Desc = {
    Text = "Под воздействием коррозии роя твои слабости обнажены. Активный урон и урон щупалец, полученные в этом ходу, увеличены на [DescArg1]%."
  },
  State_80331_Name = {
    Text = "<D13Colour:психическая Травма>"
  },
  State_80332_Desc = {
    Text = "Её эмоции, когниции и всё остальное навсегда связаны с Волей Улья, максимум до 10 стаков. \"Эмпатия\" может быть преобразована в негативный Эффект с помощью взрыва Алиемуса Клементины \"Воссоздание формы жизни\"."
  },
  State_80332_Name = {
    Text = "Эмпатия"
  },
  State_80335_Desc = {
    Text = "Под воздействием коррозии роя твои слабости обнажены. Активный урон и урон щупалец, полученные в этом ходу, увеличены на [DescArg1]%."
  },
  State_80335_Name = {
    Text = "<D13Colour:психическая Травма>"
  },
  State_80336_Desc = {
    Text = "Под воздействием коррозии роя твой страх не скрыть. Активный урон и урон щупалец, нанесённые в этом ходу, снижены на [DescArg1]%."
  },
  State_80336_Name = {
    Text = "<D13Colour:фиксация страха>"
  },
  State_80338_Desc = {
    Text = "Под воздействием коррозии роя твой страх не скрыть. Активный урон и урон щупалец, нанесённые в этом ходу, снижены на [DescArg1]%."
  },
  State_80338_Name = {
    Text = "<D13Colour:фиксация страха>"
  },
  State_80575_Desc = {
    Text = "После получения активного урона или урона от щупалец удаляется эквивалентное количество \"Древних углей\" и теряется 300% от удаляемого количества жизней; при получении другого урона удаляется половина. Уровни \"Древних углей\" сбрасываются в каждом раунде."
  },
  State_80575_Name = {
    Text = "Угли былого"
  },
  State_80644_Name = {
    Text = "Состояние@Свет трансцендентности"
  },
  State_80773_Desc = {
    Text = "При получении эффекта Сила▼ сила снижается лишь на 50% уровней. В свой ход получаемый урон, не являющийся активным или уроном щупалец, увеличен на 100%."
  },
  State_80773_Name = {
    Text = "Антитела иного измерения"
  },
  State_80774_Desc = {
    Text = "После получения активного урона или ущерба от щупалец удаляется эквивалентное количество \"Древних углей\" и теряется 300% от удаленного количества жизней, при получении другого урона удаляется половина. Уровни \"Древних углей\" сбрасываются в каждом раунде. После полного удаления \"Древних углей\" получить 50 уровней \"Крепости\"."
  },
  State_80774_Name = {
    Text = "Угли былого"
  },
  State_80777_Desc = {
    Text = "При начале битвы снизь критический шанс всех Пробудивших на 10%. После смерти остальные союзники получают [DescArg1] силы и [DescArg2] уровней «Старых углей»."
  },
  State_80777_Name = {
    Text = "Эмпатия улья: наследие"
  },
  State_80778_Desc = {
    Text = "После смерти другие союзники получают 1 уровень временного <MadnessIconKeywords:Безумия>."
  },
  State_80778_Name = {
    Text = "Эмпатия улья: слияние"
  },
  State_80782_Desc = {
    Text = "Во время этой битвы критический шанс всех Пробудивших понижен на [Layer]%."
  },
  State_80782_Name = {
    Text = "Снижение крит. шанса"
  },
  State_80783_Desc = {
    Text = "В конце хода получает 1 уровень <MadnessIconKeywords:Безумия>."
  },
  State_80783_Name = {
    Text = "Узы родства"
  },
  State_80784_Desc = {
    Text = "При жизни ниже 50% призыв одного «Первоначального Превращенца» сзади, срабатывает только 1 раз за бой."
  },
  State_80784_Name = {
    Text = "Эмпатия улья: Расщепление"
  },
  State_80785_Desc = {
    Text = "При снижении Силы снижается лишь 50% уровней Силы. Каждый раз, когда игрок использует Вознесение, получает 1 уровень Временного <MadnessIconKeywords:Безумия>."
  },
  State_80785_Name = {
    Text = "Эмпатия улья: иное измерение"
  },
  State_80788_Desc = {
    Text = "При снижении Силы снижается лишь 25% уровней Силы. Каждый раз, когда игрок использует Вознесение, получает 1 уровень Временного <MadnessIconKeywords:Безумия>."
  },
  State_80788_Name = {
    Text = "Эмпатия улья: иное измерение"
  },
  State_80789_Desc = {
    Text = "Получаемый активный урон и урон щупалец увеличены на 100%, длится 1 ход."
  },
  State_80789_Name = {
    Text = "Спячка"
  },
  State_80790_Desc = {
    Text = "После трансформации каждый Уровень пустотной энергии делает его совершенным…"
  },
  State_80790_Name = {
    Text = "Космический эфир"
  },
  State_80792_Desc = {
    Text = "Каждый раз, когда игрок активирует Вознесение, получает 1 уровень временного <MadnessIconKeywords:Безумия>."
  },
  State_80792_Name = {
    Text = "Эмпатия улья: иное измерение"
  },
  State_80794_Desc = {
    Text = "Карта не может быть разыграна и всё еще остается на руках в конце хода."
  },
  State_80794_Name = {
    Text = "<Boundkeywords:Связывание>"
  },
  State_80807_Desc = {
    Text = "В начале пятого раунда или когда собираетесь умереть, устраните всех других врагов и переключите намерение на«Момент трансформации»."
  },
  State_80807_Name = {
    Text = "Момент Метаморфозы"
  },
  State_80809_Desc = {
    Text = "В конце раунда карты с иллюзиями в руке будут сброшены."
  },
  State_80809_Name = {
    Text = "<PVPVoidKeyColour:Ничто>"
  },
  State_80810_Desc = {
    Text = "После получения активного урона или ущерба от щупалец удалите эквивалентное количество \"Древних углей\" и потеряйте 300% от количества удаляемого здоровья, при получении другого урона удаляется половина. Уровни \"Древних углей\" сбрасываются в конце каждого хода."
  },
  State_80810_Name = {
    Text = "Угли былого"
  },
  State_80827_Desc = {
    Text = "Каждый раз, когда разыгрывается 15 карт, замените текущие намерения на «Травматический Удар» (в текущем оставшиеся [Layer] карт)."
  },
  State_80827_Name = {
    Text = "Гневное наказание"
  },
  State_81022_WeaponDesc = {
    Text = "При каждом получении 1 урона всем пробуждающим телам добавляется 1 единица безумия."
  },
  State_81027_Desc = {
    Text = "Эта Карта принадлежит «Насекомоподобное», стоимость арифметики –1, после разыгрывания будет «измотана»."
  },
  State_81027_Name = {
    Text = "Ритуал жизни"
  },
  State_81054_Desc = {
    Text = "Под воздействием коррозии роя твой страх не скрыть. За каждый уровень активный урон и урон щупалец, наносимые в этом ходу, снижаются на 3%, максимум 15 уровней."
