  State_81058_Desc = {
    Text = "Её эмоции, восприятие и всё остальное находятся в вечной связи с Волей Улья. \"Эмпатия\" может быть преобразована в негативный Эффект с помощью взрыва безумия Клементины \"Воссоздание формы жизни\", максимум до 15 стаков."
