  State_84255_Desc = {
    Text = "Уникальное команды: в начале битвы получите щит, равный силе защиты снаряженца <WeaponEffect_Num:[StateArg1]%.> После срабатывания сопротивления смерти этот Эффект срабатывает снова в начале следующего хода."
  },
  State_84255_Name = {
    Text = "Штурман в открытом море"
  },
  State_84255_WeaponDesc = {
    Text = "В начале битвы получите <WeaponEffect_Num:[Block:DescArg1]> пунктов Щита. После срабатывания сопротивления смерти этот Эффект срабатывает снова в начале следующего хода."
  },
  State_84257_Desc = {
    Text = "Команда уникальна: щит, созданный вспышкой безумия носителя, увеличивается на <WeaponEffect_Num:[StateArg1]%>, после освобождения вспышки безумия временный критический Урон всех пробуждённых увеличивается на <WeaponEffect_Num:[StateArg2]%>, за каждое щупальце дополнительно увеличивается на 1%. При первом срабатывании сопротивления смерти в каждом исследовании, в начале следующего хода восстанавливается <WeaponEffect_Num:[StateArg3]%> от максимального здоровья."
  },
  State_84257_WeaponDesc = {
    Text = "Щит, создаваемый Вознесением снаряженца, увеличивается на <WeaponEffect_Num:[StateArg1]%. После освобождения Вознесения временный критический Урон всех пробуждённых увеличивается на <WeaponEffect_Num:[StateArg2]%, а за каждое щупальце дополнительно увеличивается на 1%. При первом активации сопротивления смерти в каждом исследовании, в начале следующего хода восстанавливается <WeaponEffect_Num:[StateArg3]%> от максимального здоровья."
  },
  State_84272_Desc = {
    Text = "<PVPWeaponKeywords:Колесо судьбы>：В конце хода восстановите <Heal:[Heal:StateArg1]> здоровья дружественному персонажу с наибольшей потерей здоровья。"
