  State_89447_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: Лимит карт в руке + [StateArg2]. После «Вознесения» получите [StateArg1] арифметики."
  },
  State_89447_Name = {
    Text = "Невыносимая свобода"
  },
  State_89448_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: В конце хода союзник с наименьшими ОЗ и щитом получает [StateArg1] <PVPDerivativeCardKeywords_16:«Чёрное перо»>."
  },
  State_89448_Name = {
    Text = "Одинокое перо"
  },
  State_89554_Name = {
    Text = "Световой конус судьбы"
  },
  State_89555_Desc = {
    Text = "Уникальное команды: после Вознесения Носителя Базовый урон Вознесения увеличивается на <WeaponEffect_Num:[StateArg1]%>, Повышение щита и восстановления ОЗ увеличивается на <WeaponEffect_Num:[StateArg2]%>, максимум 5 раз. Связь, получаемая Носителем при исследовании, увеличивается на <WeaponEffect_Num:[StateArg3]%>."
  },
  State_89555_WeaponDesc = {
    Text = "После освобождения вспышка безумия у носителя Базовый Урон от вспышки безумия увеличивается на <WeaponEffect_Num:[StateArg1]%, Лечение щита и жизни повышается на <WeaponEffect_Num:[StateArg2]%, максимум 5 стаков. После завершения исследования, Связать, полученная носителем, увеличивается на <WeaponEffect_Num:[StateArg3]%."
  },
  State_89557_Name = {
    Text = "Призматическая линза"
  },
  State_89559_Desc = {
    Text = "\n·Парадокс бытия: В начале исследования 75% Сопротивления смерти преобразуется в бонус к Макс. ОЗ, максимум 300% Сопротивления смерти, максимальный прирост Макс. ОЗ — 10%. При каждом срабатывании Сопротивления смерти дополнительно помещает 1 карту «Серебрянный Ключ Блеск» в руку.\n·Бездонная рана: В Битве с боссом каждый раз, когда суммарное Лечение ОЗ нашей стороны достигает 100% от максимума ОЗ, эффективность последующего Лечения ОЗ снижается на 25%, но общее текущее Сопротивление смерти повышается на 25%; срабатывает не более 3 раз.\n·Призматическая линза: В начале хода, если Контратака превышает 2000% от максимума ОЗ, уровни превышения уменьшаются вдвое, а постоянная Контратака накапливается не более чем до 6000% от максимума ОЗ; если Яд на враге превышает 3000% от максимума ОЗ, уровни превышения уменьшаются вдвое, а Яд накапливается не более чем до 9000% от максимума ОЗ. Усиление урона Пробуждённого от Контратаки снижается на 70%, однако весь наносимый Яд и Контратака повышаются на 10%. При каждом Пробуждении Пробуждённого: после конца хода получается Временная Контратака в размере 25% текущей постоянной Контратаки; в конце хода противника дополнительно срабатывает 25% Яда на всех врагах.\n·Световой конус судьбы: Количество ходов, в течение которых обычные монстры применяют «Взгляд», становится равным 6. В начале 15-го хода помещает 1 карту «Грань Светового Конуса» в руку: заполняет Ключесвет и Алиемус всех Пробуждённых до максимума."
  },
  State_89559_Name = {
    Text = "Искривление пространства и времени"
  },
  State_89567_Desc = {
    Text = "Эта Карта требует расход вычислительной мощности -[StateArg1]."
  },
  State_89567_Name = {
    Text = "Воскрешение в погибшей земле"
  },
  State_89568_Desc = {
    Text = "<PVPWeaponKeywords:Колесо Судьбы>: После смерти снаряженца перемешайте все карты \"Умение\" с расходом арифметики -[StateArg1] в колоду для розыгрыша, а владельцем станет союзник с наибольшей оставшейся жизнью."
  },
  State_89568_Name = {
    Text = "Воскрешение в погибшей земле"
  },
  State_89571_Name = {
    Text = "\"Горящий театр\""
  },
  State_89572_Desc = {
    Text = "В начале хода случайно добавьте <BurningKeywords:сжигать> к [DescArg1] картам в руке и получите [DescArg2] временной силы. Каждые 2 хода количество карт с эффектом сжигания увеличивается на 1, а получаемая временная Огромная Огромная Огромная Огромная сила увеличивается на [DescArg3]."
  },
  State_89572_Name = {
    Text = "\"Горящий театр\""
  },
  State_89626_Desc = {
    Text = "После пробуждения серебряным ключом получите 1 карту\"Серебрянный Ключ Блеск\".После завершения пробуждения всех пробуждённых в начале каждого хода обнаружьте случайную 1 карту поддержки пробуждённого."
  },
  State_89631_Desc = {
    Text = "Дополнительный [Layer] прыжок"
  },
  State_89634_Desc = {
    Text = "Очнувшись Гнозиса 4"
  },
  State_89634_Name = {
    Text = "Очнувшись Гнозиса 4"
  },
  State_89637_Desc = {
    Text = "Каждая первая Командная Карта в каждом ходе дополнительно действует 1 раз. При Аннигиляции создаётся 1 Щупальце. После переключения Щупальца на стойку \"Девятый вал\" эффекты Скачка для следующих 2-х карт команды обязательно активируются и переходят в Ультра пространство, перезарядка 3 хода."
  },
  State_89640_Desc = {
    Text = "Мастерство царства увеличивается на 200 очков. При расходе Багрового очага увеличивает расход на 15% ущерба от щупалец. Каждый раз при атаке щупальцем накапливается [Arg3] очков Багрового очага."
  },
  State_89642_Desc = {
    Text = "Лимит руки +2, после активации Алиэмиуса временный итоговый Урон увеличивается на 10%. Когда Карта попадает в Ультра пространство, 1 \"Зародыш\" в руке преобразуется в \"Непорочное дитя\". Каждый раз, когда генерируется 1 \"Зародыш\", стоимость вычислительной мощности одной случайной карты из сверхпространства уменьшается на 1."
  },
  State_89669_Desc = {
    Text = "Очнувшись серебряного ключа 4"
  },
  State_89669_Name = {
    Text = "Очнувшись серебряного ключа 4"
  },
  State_89759_Desc = {
    Text = "После освобождения ключа, Рамона получает 50% временного критического шанса."
  },
  State_89759_Name = {
    Text = "Драгоценные узы"
  },
  State_90023_Name = {
    Text = "Состояние для конфигурационного таблицы постоянных, временно отклонено."
  },
  State_90059_Desc = {
    Text = "При получении активного урона или урона от щупалец в этом ходу удаляется эквивалентное количество коррозии и теряется [DescArg1]% от удалённого количества здоровья; при получении другого урона удаляется 50% от количества урона коррозии."
  },
  State_90059_Name = {
    Text = "Коррозия"
  },
  State_90094_Name = {
    Text = "Ониксовое перо"
  },
  State_90218_Desc = {
    Text = "Уникальное команды: лимит руки +2, эффекты одного типа не накладываются. Щит и Базовый Урон, наносимые снаряженцем, увеличиваются на <WeaponEffect_Num:[StateArg1]%>, после входа в ультра-ход получает <WeaponEffect_Num:[StateArg2]> очков алиемуса. После использования \"Аннигиляция\" все пробуждённые временный критический Урон +<WeaponEffect_Num:[StateArg3]%, перезарядка 3 хода."
  },
  State_90218_WeaponDesc = {
    Text = "Лимит руки +2, эффекты одного типа не накладываются. Щит и Базовый Урон, наносимые снаряженцем, увеличиваются на <WeaponEffect_Num:[StateArg1]%>, после входа в Ультра ход получает <WeaponEffect_Num:[StateArg2]> очков Алиемуса. После использования \"Аннигиляция\" все пробуждённые получают временный критический Урон +<WeaponEffect_Num:[StateArg3]%>, перезарядка 3 хода."
